#!/usr/bin/env bash
# =============================================================================
#  Pingify - point-to-point tunnel manager for Iran <-> Kharej server pairs
#  https://github.com/GreatTeejay/Pingify
#
#  This file is generated by build.sh: it bundles the manager and the whole Go
#  core source, so a single file is everything either server needs.
#  Edit parts/*.sh and core/*.go, then run build.sh - never edit Pingify.sh.
# =============================================================================

PINGIFY_VERSION="5.19.2"
PINGIFY_REPO="GreatTeejay/Pingify"

# Everything Pingify owns lives in one directory, so it is obvious what is
# installed and trivial to back up or delete.
BASE_DIR="/root/Pingify"
CFG_DIR="$BASE_DIR"
STATE_DIR="$BASE_DIR/.state"
SRC_DIR="$BASE_DIR/.build"
CORE_BIN="$BASE_DIR/pingify-core"
SELF_BIN="/usr/local/bin/pingify"   # has to be on PATH for the "pingify" command
UNIT_DIR="/etc/systemd/system"
SYSCTL_FILE="/etc/sysctl.d/99-pingify.conf"
# AmneziaWG reads its interface config from a file, and awg-quick names the
# interface after that file, so ours live under Pingify's own directory.
AWG_DIR="$BASE_DIR/awg"
GO_MIN_MINOR=19          # the core needs Go 1.19 or newer
GO_FALLBACK="go1.22.12"  # used only when the version index is unreachable

# ---------------------------------------------------------------------------
# palette
# ---------------------------------------------------------------------------

if [ -t 1 ] && [ "${NO_COLOR:-}" = "" ] && [ "${TERM:-dumb}" != "dumb" ]; then
    C_OFF=$'\033[0m';   C_B=$'\033[1m';    C_DIM=$'\033[2m'
    C_RED=$'\033[31m';  C_GRN=$'\033[32m'; C_YEL=$'\033[33m'
    C_BLU=$'\033[34m';  C_MAG=$'\033[35m'; C_CYN=$'\033[36m'
    C_GRY=$'\033[90m'
else
    C_OFF=""; C_B=""; C_DIM=""; C_RED=""; C_GRN=""; C_YEL=""
    C_BLU=""; C_MAG=""; C_CYN=""; C_GRY=""
fi

# Box drawing degrades to ASCII on a console that is not talking UTF-8, so a
# bare serial session still renders something sane.
PINGIFY_UTF8=0
case "${LC_ALL:-${LC_CTYPE:-${LANG:-}}}" in
    *[Uu][Tt][Ff]*) PINGIFY_UTF8=1 ;;
esac

if [ "$PINGIFY_UTF8" = "1" ]; then
    BX_H='─'; BX_V='│'; BX_TL='╭'; BX_TR='╮'; BX_BL='╰'; BX_BR='╯'
    BX_DOT='·'; BX_ARR='▸'; BX_ON='●'; BX_OFF='○'
    MK_OK='✓'; MK_NO='✗'; MK_WARN='!'
else
    BX_H='-'; BX_V='|'; BX_TL='+'; BX_TR='+'; BX_BL='+'; BX_BR='+'
    BX_DOT='.'; BX_ARR='>'; BX_ON='*'; BX_OFF='o'
    MK_OK='+'; MK_NO='x'; MK_WARN='!'
fi

UI_W=64   # inner width of every panel, so the whole UI lines up

# ---------------------------------------------------------------------------
# drawing primitives
# ---------------------------------------------------------------------------

repeat() { local i n="$2" out=""; for ((i = 0; i < n; i++)); do out="$out$1"; done; printf '%s' "$out"; }

# Visible length, ignoring colour escapes - needed to pad a coloured string.
# Done with parameter expansion rather than sed: the live dashboard redraws
# every two seconds and a subprocess per cell adds up on a small VPS.
vislen() {
    local s="$1" out="" esc=$'\033['
    while [ "${s#*"$esc"}" != "$s" ]; do
        out="$out${s%%"$esc"*}"
        s="${s#*"$esc"}"
        s="${s#*m}"
    done
    out="$out$s"
    printf '%s' "${#out}"
}

pad_to() {
    local s="$1" w="$2" n; n="$(vislen "$s")"
    printf '%s' "$s"
    [ "$n" -lt "$w" ] && repeat ' ' $((w - n))
}

# ---------------------------------------------------------------------------
# round trip time
#
# The number on its own means nothing to most people looking at it. What they
# want to know is whether it is normal for this path, so the bands are drawn
# where an Iran <-> abroad tunnel changes character rather than at round
# numbers:
#
#   under 100 ms   a European or nearby datacentre behaving itself
#   100 - 200 ms   usable, but interactive traffic feels it
#   over 200 ms    either a very long way round, or the path is in trouble
#
# A tunnel that is down has no round trip at all, and that is dim, not red -
# red here should mean "this path is slow", not "there is no path".
# ---------------------------------------------------------------------------
# An address is the thing on these screens people copy, compare and mistype,
# so it gets a colour of its own rather than sitting in the same weight as the
# words around it.
addr_tint() { printf '%s%s%s' "$C_CYN" "$1" "$C_OFF"; }

rtt_colour() {
    local ms="${1%ms}"; ms="${ms%%.*}"
    case "$ms" in
        '' | *[!0-9]*) printf '%s' "$C_DIM"; return ;;
    esac
    if   [ "$ms" -lt 100 ]; then printf '%s' "$C_GRN"
    elif [ "$ms" -lt 200 ]; then printf '%s' "$C_YEL"
    else                         printf '%s' "$C_RED"
    fi
}

# rtt_tint prints the value already wrapped in its colour.
rtt_tint() { printf '%s%s%s' "$(rtt_colour "$1")" "$1" "$C_OFF"; }

# true when the path is slow enough to be worth a word of explanation
rtt_slow() {
    local ms="${1%ms}"; ms="${ms%%.*}"
    case "$ms" in '' | *[!0-9]*) return 1 ;; esac
    [ "$ms" -ge 200 ]
}

# A panel carries its title in the top border, so a screen full of them reads
# as a list of labelled blocks rather than a wall of rules.
panel() {
    local t="${1:-}" n
    if [ -z "$t" ]; then
        printf '  %s%s%s%s%s\n' "$C_GRY" "$BX_TL" "$(repeat "$BX_H" "$UI_W")" "$BX_TR" "$C_OFF"
        return
    fi
    # corner + one rule + " title " ; the rest of the line is rule + corner
    n=$(( ${#t} + 3 ))
    printf '  %s%s%s %s%s%s %s%s%s\n' \
        "$C_GRY" "$BX_TL$BX_H" "$C_OFF" "$C_CYN$C_B" "$t" "$C_OFF" \
        "$C_GRY" "$(repeat "$BX_H" $((UI_W - n)))$BX_TR" "$C_OFF"
}

panel_end() { printf '  %s%s%s%s%s\n' "$C_GRY" "$BX_BL" "$(repeat "$BX_H" "$UI_W")" "$BX_BR" "$C_OFF"; }

row() {
    printf '  %s%s%s %s %s%s%s\n' \
        "$C_GRY" "$BX_V" "$C_OFF" "$(pad_to "$1" $((UI_W - 2)))" "$C_GRY" "$BX_V" "$C_OFF"
}

# field <label> <value> [label2] [value2] - two aligned columns in one row.
field() {
    local s
    s="$(pad_to "${C_DIM}$1${C_OFF}" 13)${C_B}$2${C_OFF}"
    if [ -n "${3:-}" ]; then
        s="$(pad_to "$s" 32)$(pad_to "${C_DIM}$3${C_OFF}" 12)${C_B}$4${C_OFF}"
    fi
    row "$s"
}

# kept so older call sites keep working
box_top() { panel; }
box_bot() { panel_end; }
box_row() { row "$1"; }

say()  { printf '%s\n' "$*"; }
info() { printf '  %s%s%s %s\n' "$C_CYN" "$BX_ARR" "$C_OFF" "$*"; }
ok()   { printf '  %s%s%s %s\n' "$C_GRN" "$MK_OK" "$C_OFF" "$*"; }
warn() { printf '  %s%s%s %s\n' "$C_YEL" "$MK_WARN" "$C_OFF" "$*"; }
fail() { printf '  %s%s%s %s\n' "$C_RED" "$MK_NO" "$C_OFF" "$*"; }
dim()  { printf '    %s%s%s\n' "$C_DIM" "$*" "$C_OFF"; }
rule() { printf '  %s%s%s\n' "$C_GRY" "$(repeat "$BX_H" $((UI_W + 2)))" "$C_OFF"; }

# A section heading whose rule runs out to the panel width.
head2() {
    local t=" $1 " n; n="$(vislen "$t")"
    printf '\n  %s%s%s%s%s%s%s\n\n' \
        "$C_GRY" "$BX_H$BX_H" "$C_OFF$C_CYN$C_B" "$t" "$C_OFF$C_GRY" \
        "$(repeat "$BX_H" $((UI_W - n)))" "$C_OFF"
}

# A label above a run of related menu entries.
group() { printf '\n  %s%s%s\n' "$C_DIM$C_B" "$1" "$C_OFF"; }

# item <key> <label> [hint]
#
# The label column grows if a label outruns it, so a long one can never end up
# glued to its hint.
item() {
    local w=24 n
    n="$(vislen "$2")"
    [ "$n" -ge "$w" ] && w=$((n + 2))
    if [ -n "${3:-}" ]; then
        printf '    %s%s%s %s%s%s %s%s%s\n' \
            "$C_CYN$C_B" "$1" "$C_OFF" "$C_GRY" "$BX_ARR" "$C_OFF" \
            "$(pad_to "$2" "$w")" "$C_DIM" "$3$C_OFF"
    else
        printf '    %s%s%s %s%s%s %s\n' \
            "$C_CYN$C_B" "$1" "$C_OFF" "$C_GRY" "$BX_ARR" "$C_OFF" "$2"
    fi
}

# ---------------------------------------------------------------------------
# the wizard
#
# The steps run down one page. Nothing is cleared between them, so the answers
# already given stay on screen above the question being asked - which is what
# you want when you are copying the same numbers onto a second server.
# ---------------------------------------------------------------------------

WIZ_STEP=0

wiz_reset() { WIZ_STEP=0; }

# Kept so the wizard can note a decision without the page having to redraw.
wiz_add() { :; }

# wiz <title> [subtitle] - open a step.
wiz() {
    WIZ_STEP=$((WIZ_STEP + 1))
    local t="$WIZ_STEP $BX_DOT $1 " n; n="$(vislen " $t")"
    printf '\n  %s%s%s%s%s%s%s\n\n' \
        "$C_GRY" "$BX_H$BX_H " "$C_OFF$C_CYN$C_B" "$t" "$C_OFF$C_GRY" \
        "$(repeat "$BX_H" $((UI_W - n)))" "$C_OFF"
    [ -n "${2:-}" ] && { dim "$2"; say ""; }
    return 0
}

# choice <key> <name> <hint> - one option, name and reason on the same line.
#
# CHOICE_DEF marks the one enter picks, on the line itself. Having to read the
# prompt underneath to work out which number that is, is a step nobody should
# have to take.
CHOICE_DEF=""
choice() {
    local mark="   " hint="${3:-}"
    if [ "$1" = "$CHOICE_DEF" ]; then
        mark="${C_GRN}${BX_ARR}${C_OFF}  "
        hint="${hint}${hint:+  }${C_GRN}(default)${C_OFF}"
    fi
    printf '  %s%s%s%s  %s  %s%s%s\n' \
        "$mark" "$C_CYN$C_B" "$1" "$C_OFF" \
        "$(pad_to "${C_B}$2${C_OFF}" 14)" \
        "$C_DIM" "$hint" "$C_OFF"
}

# state <on|off> - a coloured on/off badge for toggles.
state_badge() {
    if [ "$1" = "on" ]; then
        printf '%s%s on%s' "$C_GRN" "$BX_ON" "$C_OFF"
    else
        printf '%s%s off%s' "$C_GRY" "$BX_OFF" "$C_OFF"
    fi
}

banner() {
    clear 2>/dev/null || true
    printf '\n'
    local l w pad
    if [ "$PINGIFY_UTF8" = "1" ]; then
        set -- \
            '██████╗ ██╗███╗   ██╗ ██████╗ ██╗███████╗██╗   ██╗' \
            '██╔══██╗██║████╗  ██║██╔════╝ ██║██╔════╝╚██╗ ██╔╝' \
            '██████╔╝██║██╔██╗ ██║██║  ███╗██║█████╗   ╚████╔╝ ' \
            '██╔═══╝ ██║██║╚██╗██║██║   ██║██║██╔══╝    ╚██╔╝  ' \
            '██║     ██║██║ ╚████║╚██████╔╝██║██║        ██║   ' \
            '╚═╝     ╚═╝╚═╝  ╚═══╝ ╚═════╝ ╚═╝╚═╝        ╚═╝   '
    else
        set -- \
            ' ___  _                 _   __     ' \
            '| _ \(_)_ _  __ _ (_) / _|_  _     ' \
            '|  _/| | | \| | (_| | | ||  _| || |' \
            '|_|  |_|_||_|\__, | |_||_|   \_, |ذ' \
            '             |___/          |__/   '
    fi

    # The name sits in its own frame, centred, so the page opens with one
    # object rather than six lines floating above a rule.
    w=0
    for l in "$@"; do
        [ "$(vislen "$l")" -gt "$w" ] && w="$(vislen "$l")"
    done
    local inner=$((UI_W))
    pad=$(( (inner - w) / 2 ))
    [ "$pad" -lt 0 ] && pad=0

    printf '  %s%s%s%s%s\n' "$C_CYN$C_DIM" "$BX_TL" "$(repeat "$BX_H" "$inner")" "$BX_TR" "$C_OFF"
    for l in "$@"; do
        printf '  %s%s%s%s%s%s%s%s\n' \
            "$C_CYN$C_DIM" "$BX_V" "$C_OFF" \
            "$(repeat ' ' "$pad")" "$C_CYN$C_B$l$C_OFF" \
            "$(repeat ' ' $((inner - pad - $(vislen "$l"))))" \
            "$C_CYN$C_DIM$BX_V" "$C_OFF"
    done

    # and the one line that says what it is, centred under it
    local sub="by Teejay   ${BX_DOT}   Iran ${BX_ARR} Kharej tunnel"
    pad=$(( (inner - ${#sub}) / 2 ))
    [ "$pad" -lt 0 ] && pad=0
    printf '  %s%s%s%s%s%s%s%s\n' \
        "$C_CYN$C_DIM" "$BX_V" "$C_OFF" \
        "$(repeat ' ' "$pad")" "$C_DIM$sub$C_OFF" \
        "$(repeat ' ' $((inner - pad - ${#sub})))" \
        "$C_CYN$C_DIM$BX_V" "$C_OFF"
    printf '  %s%s%s%s%s\n\n' "$C_CYN$C_DIM" "$BX_BL" "$(repeat "$BX_H" "$inner")" "$BX_BR" "$C_OFF"
}

pause() { printf '\n'; read -rsp "  ${C_DIM}press enter${C_OFF}" _; printf '\n'; }

# ask VAR "prompt" ["default"]
ask() {
    local __var="$1" __prompt="$2" __def="${3:-}" __in=""
    if [ -n "$__def" ]; then
        read -rp "  ${C_CYN}${BX_ARR}${C_OFF} ${__prompt} ${C_DIM}[${__def}]${C_OFF}${C_B}:${C_OFF} " __in
        [ -z "$__in" ] && __in="$__def"
    else
        read -rp "  ${C_CYN}${BX_ARR}${C_OFF} ${__prompt}${C_B}:${C_OFF} " __in
    fi
    printf -v "$__var" '%s' "$__in"
}

# pick <var> <prompt> <valid>... - insist on one of the listed answers.
#
# Some questions have no sensible default. Which server this is, what protocol
# to speak, who forwards - an empty enter that quietly means "the first one" is
# how somebody ends up with a tunnel they did not choose and cannot explain.
# The locals here are named apart from ask's on purpose. bash scopes locals
# dynamically, so a caller that asks ask to write into a variable ask also
# declares local gets ask's copy, and the caller's stays empty - which is a
# loop that rejects every answer, forever.
pick() {
    local _pk_var="$1" _pk_prompt="$2"; shift 2
    local _pk_in="" _pk_opt
    while :; do
        ask _pk_in "$_pk_prompt"
        if [ -z "$_pk_in" ]; then
            fail "this one has no default - choose $(printf '%s or ' "$@" | sed 's/ or $//')"
            continue
        fi
        for _pk_opt in "$@"; do
            if [ "$_pk_in" = "$_pk_opt" ]; then
                printf -v "$_pk_var" '%s' "$_pk_in"
                return 0
            fi
        done
        fail "not one of the options - choose $(printf '%s or ' "$@" | sed 's/ or $//')"
    done
}

# confirm_yes is confirm with the answer already leaning the right way: by the
# time it is asked, everything has been reviewed and the expected reply is yes.
confirm_yes() {
    local reply=""
    read -rp "  ${C_YEL}?${C_OFF} $1 ${C_DIM}[Y/n]${C_OFF}${C_B}:${C_OFF} " reply
    case "$reply" in [nN] | [nN][oO]) return 1 ;; *) return 0 ;; esac
}

confirm() {
    local reply=""
    read -rp "  ${C_YEL}?${C_OFF} $1 ${C_DIM}[y/N]${C_OFF}${C_B}:${C_OFF} " reply
    case "$reply" in [yY] | [yY][eE][sS]) return 0 ;; *) return 1 ;; esac
}

# A spinner for anything slow, so a download or a build never looks frozen.
spin() {
    local msg="$1"; shift
    if [ ! -t 1 ]; then "$@"; return $?; fi
    "$@" &
    local pid=$! i=0 frames='|/-\'
    while kill -0 "$pid" 2>/dev/null; do
        printf '\r  %s%s%s %s ' "$C_CYN" "${frames:i++%4:1}" "$C_OFF" "$msg"
        sleep 0.1
    done
    wait "$pid"
    local rc=$?
    printf '\r%s\r' "$(repeat ' ' $((${#msg} + 8)))"
    return $rc
}

# ---------------------------------------------------------------------------
# small utilities
# ---------------------------------------------------------------------------

require_root() {
    if [ "$(id -u)" != "0" ]; then
        fail "Pingify has to run as root. Try: sudo pingify"
        exit 1
    fi
}

have() { command -v "$1" >/dev/null 2>&1; }

# fetch <url> <dest> [timeout] - download one file with whatever this machine
# has. The install line is written with wget, so wget is the tool most likely
# to be present and curl the one most likely to be missing; assuming curl left
# servers quietly running an old script while the core updated around them.
fetch() {
    local url="$1" dest="$2" t="${3:-120}"
    if have curl; then
        curl -fsSL --retry 2 --max-time "$t" -o "$dest" "$url" && return 0
    fi
    if have wget; then
        wget -q --tries=2 --timeout="$t" -O "$dest" "$url" && return 0
    fi
    return 1
}

# Config files are TOML written by this script, one key per line, so a
# targeted sed reads them back and Pingify needs no parser of its own.
CFG_EXT="toml"

cfg_file() { printf '%s/%s.%s' "$CFG_DIR" "$1" "$CFG_EXT"; }

toml_arr() { [ -f "$1" ] || return 0; sed -n "s/^[[:space:]]*$2[[:space:]]*=[[:space:]]*\[\(.*\)\].*/\1/p" "$1" | head -n1; }

# toml_get <file> <section> <key> - reads a value out of one [section].
# Values keep their quotes off and numeric underscores stripped.
# The public name of a security token: eight characters derived from it, safe
# to read aloud. Both servers print the same one when the token matches, which
# is the only way to tell a wrong token apart from a broken network.
token_print() {
    local t
    t="$(printf '%s' "${1:-}" | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//')"
    [ -n "$t" ] && printf '%s' "$t" | sha256sum | cut -c1-8 || printf 'none'
}

toml_get() {
    [ -f "$1" ] || return 0
    awk -v want="$2" -v key="$3" '
        /^[[:space:]]*\[/ { s = $0; gsub(/[][[:space:]]/, "", s); cur = s; next }
        cur == want {
            line = $0
            sub(/[[:space:]]*#.*$/, "", line)
            if (match(line, "^[[:space:]]*" key "[[:space:]]*=")) {
                v = substr(line, RSTART + RLENGTH)
                gsub(/^[[:space:]]+|[[:space:]]+$/, "", v)
                if (v ~ /^"/) { gsub(/^"|"$/, "", v) }
                else if (v ~ /^[0-9_]+$/) { gsub(/_/, "", v) }
                print v
                exit
            }
        }' "$1"
}


# Only used to convert a config left behind by 3.2 or earlier.
json_str() { [ -f "$1" ] || return 0; sed -n "s/^[[:space:]]*\"$2\"[[:space:]]*:[[:space:]]*\"\([^\"]*\)\".*/\1/p" "$1" | head -n1; }
json_num() { [ -f "$1" ] || return 0; sed -n "s/^[[:space:]]*\"$2\"[[:space:]]*:[[:space:]]*\([0-9][0-9]*\).*/\1/p" "$1" | head -n1; }

port_free() {
    local p="$1"
    if have ss; then
        ! ss -Hltn "sport = :$p" 2>/dev/null | grep -q . || return 1
    fi
    return 0
}

pick_free_port() {
    local p="${1:-9700}"
    while [ "$p" -lt 65535 ]; do
        if port_free "$p"; then printf '%s' "$p"; return 0; fi
        p=$((p + 1))
    done
    printf '%s' "$1"
}

# The status endpoint has to be unique per tunnel. Asking the kernel whether a
# port is free only answers for the tunnels that happen to be running right
# now, so a second tunnel built while the first one was stopped was handed the
# same port - and then the two of them fought over it at the next boot, with
# the loser reporting no carriers to a health check that could see nothing
# wrong with it.
pick_status_port() {
    local want="${1:-9700}" p="${1:-9700}" taken="" f
    for f in "$CFG_DIR"/*.toml "$CFG_DIR"/*.json; do
        [ -f "$f" ] || continue
        taken="$taken $(toml_get "$f" status addr)"
    done
    while [ "$p" -lt 65535 ]; do
        case " $taken " in
            *":$p "*) p=$((p + 1)); continue ;;
        esac
        if port_free "$p"; then printf '%s' "$p"; return 0; fi
        p=$((p + 1))
    done
    printf '%s' "$want"
}

public_ip() {
    local ip=""
    if have curl; then
        ip=$(curl -4 -fsS --max-time 5 https://api.ipify.org 2>/dev/null)
    fi
    if [ -z "$ip" ] && have ip; then
        ip=$(ip -4 route get 1.1.1.1 2>/dev/null | awk '{for(i=1;i<=NF;i++) if($i=="src"){print $(i+1); exit}}')
    fi
    printf '%s' "$ip"
}

tunnel_names() {
    [ -d "$CFG_DIR" ] || return 0
    local f
    for f in "$CFG_DIR"/*."$CFG_EXT"; do
        [ -e "$f" ] || continue
        basename "$f" ".$CFG_EXT"
    done
}

# Where this server sits, for the panel on the front page. Best effort: an
# Iranian box may not reach the lookup service, in which case the local route
# still gives us the address.
server_info() {
    [ -n "${SRV_IP:-}" ] && return 0
    SRV_IP=""; SRV_LOC=""; SRV_ORG=""
    if have curl; then
        local j
        j="$(curl -fsS --max-time 6 'http://ip-api.com/json/?fields=query,country,isp' 2>/dev/null)"
        if [ -n "$j" ]; then
            SRV_IP="$(printf  '%s' "$j" | sed -n 's/.*"query":"\([^"]*\)".*/\1/p')"
            SRV_LOC="$(printf '%s' "$j" | sed -n 's/.*"country":"\([^"]*\)".*/\1/p')"
            SRV_ORG="$(printf '%s' "$j" | sed -n 's/.*"isp":"\([^"]*\)".*/\1/p')"
        fi
    fi
    [ -n "$SRV_IP" ] || SRV_IP="$(public_ip)"
    [ -n "$SRV_IP" ] || SRV_IP="unknown"
    [ -n "$SRV_LOC" ] || SRV_LOC="unknown"
    [ -n "$SRV_ORG" ] || SRV_ORG="unknown"
}

tunnel_count() { tunnel_names | grep -c . ; }

svc_state() {
    if systemctl is-active --quiet "pingify@$1" 2>/dev/null; then printf 'active'
    elif systemctl is-enabled --quiet "pingify@$1" 2>/dev/null; then printf 'stopped'
    else printf 'disabled'; fi
}

# ---------------------------------------------------------------------------
# OS and toolchain
# ---------------------------------------------------------------------------

detect_os() {
    OS_ID="unknown"; OS_VER="0"; OS_PRETTY="unknown"
    if [ -r /etc/os-release ]; then
        # shellcheck disable=SC1091
        . /etc/os-release
        OS_ID="${ID:-unknown}"
        OS_VER="${VERSION_ID:-0}"
        OS_PRETTY="${PRETTY_NAME:-$OS_ID $OS_VER}"
    fi
    ARCH="$(uname -m)"
    case "$ARCH" in
        x86_64 | amd64)  GOARCH="amd64" ;;
        aarch64 | arm64) GOARCH="arm64" ;;
        armv7l | armv6l) GOARCH="armv6l" ;;
        *)               GOARCH="" ;;
    esac
}

apt_install() {
    export DEBIAN_FRONTEND=noninteractive
    if [ "${PINGIFY_APT_UPDATED:-}" != "1" ]; then
        apt-get update -qq >/dev/null 2>&1 || warn "apt-get update reported a problem, continuing"
        PINGIFY_APT_UPDATED=1
    fi
    apt-get install -y -qq "$@" >/dev/null 2>&1
}

ensure_deps() {
    local missing=()
    have curl   || missing+=(curl)
    have tar    || missing+=(tar)
    have ip     || missing+=(iproute2)
    have ss     || missing+=(iproute2)
    have base64 || missing+=(coreutils)
    if [ ${#missing[@]} -gt 0 ]; then
        if have apt-get; then
            spin "installing ${missing[*]}" apt_install "${missing[@]}" \
                || warn "some packages could not be installed"
        else
            warn "please install manually: ${missing[*]}"
        fi
    fi
    mkdir -p "$BASE_DIR" "$STATE_DIR"
    chmod 700 "$BASE_DIR"
}

# Prints the minor version of a Go toolchain, e.g. 22 for go1.22.2, or 0 when
# the binary is unusable or predates the 1.x scheme.
go_version_minor() {
    local v major rest minor
    v="$("$1" version 2>/dev/null | awk '{print $3}')"   # e.g. go1.22.2
    v="${v#go}"
    major="${v%%.*}"; rest="${v#*.}"; minor="${rest%%.*}"
    case "$major.$minor" in
        1.*[!0-9]* | 1.) printf '0'; return ;;
        1.*) printf '%s' "$minor" ;;
        *)   printf '0' ;;
    esac
}

find_go() {
    local cand
    for cand in "$(command -v go 2>/dev/null)" /usr/local/go/bin/go /usr/lib/go/bin/go; do
        [ -n "$cand" ] && [ -x "$cand" ] || continue
        if [ "$(go_version_minor "$cand")" -ge "$GO_MIN_MINOR" ] 2>/dev/null; then
            GO_BIN="$cand"; return 0
        fi
    done
    for cand in /usr/lib/go-*/bin/go; do
        [ -x "$cand" ] || continue
        if [ "$(go_version_minor "$cand")" -ge "$GO_MIN_MINOR" ] 2>/dev/null; then
            GO_BIN="$cand"; return 0
        fi
    done
    return 1
}

install_go_tarball() {
    [ -n "$GOARCH" ] || { fail "unsupported CPU architecture: $ARCH"; return 1; }
    local ver=""
    ver=$(curl -fsS --max-time 8 "https://go.dev/VERSION?m=text" 2>/dev/null | head -n1)
    case "$ver" in go1.*) ;; *) ver="$GO_FALLBACK" ;; esac
    info "downloading $ver for $GOARCH"
    if ! curl -fL --retry 2 --max-time 300 -o /tmp/pingify-go.tgz \
         "https://go.dev/dl/${ver}.linux-${GOARCH}.tar.gz"; then
        fail "could not download the Go toolchain"
        dim "this is only the fallback path - see Update Core for other options"
        return 1
    fi
    rm -rf /usr/local/go
    tar -C /usr/local -xzf /tmp/pingify-go.tgz || return 1
    rm -f /tmp/pingify-go.tgz
    [ -x /usr/local/go/bin/go ] || return 1
    GO_BIN="/usr/local/go/bin/go"
    return 0
}

ensure_go() {
    if find_go; then
        dim "using $("$GO_BIN" version)"
        return 0
    fi
    info "no suitable Go toolchain here (need 1.${GO_MIN_MINOR} or newer)"
    if have apt-get; then
        spin "installing golang-go from the distro" apt_install golang-go
        find_go && { dim "using $("$GO_BIN" version)"; return 0; }
    fi
    install_go_tarball || return 1
    dim "using $("$GO_BIN" version)"
    return 0
}

# ---------------------------------------------------------------------------
# the core
#
# Three ways to get it, tried in this order:
#   1. download the prebuilt binary for this CPU from GitHub Releases - the
#      normal path, a couple of seconds and no toolchain
#   2. compile the sources embedded in this script - needs Go but downloads
#      nothing, for a server that cannot reach the release files
#   3. import a binary you built elsewhere and copied across
# ---------------------------------------------------------------------------

release_base() { printf 'https://github.com/%s/releases/latest/download' "$PINGIFY_REPO"; }
core_asset()   { printf 'pingify-core-linux-%s' "$GOARCH"; }

core_version() {
    [ -x "$CORE_BIN" ] || { printf 'not installed'; return 1; }
    "$CORE_BIN" -version 2>/dev/null | awk '{print $2}' || printf 'unknown'
}

# Accept a candidate binary only once it has proved it runs on this machine.
adopt_core() {
    local tmp="$1"
    chmod +x "$tmp" 2>/dev/null
    if ! "$tmp" -version >/dev/null 2>&1; then
        fail "that binary does not run on this server (wrong architecture?)"
        rm -f "$tmp"
        return 1
    fi
    install -m 0755 "$tmp" "$CORE_BIN" || return 1
    rm -f "$tmp"
    ok "core $("$CORE_BIN" -version | awk '{print $2}') installed"
    return 0
}

download_core() {
    [ -n "$GOARCH" ] || { warn "no prebuilt core for $ARCH"; return 1; }
    have curl || return 1
    local base tmp="/tmp/pingify-core.dl" sums="/tmp/pingify-core.sums"
    base="$(release_base)"

    if ! spin "downloading the core for $GOARCH" \
         fetch "$base/$(core_asset)" "$tmp" 180; then
        rm -f "$tmp"
        return 1
    fi

    # The checksum file is published alongside the binaries. A missing one is
    # not fatal, a wrong one is.
    if fetch "$base/SHA256SUMS" "$sums" 30 2>/dev/null; then
        local want got
        want="$(awk -v a="$(core_asset)" '$2 ~ a {print $1; exit}' "$sums")"
        got="$(sha256sum "$tmp" | awk '{print $1}')"
        rm -f "$sums"
        if [ -n "$want" ] && [ "$want" != "$got" ]; then
            fail "checksum mismatch - refusing to install this download"
            rm -f "$tmp"
            return 1
        fi
    fi

    adopt_core "$tmp"
}

build_core() {
    ensure_go || return 1
    rm -rf "$SRC_DIR"
    mkdir -p "$SRC_DIR" || return 1
    write_core_sources "$SRC_DIR" || return 1
    printf 'module pingify\n\ngo 1.%s\n' "$GO_MIN_MINOR" > "$SRC_DIR/go.mod"

    local log="/tmp/pingify-build.log"
    go_build_now() {
        ( cd "$SRC_DIR" && \
          GOTOOLCHAIN=local GO111MODULE=on GOFLAGS=-mod=mod GOPROXY=off GOSUMDB=off \
          GOPATH="${GOPATH:-/tmp/pingify-gopath}" GOCACHE="${GOCACHE:-/tmp/pingify-gocache}" \
          CGO_ENABLED=0 "$GO_BIN" build -trimpath -ldflags "-s -w" \
          -o "$SRC_DIR/pingify-core" . ) >"$log" 2>&1
    }
    if ! spin "compiling the core (a minute or so on a small VPS)" go_build_now; then
        fail "the core did not compile"
        sed 's/^/      /' "$log" | tail -n 20
        return 1
    fi
    adopt_core "$SRC_DIR/pingify-core"
}

# install_core is the full ladder; ensure_core only runs it when needed.
install_core() {
    if download_core; then return 0; fi
    warn "GitHub is not reachable - compiling the core here instead"
    build_core
}

ensure_core() {
    [ -x "$CORE_BIN" ] && return 0
    install_core
}

# The script and the core share the config format, so a core left behind by an
# older install reads a newer config as if half of it were not there. 3.4 moved
# configs into sections; a 3.3 core reads one of those and reports every field
# as empty - which surfaced as "role must be \"server\" or \"client\", got \"\""
# with nothing to point at the real cause. They are kept in step here instead.
core_matches_script() {
    [ -x "$CORE_BIN" ] || return 1
    [ "$(core_version)" = "$PINGIFY_VERSION" ]
}

ensure_core_current() {
    [ -x "$CORE_BIN" ] || return 0
    core_matches_script && return 0
    banner
    head2 "Core update"
    warn "the core is $(core_version), this script is $PINGIFY_VERSION"
    dim "they have to match - the config format is shared between them"
    say ""
    if download_core; then
        restart_all "the core was updated"
    else
        say ""
        fail "the core could not be updated"
        dim "until it matches, new tunnels will be rejected"
        dim "check this server can reach GitHub, then run pingify again"
    fi
    pause
}

# ---------------------------------------------------------------------------
# systemd
# ---------------------------------------------------------------------------

write_units() {
    cat > "$UNIT_DIR/pingify@.service" <<UNIT
[Unit]
Description=Pingify tunnel %i
Documentation=https://github.com/GreatTeejay/Pingify
After=network-online.target
Wants=network-online.target
StartLimitIntervalSec=0

[Service]
Type=simple
ExecStart=$CORE_BIN -c $CFG_DIR/%i.$CFG_EXT
WorkingDirectory=$BASE_DIR
Restart=always
RestartSec=2
LimitNOFILE=1048576
TasksMax=infinity
NoNewPrivileges=yes
AmbientCapabilities=CAP_NET_ADMIN CAP_NET_BIND_SERVICE CAP_NET_RAW
CapabilityBoundingSet=CAP_NET_ADMIN CAP_NET_BIND_SERVICE CAP_NET_RAW
# ProtectHome is deliberately off: the core and its config live under /root.
ProtectHome=no
ProtectSystem=full
StandardOutput=journal
StandardError=journal
SyslogIdentifier=pingify-%i

[Install]
WantedBy=multi-user.target
UNIT

    cat > "$UNIT_DIR/pingify-health.service" <<'UNIT'
[Unit]
Description=Pingify health check
ConditionPathExists=/usr/local/bin/pingify

[Service]
Type=oneshot
ExecStart=/usr/local/bin/pingify --health-check
SyslogIdentifier=pingify-health
UNIT

    cat > "$UNIT_DIR/pingify-health.timer" <<'UNIT'
[Unit]
Description=Pingify health check every 30s

[Timer]
OnBootSec=60s
OnUnitActiveSec=30s
AccuracySec=5s
Unit=pingify-health.service

[Install]
WantedBy=timers.target
UNIT

    cat > "$UNIT_DIR/pingify-recycle@.service" <<'UNIT'
[Unit]
Description=Pingify scheduled recycle of tunnel %i

[Service]
Type=oneshot
ExecStart=/bin/systemctl restart pingify@%i.service
SyslogIdentifier=pingify-recycle
UNIT

    systemctl daemon-reload
}

service_enable_start() {
    systemctl enable --now "pingify@$1" >/dev/null 2>&1
}

# ---------------------------------------------------------------------------
# tunnel configuration
#
# Two things decide the shape of a tunnel, and both are asked on both servers
# because both ends have to agree.
#
#   kind        TCP  - the servers talk over their own public addresses
#               TUN  - a private layer-3 link, carried over ICMP today
#
#   forwarder   only meaningful under TUN, where a local tunnel exists:
#               PINGIFY  - the core carries each connection itself
#               IPTABLES - the kernel NATs onto the local tunnel
#
# A TCP tunnel has no local tunnel and adds no interface, so the core is the
# only thing that can forward on it and there is nothing to ask.
#
# Ports are asked for on the IRAN server alone - that is the end clients
# reach. The security token is typed by hand on both.
# ---------------------------------------------------------------------------

cfg_reset() {
    T_NAME=""; T_ROLE=""
    # kind is TCP or TUN; the transport, mode and forwarder all follow from it.
    T_KIND="tcp"; T_TRANSPORT="tcp"; T_MODE="forward"; T_FORWARDER="pingify"
    T_TOKEN=""
    T_PORT=9443          # the tunnel's own port, TCP only
    T_ACCEPTS="server"   # reverse: IRAN accepts, KHAREJ comes to it
    T_PUBLIC_IP=""; T_PEER_IP=""
    T_CARRIERS=16; T_WINDOW=1024; T_KEEPALIVE=10; T_PRESET="balanced"
    T_SNDBUF=1024; T_RCVBUF=1024   # socket buffers, sized to hold a BDP
    T_OBFUSCATE="false"  # v2.1.1 wire shape; the one that survives the path
    T_FORWARDS=""; T_STATUS=""; T_LOG="info"
    T_TUNIF=""; T_TUNLOCAL=""; T_TUNPEER=""; T_TUNMTU=1380
    # kernel tunnels: GRE carries a TTL, AmneziaWG a port, a keypair half and
    # the obfuscation values both ends have to agree on
    T_GRE_TTL=255
    T_AWG_PORT=51820; T_AWG_PRIV=""; T_AWG_PUB=""; T_AWG_OBF=""
}

this_side_accepts() { [ "$T_ROLE" = "$T_ACCEPTS" ]; }

# A local tunnel belongs to the TUN kind and nowhere else. A TCP tunnel runs
# over the two public addresses and leaves the machine as it found it, so the
# core is the only thing that can forward on it.
cfg_mode() {
    # GRE and AmneziaWG are the kernel's own tunnels. They always build a
    # private link, and the kernel is the only thing that can forward on it -
    # our core is not in the path at all.
    if kernel_transport; then
        T_KIND="tun"; T_MODE="tun"; T_FORWARDER="iptables"
        T_TUNIF="$(link_iface "$T_NAME")"
        return
    fi
    if [ "$T_KIND" = "tun" ]; then
        # both forwarders work here: the kernel can NAT onto the local tunnel,
        # or the core can carry the ports over the same carriers.
        [ "$T_FORWARDER" = "iptables" ] && T_MODE="tun" || T_MODE="both"
    else
        T_FORWARDER="pingify"
        T_MODE="forward"
    fi
}

cfg_needs_link() { [ "$T_MODE" != "forward" ]; }

# The name says which server this is and what the tunnel runs on, so two
# servers side by side read as what they are without either file being opened.
# A tunnel that builds a private link wears the TUN label in front of it.
#
# Both the wizard and the importer name tunnels, and they used to do it with
# two copies of this - which drifted the moment one of them was edited, and
# left an AmneziaWG tunnel called iran-9443 after a TCP port it does not use.
tunnel_default_name() {
    local extra="${1:-}" base tail=""
    [ -n "$extra" ] && tail="-$extra"
    base="$(printf '%s' "$(side_label "$T_ROLE")" | tr 'A-Z' 'a-z')"
    case "$T_TRANSPORT" in
        icmp) printf 'tun-%s-icmp%s' "$base" "$tail" ;;
        gre)  printf 'tun-%s-gre%s' "$base" "$tail" ;;
        awg)  printf 'tun-%s-awg%s' "$base" "$tail" ;;
        *)    printf '%s-%s' "$base" "$T_PORT" ;;
    esac
}

# link_octet - the x in 10.x.10.0/24.
#
# When a server holds two tunnels of the same kind, something has to tell them
# apart, and a counter tells you nothing: iran-gre-2 says only that it was
# second. The private network says which one it is - and both servers agreed
# on it, so both ends of one tunnel still arrive at the same name. The health
# port cannot do this job: it is chosen locally and independently on each
# server, so the two ends would end up called different things.
link_octet() {
    local a="${T_TUNLOCAL%%/*}"
    case "$a" in
        10.*.*.*) a="${a#10.}"; printf '%s' "${a%%.*}"; return 0 ;;
    esac
    return 1
}

# listen and connect are derived, never stored anywhere shared: they are the
# one part of a tunnel that differs between the two servers.
cfg_endpoints() {
    CFG_LISTEN=""; CFG_CONNECT=""
    # A kernel tunnel names both addresses in its own section; there is no
    # socket here for anything to listen on or dial.
    kernel_transport && return
    if this_side_accepts; then
        # ICMP has no port, so listen carries the address to answer from.
        if [ "$T_TRANSPORT" = "icmp" ]; then CFG_LISTEN="${T_PUBLIC_IP:-0.0.0.0}"
        else CFG_LISTEN="0.0.0.0:$T_PORT"; fi
    else
        if [ "$T_TRANSPORT" = "icmp" ]; then CFG_CONNECT="$T_PEER_IP"
        else CFG_CONNECT="$T_PEER_IP:$T_PORT"; fi
    fi
}

# ---------------------------------------------------------------------------
# performance presets
#
# These numbers used to be guesses. They are now taken from iperf3 between a
# real Iran and Kharej pair:
#
#   the path carries ~100 Mbit/s in both directions
#   round trip is ~78 ms
#   one TCP connection reaches only 4-6 Mbit/s, because loss holds its
#   congestion window down around 30-90 KB
#
# A single connection is therefore worth about 6 Mbit/s no matter how much
# bandwidth exists, and filling 100 Mbit/s takes 15-20 of them. Four carriers -
# the old default - left seventy Mbit/s of a hundred unused.
#
# carriers  how many connections the link is spread over. On a lossy path this
#           is the setting that decides throughput, because each connection is
#           capped by its own window, not by the path.
# window    how much one forwarded connection may have in flight. The delay
#           bandwidth product here is about 1 MB, so anything below that
#           throttles a single large transfer even when the carriers could
#           carry it.
# ---------------------------------------------------------------------------

# The numbers, and why each one is what it is.
#
# A stream is pinned to one carrier for its life, so the window alone decides
# how fast a single download can go: window / round-trip. On the 75-90 ms this
# path actually measures, that is
#
#   256 KB  ->  ~24 Mbit/s      1024 KB  ->  ~95 Mbit/s
#   512 KB  ->  ~48 Mbit/s      4096 KB  -> ~380 Mbit/s
#
# for ONE connection. Carriers do not raise that; they spread many connections
# so one heavy download stops starving everything else.
#
# Bigger is not simply better. A window past what the path can carry does not
# go faster - it queues, and a queue is latency. That is what shows up as a
# video that stalls and a ping that swings while the speed graph looks fine.
# So the presets climb the window only as far as the traffic needs, and buy
# steadiness with carriers rather than with depth.
apply_preset() {
    case "$1" in
        # Games and calls: the smallest window that still fills a link, so
        # nothing is ever sat in a queue waiting. Throughput is not the point.
        gaming)     T_CARRIERS=8;  T_WINDOW=256 ;;
        # Browsing and chat - many small things at once, none of them large.
        latency)    T_CARRIERS=12; T_WINDOW=512 ;;
        # Video. One stream reaching ~95 Mbit/s covers 4K with room over, and
        # 16 carriers keep a download from taking the picture down with it.
        balanced)   T_CARRIERS=16; T_WINDOW=1024 ;;
        # Large files, where finishing sooner is worth some queueing.
        throughput) T_CARRIERS=20; T_WINDOW=2048 ;;
        # Everything the path will give. Uses real memory: each carrier holds
        # a send and a receive buffer this size.
        extreme)    T_CARRIERS=24; T_WINDOW=4096 ;;
        *)          return 1 ;;
    esac
    # One keepalive for every preset. What kept a carrier alive was how often
    # the *peer* spoke, so two ends on different presets used to disagree about
    # how long to wait - and the impatient one hung up on a healthy tunnel.
    T_KEEPALIVE=10
    T_PRESET="$1"
    return 0
}

# The tuning arrives in the token as bare numbers, so name the preset they
# match. Writing "from token" put a string in the profile field that is not a
# profile, and told a reader on this server nothing about what the tuning is -
# while the other server, with the identical numbers, called it Extreme.
# preset_name asks apply_preset rather than holding a second copy of the table.
# The two were separate lists, and the moment the presets were retuned they
# disagreed: apply_preset set balanced to 16 carriers while this still called
# 16 "custom" and 14 "balanced". A config could then report a profile no preset
# would produce.
preset_name() {
    local car="$1" win="$2" p
    for p in gaming latency balanced throughput extreme; do
        # in a subshell: apply_preset writes the T_ variables, and this is
        # asked from screens that are holding a tunnel in them
        if [ "$(apply_preset "$p" >/dev/null 2>&1; printf '%s/%s' "$T_CARRIERS" "$T_WINDOW")" = "$car/$win" ]; then
            printf '%s' "$p"
            return 0
        fi
    done
    printf 'custom'
}

preset_menu() {
    CHOICE_DEF="3"
    choice 1 "Gaming" "8 carriers, 256 KB - lowest ping, nothing queued"
    choice 2 "Latency" "12 carriers, 512 KB - browsing, calls, chat"
    choice 3 "Balanced" "16 carriers, 1024 KB - video without stalls"
    choice 4 "Download" "20 carriers, 2048 KB - large files"
    choice 5 "Extreme" "24 carriers, 4096 KB - fastest, most memory"
    choice 6 "Custom" "set the numbers yourself"
    CHOICE_DEF=""
    say ""
    local p=""
    ask p "select" "3"
    case "$p" in
        1) apply_preset gaming ;;
        2) apply_preset latency ;;
        4) apply_preset throughput ;;
        5) apply_preset extreme ;;
        6) T_PRESET="custom"
           say ""
           ask T_CARRIERS "parallel connections" "$T_CARRIERS"
           ask T_WINDOW "window per connection, KB" "$T_WINDOW"
           ask T_KEEPALIVE "keepalive seconds" "$T_KEEPALIVE" ;;
        *) apply_preset balanced ;;
    esac
    case "$T_CARRIERS" in "" | *[!0-9]*) T_CARRIERS=16 ;; esac
    case "$T_WINDOW" in "" | *[!0-9]*) T_WINDOW=1024 ;; esac
    case "$T_KEEPALIVE" in "" | *[!0-9]*) T_KEEPALIVE=10 ;; esac
    [ "$T_CARRIERS" -lt 1 ] && T_CARRIERS=1
    [ "$T_CARRIERS" -gt 64 ] && T_CARRIERS=64

    # Socket buffers have to hold a delay bandwidth product or the kernel
    # window cannot grow into one. Sized from the chosen window, capped where
    # more stops helping.
    T_SNDBUF="$T_WINDOW"; T_RCVBUF="$T_WINDOW"
    [ "$T_SNDBUF" -lt 512 ] && T_SNDBUF=512
    [ "$T_RCVBUF" -lt 512 ] && T_RCVBUF=512
    [ "$T_SNDBUF" -gt 4096 ] && T_SNDBUF=4096
    [ "$T_RCVBUF" -gt 4096 ] && T_RCVBUF=4096
}

# ---------------------------------------------------------------------------
# rendering
# ---------------------------------------------------------------------------

cfg_render() {
    local listen="$1" connect="$2" status="$3"
    printf '# Pingify tunnel - written by the manager, safe to edit by hand\n'
    printf '\n[tunnel]\n'
    printf 'name             = "%s"\n' "$T_NAME"
    printf 'role             = "%s"\n' "$T_ROLE"
    printf 'kind             = "%s"\n' "$T_KIND"
    printf 'mode             = "%s"\n' "$T_MODE"
    printf '\n[transport]\n'
    printf 'type             = "%s"\n' "$T_TRANSPORT"
    [ -n "$listen" ]  && printf 'listen           = "%s"\n' "$listen"
    [ -n "$connect" ] && printf 'connect          = "%s"\n' "$connect"
    printf 'carriers         = %s\n' "$T_CARRIERS"
    printf 'keepalive_sec    = %s\n' "$T_KEEPALIVE"
    printf 'obfuscate        = %s\n' "$T_OBFUSCATE"
    printf '\n[security]\n'
    printf 'token            = "%s"\n' "$T_TOKEN"
    printf '\n[forward]\n'
    printf 'forwarder        = "%s"\n' "$T_FORWARDER"
    [ -n "$T_FORWARDS" ] && printf 'ports            = [%s]\n' "$T_FORWARDS"
    if [ "$T_MODE" = "tun" ] || [ "$T_MODE" = "both" ]; then
        printf '\n[tun]\n'
        printf 'name             = "%s"\n' "$T_TUNIF"
        printf 'local_addr       = "%s"\n' "$T_TUNLOCAL"
        printf 'remote_addr      = "%s"\n' "$T_TUNPEER"
        printf 'mtu              = %s\n' "$T_TUNMTU"
    fi
    if [ "$T_TRANSPORT" = "gre" ]; then
        printf '\n[gre]\n'
        printf 'ttl              = %s\n' "$T_GRE_TTL"
        printf 'local_public     = "%s"\n' "$T_PUBLIC_IP"
        printf 'peer_public      = "%s"\n' "$T_PEER_IP"
    fi
    if [ "$T_TRANSPORT" = "awg" ]; then
        printf '\n[awg]\n'
        printf 'listen_port      = %s\n' "$T_AWG_PORT"
        printf 'private_key      = "%s"\n' "$T_AWG_PRIV"
        printf 'peer_key         = "%s"\n' "$T_AWG_PUB"
        printf 'obfuscation      = "%s"\n' "$T_AWG_OBF"
        printf 'local_public     = "%s"\n' "$T_PUBLIC_IP"
        printf 'peer_public      = "%s"\n' "$T_PEER_IP"
    fi
    printf '\n[tuning]\n'
    printf 'profile          = "%s"\n' "$T_PRESET"
    printf 'window_kb        = %s\n' "$T_WINDOW"
    printf 'sndbuf_kb        = %s\n' "$T_SNDBUF"
    printf 'rcvbuf_kb        = %s\n' "$T_RCVBUF"
    printf '\n[status]\n'
    printf 'addr             = "%s"\n' "$status"
    printf '\n[logging]\n'
    printf 'level            = "%s"\n' "$T_LOG"
}

# Name the missing field rather than letting the core report it as a flat
# rejection with nothing to point at.
cfg_check_complete() {
    local missing=""
    [ -n "$T_NAME" ]      || missing="$missing name"
    [ -n "$T_ROLE" ]      || missing="$missing side"
    [ -n "$T_TRANSPORT" ] || missing="$missing protocol"
    [ -n "$T_TOKEN" ]     || missing="$missing token"
    case "$T_MODE" in
        tun | both) [ -n "$T_TUNLOCAL" ] || missing="$missing private-address" ;;
    esac
    if [ "$T_ROLE" = "server" ] && [ -z "$T_FORWARDS" ]; then
        missing="$missing ports"
    fi
    if ! this_side_accepts && [ -z "$T_PEER_IP" ]; then
        missing="$missing peer-address"
    fi
    if kernel_transport; then
        # Both ends of a kernel tunnel name both public addresses: the kernel
        # builds the link from the pair, not from whoever dialled first.
        [ -n "$T_PUBLIC_IP" ] || missing="$missing this-address"
        [ -n "$T_PEER_IP" ]   || missing="$missing peer-address"
        [ -n "$T_TUNPEER" ]   || missing="$missing peer-private-address"
        if [ "$T_TRANSPORT" = "awg" ]; then
            [ -n "$T_AWG_PRIV" ] || missing="$missing private-key"
            [ -n "$T_AWG_PUB" ]  || missing="$missing peer-key"
        fi
    fi
    if [ -n "$missing" ]; then
        fail "these are still missing:$missing"
        return 1
    fi
    return 0
}

cfg_save() {
    local file
    # Everything here is read through a command substitution, so anything the
    # check prints on stdout ends up inside the caller's variable instead of on
    # the screen. That turned a named missing field into a confirm prompt that
    # appeared to do nothing at all.
    cfg_check_complete >&2 || return 1
    file="$(cfg_file "$T_NAME")"
    cfg_endpoints
    cfg_render "$CFG_LISTEN" "$CFG_CONNECT" "$T_STATUS" > "$file"
    chmod 600 "$file"
    printf '%s' "$file"
}

parse_forwards() {
    local raw="$1" out="" item
    raw="${raw//,/ }"
    for item in $raw; do
        [ -n "$item" ] || continue
        [ -n "$out" ] && out="$out,"
        out="$out\"$item\""
    done
    printf '%s' "$out"
}

side_label()      { [ "$1" = "server" ] && printf 'IRAN' || printf 'KHAREJ'; }
# BRAID is what the TCP transport does: several carriers woven together, each
# flow pinned to one strand so nothing arrives out of order. The protocol is
# still plain TCP - the name describes the weave, not a new protocol.
transport_label() {
    case "$1" in
        icmp | echo) printf 'TUN-ICMP' ;;
        gre)         printf 'TUN-GRE' ;;
        awg)         printf 'TUN-AWG' ;;
        *)           printf 'TCP' ;;
    esac
}

# ---------------------------------------------------------------------------
# new tunnel
# ---------------------------------------------------------------------------

# ---------------------------------------------------------------------------
# the setup token
#
# Build the tunnel on one server, paste one line on the other, and the second
# server is finished. Everything both ends have to agree on travels in it, so
# there is nothing to copy by hand and nothing to get wrong:
#
#   p2|kind|transport|mode|forwarder|dial|host|port|token|carriers|window|
#      keepalive|snd|rcv|tunlocal|tunpeer|mtu
#
# dial says what the far end does about the connection: 1 means it dials us
# and host is where, 0 means it accepts and supplies its own address. The
# private addresses are already swapped - what is ours becomes theirs.
#
# It is a list of values rather than a config document on purpose. A document
# ties the token to whatever format that document is in, and changing the
# format then breaks every token that was ever printed.
# ---------------------------------------------------------------------------

cfg_setup_token() {
    local dial host="" port="" tl="" tp="" mtu=""
    local ttl="" awgport="" awgpriv="" awgpub="" awgobf=""
    if this_side_accepts; then
        dial=1; host="$T_PUBLIC_IP"
    else
        dial=0
    fi
    [ "$T_TRANSPORT" = "tcp" ] && port="$T_PORT"
    if [ "$T_MODE" = "tun" ] || [ "$T_MODE" = "both" ]; then
        local pfx="${T_TUNLOCAL##*/}"
        [ "$pfx" = "$T_TUNLOCAL" ] && pfx=24
        tl="${T_TUNPEER%%/*}/${pfx}"
        tp="${T_TUNLOCAL}"
        mtu="$T_TUNMTU"
    fi
    if kernel_transport; then
        # The kernel builds its link from a pair of public addresses, so both
        # ends need both of them - not just whichever one dials.
        host="$T_PUBLIC_IP"
        if [ "$T_TRANSPORT" = "gre" ]; then
            ttl="$T_GRE_TTL"
        else
            awgport="$T_AWG_PORT"
            awgpriv="$awg_peer_priv"   # the half the other server keeps
            awgpub="$awg_self_pub"     # ours, which it lists as its peer
            awgobf="$T_AWG_OBF"
        fi
    fi
    printf 'p3|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s' \
        "$T_KIND" "$T_TRANSPORT" "$T_MODE" "$T_FORWARDER" \
        "$dial" "$host" "$port" "$T_TOKEN" \
        "$T_CARRIERS" "$T_WINDOW" "$T_KEEPALIVE" "$T_SNDBUF" "$T_RCVBUF" \
        "$tl" "$tp" "$mtu" \
        "$ttl" "$awgport" "$awgpriv" "$awgpub" "$awgobf" \
        | base64 | tr -d '\n'
}

# import_tunnel turns one of those into a running tunnel on this server.
import_tunnel() {
    banner
    head2 "Paste the setup token"
    dim "Printed by the other server when its tunnel was made."
    say ""
    local token=""
    ask token "token"
    [ -n "$token" ] || return 1

    local raw
    raw="$(printf '%s' "$token" | tr -d ' \t\r\n' | base64 -d 2>/dev/null)"
    case "$raw" in
        p2\|* | p3\|*) ;;
        *) fail "that is not a Pingify setup token"; pause; return 1 ;;
    esac

    # p3 added the five kernel-tunnel fields on the end. A p2 token simply
    # leaves them empty, which is what it meant.
    local v kind tr mode fwd dial host port tok car win ka snd rcv tl tp mtu
    local ttl awgport awgpriv awgpub awgobf
    IFS='|' read -r v kind tr mode fwd dial host port tok car win ka snd rcv tl tp mtu ttl awgport awgpriv awgpub awgobf <<TOKEN
$raw
TOKEN
    if [ -z "$tok" ] || [ -z "$tr" ]; then
        fail "the token is incomplete"
        pause; return 1
    fi

    cfg_reset
    server_info
    T_KIND="$kind"; T_TRANSPORT="$tr"; T_MODE="$mode"; T_FORWARDER="$fwd"
    T_TOKEN="$tok"; T_PORT="${port:-9443}"
    T_CARRIERS="$car"; T_WINDOW="$win"; T_KEEPALIVE="$ka"
    T_SNDBUF="${snd:-1024}"; T_RCVBUF="${rcv:-1024}"
    T_PRESET="$(preset_name "$car" "$win")"
    [ -n "$tl" ] && { T_TUNLOCAL="$tl"; T_TUNPEER="$tp"; T_TUNMTU="${mtu:-1380}"; }
    if kernel_transport; then
        # The kernel needs both public addresses whichever end this is, and
        # the token carries the sender's regardless of who dials.
        T_PEER_IP="$host"
        T_GRE_TTL="${ttl:-255}"
        T_AWG_PORT="${awgport:-51820}"
        T_AWG_PRIV="$awgpriv"   # made on the other server, for this one
        T_AWG_PUB="$awgpub"     # the other server's public half
        T_AWG_OBF="$awgobf"
    fi

    # A setup token is printed by the IRAN server and nowhere else, so a
    # machine pasting one is KHAREJ. There is nothing to ask: asking invited
    # the wrong answer, and the wrong answer built a tunnel with no address to
    # dial and no explanation of why it would not start.
    T_ROLE="client"
    if [ "$dial" = "1" ]; then
        # IRAN waits, so this end comes to it - the usual arrangement
        T_ACCEPTS="server"
        T_PEER_IP="$host"
    else
        # IRAN dials out, so this end is the one that waits
        T_ACCEPTS="client"
    fi

    say ""
    head2 "This server"
    dim "the token came from IRAN, so this is the KHAREJ side"
    say ""
    [ -n "$SRV_IP" ] && [ "$SRV_IP" != "unknown" ] && T_PUBLIC_IP="$SRV_IP"
    ask T_PUBLIC_IP "address of this KHAREJ server" "$T_PUBLIC_IP"
    [ -n "$T_PUBLIC_IP" ] || { fail "an address is required"; pause; return 1; }

    # The ports live on IRAN, which already has them - there is nothing to ask
    # for here, and nothing on this side to answer with.

    T_NAME="$(tunnel_default_name)"
    # The network came across in the token, so this end reaches the same name
    # the other end did without either of them being told what it is.
    local oct; oct="$(link_octet)" && T_NAME="$(tunnel_default_name "$oct")"
    if [ -f "$(cfg_file "$T_NAME")" ]; then
        say ""
        warn "a tunnel named $T_NAME already exists on this server"
        confirm "replace it?" || return 1
        systemctl stop "pingify@$T_NAME" >/dev/null 2>&1
    fi
    # The interface is named after the tunnel, which only just got its name.
    cfg_needs_link && T_TUNIF="$(link_iface "$T_NAME")"
    # A kernel tunnel runs no process of ours, so there is nothing to serve a
    # status endpoint and nothing that would read one.
    kernel_transport && T_STATUS="" || T_STATUS="127.0.0.1:$(pick_status_port 9700)"

    banner
    head2 "Ready to create"
    cfg_endpoints
    panel "$T_NAME"
    field "This server" "$(side_label "$T_ROLE")"
    field "Address" "$(addr_tint "$T_PUBLIC_IP")"
    field "Protocol" "$(transport_label "$T_TRANSPORT")"
    field "Forwarder" "$(forwarder_label "$T_FORWARDER")"
    if [ -n "$CFG_LISTEN" ]; then
        field "Link" "accepts on $(addr_tint "$CFG_LISTEN")"
    else
        field "Link" "dials $(addr_tint "$CFG_CONNECT")"
    fi
    cfg_needs_link && field "Private link" "$(addr_tint "$T_TUNLOCAL") ${BX_ARR} $(addr_tint "$T_TUNPEER")"
    [ -n "$T_FORWARDS" ] && field "Ports" "$(printf '%s' "$T_FORWARDS" | tr -d '"' | tr ',' ' ')"
    field "Token" "$(token_print "$T_TOKEN")"
    field "Carriers" "$T_CARRIERS"
    panel_end
    say ""
    confirm_yes "create the tunnel ${C_B}${T_NAME}${C_OFF}?" || { warn "cancelled"; pause; return 1; }

    say ""
    local file
    file="$(cfg_save)" || { pause; return 1; }
    # The core only judges configs it is going to run, and a kernel tunnel has
    # no core in the path - the same split the wizard makes.
    if ! kernel_transport; then
        if ! "$CORE_BIN" -c "$file" -check >/dev/null 2>&1; then
            fail "the core rejected this configuration"
            core_matches_script || dim "the core is $(core_version) and this script is $PINGIFY_VERSION"
            "$CORE_BIN" -c "$file" -check 2>&1 | sed 's/^/      /'
            rm -f "$file"
            pause; return 1
        fi
    fi
    write_units
    if kernel_transport; then
        [ "$T_TRANSPORT" = "awg" ] && awg_write_conf "$T_NAME" "$T_TUNIF" "$(awg_conf_path "$T_TUNIF")"
        write_link_unit "$T_NAME" || { fail "could not write the unit"; pause; return 1; }
    fi
    service_enable_start "$T_NAME"
    enable_watchdog quiet
    [ "$T_FORWARDER" = "iptables" ] && apply_nat quiet
    say ""
    ok "$T_NAME is configured and running"
    say ""
    tunnel_status_block "$T_NAME"
    pause
}

new_tunnel() {
    banner
    head2 "New tunnel"
    ensure_core || { pause; return 1; }
    cfg_reset
    wiz_reset
    server_info

    # -- which server is this ----------------------------------------------
    wiz "Which server is this?"
    choice 1 "IRAN" "clients connect here, and the ports live here"
    choice 2 "KHAREJ" "your panel and inbounds run here"
    choice 3 "Paste a token" "finish this server from the other one"
    say ""
    local side=""
    pick side "select" 1 2 3
    [ "$side" = "3" ] && { import_tunnel; return $?; }
    if [ "$side" = "2" ]; then T_ROLE="client"; else T_ROLE="server"; fi
    wiz_add "$(side_label "$T_ROLE")"

    # -- protocol -----------------------------------------------------------
    # One flat list. TUN-ICMP is not a category with something inside it: it
    # is a protocol you pick, and picking it is what brings up the local link.
    wiz "Protocol"
    choice 1 "TCP" "over the two public addresses - several connections at once"
    choice 2 "TUN-ICMP" "inside ping packets, over a private link - no port at all"
    choice 3 "TUN-GRE" "the kernel's own tunnel - fastest, but plainly visible"
    choice 4 "TUN-AWG" "obfuscated WireGuard - encrypted, and shaped not to look like it"
    say ""
    local proto=""
    pick proto "select" 1 2 3 4

    case "$proto" in
        2)  T_KIND="tun"; T_TRANSPORT="icmp"
            wiz "Who forwards the ports?"
            choice 1 "PINGIFY" "the core carries every connection itself"
            choice 2 "IPTABLES" "the kernel does it - lighter on a busy link"
            say ""
            local fw=""
            pick fw "select" 1 2
            if [ "$fw" = "2" ] && have iptables; then
                T_FORWARDER="iptables"
            else
                [ "$fw" = "2" ] && warn "iptables is not installed here - using PINGIFY"
                T_FORWARDER="pingify"
            fi ;;
        3)  T_TRANSPORT="gre"
            # GRE is protocol 47 with no encryption and no disguise. It is the
            # fastest thing here by a distance, and the easiest to recognise,
            # so say so before rather than after.
            say ""
            warn "GRE carries nothing secret and hides nothing"
            dim "it is the kernel moving packets with no encryption and no"
            dim "obfuscation, so anything watching the path can see what it is."
            dim "Fast, and worth it where the path still allows it."
            say ""
            confirm_yes "use TUN-GRE?" || return 0
            gre_ready || { fail "this kernel has no GRE support"; pause; return 1; } ;;
        4)  T_TRANSPORT="awg"
            awg_install || { pause; return 1; } ;;
        *)  T_KIND="tcp"; T_TRANSPORT="tcp"
            T_FORWARDER="pingify" ;;
    esac
    cfg_mode

    # -- which way the link is opened, TCP only ----------------------------
    #
    # Ports live on IRAN either way and clients always arrive there. This is
    # only about which end makes the TCP connection, and it matters because
    # the two are not equally reachable: one Iranian server here takes an
    # inbound connection and runs at 100 Mbit/s with no retransmits, another
    # accepts it and then loses the flow a few kilobytes in. If one direction
    # will not stay up, the other usually will.
    #
    # Reverse is what a Pingify tunnel is. IRAN accepts and KHAREJ comes to
    # it, which is the arrangement ICMP has always used and the one every
    # other transport starts from.
    #
    # TCP is asked because there it can fail: an Iranian server that will not
    # hold an inbound connection has no way to be reached, and turning the
    # link around is the only thing that helps. ICMP is not asked - it has no
    # port to be reachable on, so there is nothing to choose.
    T_ACCEPTS="server"
    if [ "$T_TRANSPORT" = "tcp" ]; then
        wiz "Link direction"
        CHOICE_DEF="1"
        choice 1 "Reverse" "KHAREJ opens the connection to IRAN - the usual one"
        choice 2 "Direct" "IRAN opens it to KHAREJ - when inbound to IRAN will not hold"
        CHOICE_DEF=""
        say ""
        local dir=""
        ask dir "select" "1"
        if [ "$dir" = "2" ]; then
            T_ACCEPTS="client"      # KHAREJ accepts; IRAN dials out
        else
            T_ACCEPTS="server"      # IRAN accepts; KHAREJ dials in
        fi
    fi

    # -- where the servers are ---------------------------------------------
    #
    # Both addresses, always. The far one is obvious - somebody has to be
    # dialled or answered. The near one matters on a server with more than one
    # address: ICMP answers from whatever the kernel picks otherwise, and a
    # reply that leaves from an address the far end is not expecting is a reply
    # the far end throws away.
    wiz "Addresses"
    if [ -n "$SRV_IP" ] && [ "$SRV_IP" != "unknown" ]; then
        T_PUBLIC_IP="$SRV_IP"
        dim "this machine reports ${C_OFF}${SRV_IP}${C_DIM} - press enter to take it"
        say ""
    fi
    ask T_PUBLIC_IP "address of this $(side_label "$T_ROLE") server" "$T_PUBLIC_IP"
    [ -n "$T_PUBLIC_IP" ] || { fail "an address is required"; pause; return 1; }

    say ""
    ask T_PEER_IP "address of the $( [ "$T_ROLE" = "server" ] && echo KHAREJ || echo IRAN ) server" "$T_PEER_IP"
    [ -n "$T_PEER_IP" ] || { fail "an address is required"; pause; return 1; }

    if [ "$T_TRANSPORT" = "tcp" ]; then
        say ""
        ask T_PORT "port for the tunnel itself, same on both" "$T_PORT"
        case "$T_PORT" in "" | *[!0-9]*) T_PORT=9443 ;; esac
        this_side_accepts && dim "leave $T_PORT open in this server's firewall"
    elif [ "$T_TRANSPORT" = "awg" ]; then
        say ""
        ask T_AWG_PORT "UDP port for the tunnel, same on both" "$T_AWG_PORT"
        case "$T_AWG_PORT" in "" | *[!0-9]*) T_AWG_PORT=51820 ;; esac
        dim "leave ${T_AWG_PORT}/udp open in this server's firewall"
    fi
    say ""

    # -- name, derived ------------------------------------------------------
    # iran-9443 on the Iran server, kharej-9443 abroad, iran-icmp for a TUN
    # tunnel. Two servers side by side say what they are without either file
    # being opened, and there is nothing to answer.
    #
    # Provisional for now. When this server already holds a tunnel of the same
    # kind, what tells the two apart is the private network they sit on - and
    # that is not known until it has been asked for, a few lines down.
    T_NAME="$(tunnel_default_name)"

    # -- the private link, whenever one is needed --------------------------
    #
    # Each transport pays a different tax on every packet, so the starting MTU
    # follows the transport: GRE adds 24 bytes, AmneziaWG adds its own header
    # plus the junk it pads with, and ICMP carries ours.
    case "$T_TRANSPORT" in
        gre) T_TUNMTU=1400 ;;
        awg) T_TUNMTU=1320 ;;
    esac
    if cfg_needs_link; then
        wiz "Private link" "Both servers get an address on a small network of their own."
        # Two tunnels on one network route into each other, and the symptom is
        # traffic going somewhere it was not meant to with nothing on the
        # server to explain it. So say what is taken, offer one that is not,
        # and do not accept a repeat.
        show_taken_nets "$T_NAME"
        local octet="" owner=""
        while :; do
            ask octet "range 10.x.10.0/24 - pick x" "$(free_link_octet "$T_NAME")"
            case "$octet" in
                '' | *[!0-9]*) fail "a number from 0 to 255"; continue ;;
            esac
            [ "$octet" -le 255 ] || { fail "a number from 0 to 255"; continue; }
            owner="$(net_owner "10.${octet}.10" "$T_NAME")"
            if [ -n "$owner" ]; then
                fail "10.${octet}.10.0/24 already belongs to $owner"
                dim "pick another x, or delete that tunnel first"
                continue
            fi
            if host_has_net "10.${octet}.10"; then
                fail "this server already has an address on 10.${octet}.10.0/24"
                dim "something else is on that network - docker, or another VPN"
                continue
            fi
            break
        done
        if [ "$T_ROLE" = "server" ]; then
            T_TUNLOCAL="10.${octet}.10.1/24"; T_TUNPEER="10.${octet}.10.2/24"
        else
            T_TUNLOCAL="10.${octet}.10.2/24"; T_TUNPEER="10.${octet}.10.1/24"
        fi
        say ""
        ask T_TUNLOCAL "this server" "$T_TUNLOCAL"
        ask T_TUNPEER  "the other server" "$T_TUNPEER"

        # Now the name carries the network - always, not only when two of
        # them collide. Ten GRE tunnels where one is bare and nine are
        # numbered is not an order, it is an exception with nine examples.
        # Every one of these reads the same and says where to find it:
        # tun-iran-gre-20 is the tunnel on 10.20.10.0/24.
        local oct; oct="$(link_octet)" && T_NAME="$(tunnel_default_name "$oct")"
        T_TUNIF="$(link_iface "$T_NAME")"
        say ""
        # A kernel tunnel's interface is named after the tunnel, so there is
        # nothing to answer; ours is ours to choose - and has to be one that
        # is not already taken, or the second tunnel cannot create it.
        if ! kernel_transport; then
            local iface_owner_name=""
            while :; do
                ask T_TUNIF "device name" "$(free_tun_iface "$T_NAME" "$T_NAME")"
                case "$T_TUNIF" in
                    '' | *[!a-zA-Z0-9_-]*) fail "letters, digits, dash and underscore"; continue ;;
                esac
                [ "${#T_TUNIF}" -le 15 ] || { fail "linux stops at 15 characters"; continue; }
                iface_owner_name="$(iface_owner "$T_TUNIF" "$T_NAME")"
                if [ -n "$iface_owner_name" ]; then
                    fail "$T_TUNIF already belongs to $iface_owner_name"
                    continue
                fi
                if host_has_iface "$T_TUNIF"; then
                    fail "this server already has an interface called $T_TUNIF"
                    continue
                fi
                break
            done
        fi
        ask T_TUNMTU   "MTU" "$T_TUNMTU"
        case "$T_TUNMTU" in "" | *[!0-9]*) T_TUNMTU=1380 ;; esac
    fi

    # Whatever is left over - a TCP tunnel has no network to name itself
    # after, and a private one whose addresses were hand-set may not either.
    if [ -f "$(cfg_file "$T_NAME")" ]; then
        local n=2
        while [ -f "$(cfg_file "${T_NAME}-${n}")" ]; do n=$((n + 1)); done
        T_NAME="${T_NAME}-${n}"
        cfg_needs_link && T_TUNIF="$(link_iface "$T_NAME")"
    fi
    say ""
    ok "this tunnel is called ${C_B}${T_NAME}${C_OFF}"

    # -- AmneziaWG keys -----------------------------------------------------
    #
    # WireGuard needs a real keypair on each side, and each side needs the
    # other's public half. Normally that is two visits to two servers with a
    # key carried between them, and the script this came from asks for exactly
    # that. Both pairs are made here instead and the other server's half rides
    # in the setup token with everything else, because the token is already
    # the secret that carries the tunnel and one trip is better than three.
    local awg_peer_priv="" awg_self_pub=""
    if [ "$T_TRANSPORT" = "awg" ]; then
        local mine theirs
        mine="$(awg_keypair)"   || { fail "awg genkey failed"; pause; return 1; }
        theirs="$(awg_keypair)" || { fail "awg genkey failed"; pause; return 1; }
        T_AWG_PRIV="${mine%% *}"          # ours, kept here
        T_AWG_PUB="${theirs##* }"         # the other server's, listed as peer
        awg_peer_priv="${theirs%% *}"     # the other server's, travels
        awg_self_pub="${mine##* }"        # ours, travels
        T_AWG_OBF="$(awg_new_obf)"
    fi

    # -- security ----------------------------------------------------------
    wiz "Security token" "One secret, typed the same on BOTH servers. Any length."
    # What it actually does differs by transport, and saying so is better than
    # letting somebody assume GRE is encrypted because they were asked for a
    # password.
    case "$T_TRANSPORT" in
        awg) dim "here it becomes the pre-shared key WireGuard mixes into every"
             dim "handshake: without a matching one, the tunnel does not form." ;;
        gre) dim "GRE has no encryption. Here the token becomes the key GRE"
             dim "stamps on each packet, which keeps two tunnels apart - it"
             dim "does not hide anything, because GRE cannot." ;;
        *)   dim "it keys the encryption on every frame this tunnel carries." ;;
    esac
    say ""
    while :; do
        ask T_TOKEN "token"
        T_TOKEN="$(printf '%s' "$T_TOKEN" | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//')"
        [ -n "$T_TOKEN" ] && break
        fail "a token is required"
    done
    say ""
    ok "fingerprint  ${C_YEL}$(token_print "$T_TOKEN")${C_OFF}"

    # -- ports: the IRAN side owns them ------------------------------------
    if [ "$T_ROLE" = "server" ]; then
        wiz "Ports" "The ports your clients will connect to, here on IRAN."
        # Two tunnels forwarding one port means whichever bound it first wins,
        # and the other simply never sees a connection. Say what is taken, and
        # do not accept a port that is.
        show_taken_ports "$T_NAME"
        dim "443   443=8443   443=10.0.0.5:443   udp:500   8000-8010"
        say ""
        local raw="" clash=""
        while :; do
            ask raw "ports, comma separated" "443"
            T_FORWARDS="$(parse_forwards "$raw")"
            if [ -z "$T_FORWARDS" ]; then
                fail "at least one port is required"
                continue
            fi
            clash="$(forwards_clash "$raw" "$T_NAME")" && break
            printf '%s\n' "$clash" | while read -r line; do
                [ -n "$line" ] && fail "$line"
            done
            dim "pick another port, or free that one first"
        done
    fi

    # -- performance -------------------------------------------------------
    wiz "Performance" "Pick the shape of your traffic; you can change it later."
    preset_menu

    # -- logging -----------------------------------------------------------
    wiz "How much to log" "Each level includes the ones above it."
    CHOICE_DEF="3"
    choice 1 "error" "only what is broken"
    choice 2 "warn" "and what is wrong but survivable"
    choice 3 "info" "and what a healthy tunnel does"
    choice 4 "debug" "and why each carrier and stream did what it did"
    choice 5 "trace" "and every packet - slows a busy tunnel down"
    CHOICE_DEF=""
    say ""
    local lg=""
    ask lg "select" "3"
    case "$lg" in
        1) T_LOG="error" ;; 2) T_LOG="warn" ;;
        4) T_LOG="debug" ;; 5) T_LOG="trace" ;;
        *) T_LOG="info" ;;
    esac

    # A kernel tunnel runs no process of ours, so there is nothing to serve a
    # status endpoint and nothing that would read one.
    kernel_transport && T_STATUS="" || T_STATUS="127.0.0.1:$(pick_status_port 9700)"

    # -- review ------------------------------------------------------------
    banner
    cfg_endpoints
    head2 "Ready to create"
    panel "$T_NAME"
    field "This server" "$(side_label "$T_ROLE")"
    field "Address" "$(addr_tint "$T_PUBLIC_IP")"
    if [ "$T_KIND" = "tun" ]; then
        field "Type" "TUN over $(transport_label "$T_TRANSPORT")"
    else
        field "Type" "$(transport_label "$T_TRANSPORT")"
    fi
    field "Forwarder" "$(forwarder_label "$T_FORWARDER")"
    if [ -n "$CFG_LISTEN" ]; then
        field "Link" "accepts on $(addr_tint "$CFG_LISTEN")"
    else
        field "Link" "connects to $(addr_tint "$CFG_CONNECT")"
    fi
    cfg_needs_link && field "Private link" "$(addr_tint "$T_TUNLOCAL") ${BX_ARR} $(addr_tint "$T_TUNPEER")"
    [ -n "$T_FORWARDS" ] && field "Ports" "$(printf '%s' "$T_FORWARDS" | tr -d '"' | tr ',' ' ')"
    field "Token" "$(token_print "$T_TOKEN")"
    field "Tuning" "$T_PRESET"
    field "Logging" "$T_LOG"
    panel_end
    say ""
    if ! confirm_yes "create the tunnel ${C_B}${T_NAME}${C_OFF}?"; then
        warn "cancelled, nothing was written"
        pause
        return 1
    fi

    # -- write and start ---------------------------------------------------
    say ""
    local file
    file="$(cfg_save)" || { pause; return 1; }
    # The core only judges configs it is going to run. A kernel tunnel has no
    # core in the path at all, so asking it would be asking the wrong program.
    if ! kernel_transport; then
        if ! "$CORE_BIN" -c "$file" -check >/dev/null 2>&1; then
            fail "the core rejected this configuration"
            core_matches_script || dim "the core is $(core_version) and this script is $PINGIFY_VERSION - update the core"
            "$CORE_BIN" -c "$file" -check 2>&1 | sed 's/^/      /'
            rm -f "$file"
            pause; return 1
        fi
    fi

    write_units
    if kernel_transport; then
        [ "$T_TRANSPORT" = "awg" ] && awg_write_conf "$T_NAME" "$T_TUNIF" "$(awg_conf_path "$T_TUNIF")"
        write_link_unit "$T_NAME" || { fail "could not write the unit"; pause; return 1; }
    fi
    service_enable_start "$T_NAME"
    enable_watchdog quiet
    # Unconditional: apply_nat tears the chains down when no tunnel needs
    # them, so this is also what cleans up after a forwarder that changed.
    apply_nat quiet

    # An ICMP tunnel wants this server quiet. The kernel answering ordinary
    # pings never touches our own traffic - the transport is a raw socket the
    # kernel copies to us regardless, and both ends send echo *replies*, which
    # the kernel never answers by itself - but a tunnel hiding inside ping is
    # not helped by a host that cheerfully answers every scanner that asks.
    if [ "$T_TRANSPORT" = "icmp" ] && [ "$T_ROLE" = "server" ] && [ "$(block_state icmp)" != "on" ]; then
        mkdir -p "$STATE_DIR"
        : > "$STATE_DIR/block-icmp"
        apply_blocking quiet
        ok "this server no longer answers pings (Blocking ${BX_ARR} ICMP, to undo)"
    fi

    ok "$T_NAME is running"
    dim "$file"
    say ""

    # -- the other server --------------------------------------------------
    #
    # Only IRAN prints one. A token is a description of the tunnel written
    # from the point of view of the end that owns the ports, and the KHAREJ
    # end is what it builds - so a token printed there has nowhere to go, and
    # printing one anyway taught people to carry it the wrong way round.
    if [ "$T_ROLE" = "server" ]; then
        head2 "Now the KHAREJ server"
        dim "run Pingify there and choose  New tunnel ${BX_ARR} Paste a token"
        say ""
        rule
        printf '%s\n' "${C_YEL}$(cfg_setup_token)${C_OFF}"
        rule
        say ""
        warn "treat it like a password - it carries the security token"
    else
        head2 "Both servers are set up"
        dim "this end was built from IRAN's token, so there is nothing to carry back"
    fi
    say ""
    tunnel_status_block "$T_NAME"
    pause
}

# ---------------------------------------------------------------------------
# forwarders
#
# Two ways to get a client on the IRAN server through to a service on KHAREJ.
#
#   pingify   The core does it. It accepts the connection, multiplexes it over
#             the carriers and opens the far side itself. Every byte is
#             encrypted end to end by the core, it works over any transport,
#             and it needs nothing from the kernel.
#
#   iptables  The kernel does it. A private layer-3 link is brought up between
#             the two servers and the traffic is NATed onto it, so a packet is
#             never copied into user space at all. Less CPU and more headroom
#             on a busy tunnel - at the cost of only working over a full-IP
#             link, and of touching the NAT table.
#
# Rules live in Pingify's own chains, so nothing your panel installed is
# disturbed, and a boot unit puts them back after a restart.
# ---------------------------------------------------------------------------

forwarder_label() {
    case "$1" in
        iptables) printf 'IPTABLES' ;;
        *)        printf 'PINGIFY' ;;
    esac
}

# nat_chains prepares the two chains and hooks them in once.
nat_chains() {
    local c
    for c in PINGIFY_NAT PINGIFY_POST; do
        iptables -t nat -N "$c" 2>/dev/null || iptables -t nat -F "$c" 2>/dev/null
    done
    iptables -t nat -C PREROUTING  -j PINGIFY_NAT  2>/dev/null || iptables -t nat -I PREROUTING 1  -j PINGIFY_NAT
    iptables -t nat -C OUTPUT      -j PINGIFY_NAT  2>/dev/null || iptables -t nat -I OUTPUT 1      -j PINGIFY_NAT
    iptables -t nat -C POSTROUTING -j PINGIFY_POST 2>/dev/null || iptables -t nat -I POSTROUTING 1 -j PINGIFY_POST
}

# The mangle chain, for the one rule that decides whether a tunnel is quick
# or merely connected.
mss_chain() {
    iptables -t mangle -N PINGIFY_MSS 2>/dev/null || iptables -t mangle -F PINGIFY_MSS 2>/dev/null
    iptables -t mangle -C FORWARD -j PINGIFY_MSS 2>/dev/null || iptables -t mangle -I FORWARD 1 -j PINGIFY_MSS
    iptables -t mangle -C OUTPUT  -j PINGIFY_MSS 2>/dev/null || iptables -t mangle -I OUTPUT 1  -j PINGIFY_MSS
}

mss_drop_chain() {
    iptables -t mangle -D FORWARD -j PINGIFY_MSS 2>/dev/null
    iptables -t mangle -D OUTPUT  -j PINGIFY_MSS 2>/dev/null
    iptables -t mangle -F PINGIFY_MSS 2>/dev/null
    iptables -t mangle -X PINGIFY_MSS 2>/dev/null
}

nat_drop_chains() {
    mss_drop_chain
    iptables -t nat -D PREROUTING  -j PINGIFY_NAT  2>/dev/null
    iptables -t nat -D OUTPUT      -j PINGIFY_NAT  2>/dev/null
    iptables -t nat -D POSTROUTING -j PINGIFY_POST 2>/dev/null
    local c
    for c in PINGIFY_NAT PINGIFY_POST; do
        iptables -t nat -F "$c" 2>/dev/null
        iptables -t nat -X "$c" 2>/dev/null
    done
}

# nat_rules_for writes the rules one tunnel needs. Both ends need a rule: the
# IRAN side sends the traffic across the private link, and the KHAREJ side
# turns it back towards whatever is listening on loopback.
nat_rules_for() {
    local name="$1"
    cfg_load "$name" || return 1
    [ "$T_FORWARDER" = "iptables" ] || return 0
    # a private link is what the rules route onto; forward-only has none
    [ "$T_MODE" != "forward" ] || return 0

    local peer_ip local_ip
    peer_ip="${T_TUNPEER%%/*}"
    local_ip="${T_TUNLOCAL%%/*}"
    [ -n "$peer_ip" ] && [ -n "$local_ip" ] || return 1

    sysctl -w net.ipv4.ip_forward=1 >/dev/null 2>&1
    # DNAT to a loopback address is refused unless this is on.
    sysctl -w net.ipv4.conf.all.route_localnet=1 >/dev/null 2>&1

    local spec proto lport rport target
    for spec in $(printf '%s' "$T_FORWARDS" | tr -d '"' | tr ',' ' '); do
        proto=tcp
        case "$spec" in
            udp:*) proto=udp; spec="${spec#udp:}" ;;
            tcp:*) spec="${spec#tcp:}" ;;
        esac
        lport="${spec%%=*}"
        rport="${spec#*=}"
        [ "$rport" = "$spec" ] && rport="$lport"
        case "$lport$rport" in *[!0-9-]*) continue ;; esac

        # Only the IRAN side has rules: it sends the traffic straight to the
        # other server's private address. Nothing is needed over there, as
        # long as the service listens on 0.0.0.0 rather than loopback alone.
        if [ "$T_ROLE" = "server" ]; then
            target="$peer_ip:$rport"
            iptables -t nat -A PINGIFY_NAT -p "$proto" --dport "$lport" \
                     ! -s "$peer_ip" -j DNAT --to-destination "$target" 2>/dev/null
        fi
    done

    # Replies have to come back the way they came.
    iptables -t nat -A PINGIFY_POST -o "$T_TUNIF" -j MASQUERADE 2>/dev/null

    # And the rule that decides whether this is quick or merely connected.
    #
    # A tunnel carries a smaller packet than the path it rides on. Two ends
    # setting up a TCP session through it agree a segment size from what their
    # own interfaces can take, which is larger than the tunnel - so the first
    # real transfer sends a packet that will not fit and the session stalls
    # while both sides patiently retry it. It looks exactly like a slow link,
    # and no amount of tuning on either end helps, because nothing on either
    # end is wrong.
    #
    # Clamping the announced size to what the tunnel actually carries is the
    # fix, and it costs one rule.
    iptables -t mangle -A PINGIFY_MSS -o "$T_TUNIF" -p tcp --syn -j TCPMSS --clamp-mss-to-pmtu 2>/dev/null

    # Asymmetric routing is normal on a tunnel - the reply comes back on a
    # different interface than the kernel would have chosen - and the reverse
    # path filter drops exactly that.
    sysctl -w "net.ipv4.conf.${T_TUNIF}.rp_filter=0" >/dev/null 2>&1

    # And the queue on the tunnel itself. A single deep FIFO is what makes a
    # loaded tunnel feel bad rather than merely full: one large download fills
    # it, and every small packet behind it - a video's next chunk request, a
    # chat message, an ACK - waits behind the whole backlog. The delay shows
    # up as stalling and buffering while the throughput graph looks fine.
    #
    # fq_codel gives each flow its own queue and keeps them short, so a big
    # transfer stops delaying everything travelling with it.
    if have tc; then
        tc qdisc replace dev "$T_TUNIF" root fq_codel >/dev/null 2>&1
    fi
    return 0
}

# apply_nat rebuilds every tunnel's rules from its config.
apply_nat() {
    local quiet="${1:-}"
    have iptables || { [ "$quiet" = quiet ] || warn "iptables is not installed"; return 1; }
    local any=0 n
    for n in $(tunnel_names); do
        if [ "$(toml_get "$(cfg_file "$n")" forward forwarder)" = "iptables" ]; then
            any=1
        fi
    done
    if [ "$any" = "0" ]; then
        nat_drop_chains
        return 0
    fi
    nat_chains
    mss_chain
    # Each in its own shell. nat_rules_for reads a config with cfg_load, which
    # writes every T_ variable there is - and this is called from the middle of
    # the wizard, where those variables are the tunnel being built. It was
    # overwriting them with whichever config happened to be read last, so the
    # setup token described a different tunnel and the "is running" line named
    # one too.
    for n in $(tunnel_names); do ( nat_rules_for "$n" ); done
    # The ping block exempts each tunnel's own interface by name, so the set
    # of tunnels changing means those rules have to be rebuilt too.
    [ "$(block_state icmp)" = "on" ] && apply_blocking quiet
    [ "$quiet" = quiet ] || ok "forwarding rules applied"
    return 0
}

# show_nat - every rule Pingify has put in the firewall, and nothing else.
#
# Worth being clear about what this is, because the old wording read as though
# Pingify were an iptables tool. It is not. A tunnel is carried by the engine
# or by the kernel, and the firewall only ever gets involved for two reasons:
#
#   forwarding   only when a tunnel's forwarder is IPTABLES - the kernel NATs
#                onto the private link. A tunnel forwarded by PINGIFY has the
#                core carrying each connection itself and needs no rule at all.
#
#   blocking     the switches under Blocking - ping, speedtest sites, QUIC.
#
# Everything lives in chains named PINGIFY_*, hooked into the built-in ones, so
# nothing here touches a rule you or your panel put in place. An empty list is
# a normal state, not a fault.
show_nat() {
    say ""
    if ! have iptables; then
        warn "iptables is not installed on this server"
        dim "so nothing here uses it - a tunnel forwarded by PINGIFY does not"
        dim "need it, and one forwarded by IPTABLES could not be built"
        return
    fi

    local any=0 out

    out="$(iptables -t nat -S PINGIFY_NAT 2>/dev/null | grep -v '^-N ')"
    if [ -n "$out" ]; then
        any=1
        head2 "Forwarding"
        dim "sends a port on this server across the private link"
        say ""
        printf '%s\n' "$out" | sed 's/^/    /'
        say ""
        out="$(iptables -t nat -S PINGIFY_POST 2>/dev/null | grep -v '^-N ')"
        [ -n "$out" ] && printf '%s\n' "$out" | sed 's/^/    /'
        say ""
    fi

    out="$(iptables -t mangle -S PINGIFY_MSS 2>/dev/null | grep -v '^-N ')"
    if [ -n "$out" ]; then
        any=1
        head2 "Segment size"
        dim "clamps what a TCP session announces to what the tunnel can carry -"
        dim "without it, large transfers stall on a packet that will not fit"
        say ""
        printf '%s\n' "$out" | sed 's/^/    /'
        say ""
    fi

    out="$(iptables -S PINGIFY_IN 2>/dev/null | grep -v '^-N ')"
    out="$out$(iptables -S PINGIFY_OUT 2>/dev/null | grep -v '^-N ')"
    if [ -n "$out" ]; then
        any=1
        head2 "Blocking"
        dim "the switches under Blocking in the main menu"
        say ""
        iptables -S PINGIFY_IN  2>/dev/null | grep -v '^-N ' | sed 's/^/    /'
        iptables -S PINGIFY_OUT 2>/dev/null | grep -v '^-N ' | sed 's/^/    /'
        say ""
    fi

    if [ "$any" = "0" ]; then
        ok "Pingify has no firewall rules on this server"
        say ""
        dim "Which is normal. Rules appear only when a tunnel is forwarded by"
        dim "IPTABLES rather than by the core, or when something under Blocking"
        dim "is switched on."
    fi
}

# ---------------------------------------------------------------------------
# what is already spoken for
#
# Two tunnels on one private network route into each other. Two tunnels
# forwarding one port means whichever bound it first wins. Both fail quietly -
# the traffic goes somewhere, just not where it was meant to - and nothing on
# the server explains it afterwards.
#
# So both are checked before the answer is taken, against the configs on this
# machine and what the kernel already has bound, which together are the only
# places that know.
# ---------------------------------------------------------------------------

# cfg_files - every tunnel config here, one per line
cfg_files() {
    local f
    for f in "$CFG_DIR"/*.toml "$CFG_DIR"/*.json; do
        [ -f "$f" ] && printf '%s\n' "$f"
    done
    return 0
}

# list_has LIST ITEM - is ITEM one whole line of LIST?
#
# Written without a pipe on purpose. "generator | grep -q" is a race whenever
# pipefail is set: grep exits at the first match, the generator takes a
# SIGPIPE, and the pipeline then reports 141 instead of 0 - so the answer
# depends on which of the two got there first. It is intermittent, it is
# invisible, and it is exactly the kind of wrong answer this file exists to
# stop being given.
list_has() {
    local list="$1" item="$2" nl='
'
    [ -n "$item" ] || return 1
    case "$nl$list$nl" in
        *"$nl$item$nl"*) return 0 ;;
    esac
    return 1
}

# cfg_name FILE - the tunnel's own name, falling back to the filename
cfg_name() {
    local n
    n="$(toml_get "$1" tunnel name)"
    if [ -z "$n" ]; then
        n="$(basename "$1")"
        n="${n%.toml}"; n="${n%.json}"
    fi
    printf '%s' "$n"
}

# ---------------------------------------------------------------------------
# private networks
# ---------------------------------------------------------------------------

# tun_nets [EXCEPT] - "network name" for every private link claimed here,
# skipping one tunnel by name so editing its own settings is not a clash.
tun_nets() {
    local except="${1:-}" f addr name
    cfg_files | while read -r f; do
        addr="$(toml_get "$f" tun local_addr)"
        [ -n "$addr" ] || continue
        name="$(cfg_name "$f")"
        [ -n "$except" ] && [ "$name" = "$except" ] && continue
        printf '%s %s\n' "${addr%.*}" "$name"
    done
    return 0
}

# net_owner NETWORK [EXCEPT] - the tunnel using it, or nothing. NETWORK is the
# first three octets with no mask, e.g. 10.10.10
net_owner() {
    local want="$1" except="${2:-}"
    tun_nets "$except" | while read -r net name; do
        if [ "$net" = "$want" ]; then
            printf '%s' "$name"
            break
        fi
    done
    return 0
}

# host_nets - the /24s this machine already has an address on. Docker, another
# VPN and the provider's own private range all show up here, and a tunnel that
# shadows one of them quietly takes traffic that was not meant for it.
host_nets() {
    have ip || return 0
    ip -4 -o addr show 2>/dev/null | awk '{print $4}' | while read -r cidr; do
        [ -n "$cidr" ] && printf '%s\n' "${cidr%.*}"
    done
    return 0
}

host_has_net() {
    local want="$1"
    list_has "$(host_nets)" "$want"
}

# free_link_octet [EXCEPT] - the first x where 10.x.10.0/24 is free, so the
# default offered is one that will be accepted.
free_link_octet() {
    local except="${1:-}" x=10
    while [ "$x" -lt 250 ]; do
        if [ -z "$(net_owner "10.${x}.10" "$except")" ] && ! host_has_net "10.${x}.10"; then
            printf '%s' "$x"
            return 0
        fi
        x=$((x + 1))
    done
    printf '10'
    return 1
}

# this_side - IRAN, KHAREJ, or nothing when there is no tunnel to tell from.
#
# Every tunnel on one machine is the same end of the link, so the first one
# answers for all of them. Worth knowing wherever a screen has to say "run
# this one here and that one over there".
this_side() {
    local f role
    cfg_files | while read -r f; do
        role="$(toml_get "$f" tunnel role)"
        [ -n "$role" ] || continue
        [ "$role" = "server" ] && printf 'IRAN' || printf 'KHAREJ'
        break
    done
    return 0
}

# ---------------------------------------------------------------------------
# tunnel devices
#
# A GRE or AmneziaWG device is named after its tunnel, so two can never
# collide. The core's own TUN device is answered for, and the answer offered
# was pfy0 every time - so a second ICMP tunnel took the name of the first and
# then could not create its interface.
# ---------------------------------------------------------------------------

tun_ifaces() {
    local except="${1:-}" f iface name
    cfg_files | while read -r f; do
        iface="$(toml_get "$f" tun name)"
        [ -n "$iface" ] || continue
        name="$(cfg_name "$f")"
        [ -n "$except" ] && [ "$name" = "$except" ] && continue
        printf '%s %s
' "$iface" "$name"
    done
    return 0
}

iface_owner() {
    local want="$1" except="${2:-}"
    tun_ifaces "$except" | while read -r iface name; do
        if [ "$iface" = "$want" ]; then
            printf '%s' "$name"
            break
        fi
    done
    return 0
}

# host_has_iface NAME - this machine already has an interface by that name,
# whether Pingify made it or not
host_has_iface() {
    have ip || return 1
    ip link show "$1" >/dev/null 2>&1
}

# free_tun_iface [TUNNEL] [EXCEPT] - a device name that is free and says what
# it is. pfy0 said nothing: not which tunnel it belonged to, not what it
# carried, and on a server with two of them not even which was which. The name
# is derived from the tunnel instead - icmp-iran beside gre-iran and
# awg-kharej - and only falls back to counting when that one is taken.
free_tun_iface() {
    local tunnel="${1:-}" except="${2:-}" base n=2
    if [ -n "$tunnel" ]; then
        base="$(link_iface "$tunnel")"
    else
        base="pfy0"
    fi
    if [ -z "$(iface_owner "$base" "$except")" ] && ! host_has_iface "$base"; then
        printf '%s' "$base"
        return 0
    fi
    while [ "$n" -lt 64 ]; do
        if [ -z "$(iface_owner "${base}${n}" "$except")" ] && ! host_has_iface "${base}${n}"; then
            printf '%s%s' "$base" "$n"
            return 0
        fi
        n=$((n + 1))
    done
    printf '%s' "$base"
    return 1
}

# ---------------------------------------------------------------------------
# ports
# ---------------------------------------------------------------------------

# ports_of FILE - every single port that config forwards, one per line, with
# ranges expanded and the udp:/tcp: prefixes and =target parts stripped.
ports_of() {
    local f="$1" spec p lo hi pt
    for spec in $(toml_arr "$f" ports | tr -d '"' | tr ',' ' '); do
        p="${spec%%=*}"; p="${p#udp:}"; p="${p#tcp:}"
        case "$p" in
            *-*) lo="${p%%-*}"; hi="${p##*-}" ;;
            *)   lo="$p"; hi="$p" ;;
        esac
        case "$lo" in '' | *[!0-9]*) continue ;; esac
        case "$hi" in '' | *[!0-9]*) continue ;; esac
        [ "$hi" -ge "$lo" ] || continue
        # A range wider than this is a mistake being made, not a range.
        [ "$((hi - lo))" -gt 512 ] && hi="$((lo + 512))"
        pt="$lo"
        while [ "$pt" -le "$hi" ]; do
            printf '%s\n' "$pt"
            pt=$((pt + 1))
        done
    done
    return 0
}

# port_owner PORT [EXCEPT] - the tunnel already forwarding it, or nothing
port_owner() {
    local want="$1" except="${2:-}" f name
    case "$want" in '' | *[!0-9]*) return 0 ;; esac
    cfg_files | while read -r f; do
        name="$(cfg_name "$f")"
        [ -n "$except" ] && [ "$name" = "$except" ] && continue
        if list_has "$(ports_of "$f")" "$want"; then
            printf '%s' "$name"
            break
        fi
    done
    return 0
}

# listening_ports - every port with something bound to it, asked once. Per
# port it would be one ss call each, which on a range is a visible pause.
listening_ports() {
    have ss || return 0
    ss -Hltun 2>/dev/null | awk '{print $5}' | sed 's/.*://' | sort -u
    return 0
}

# forwards_clash SPECS [EXCEPT] - print one line per port that is already
# taken, by another tunnel or by something already listening. Returns 0 when
# there is nothing wrong, so it reads as "these forwards are fine".
forwards_clash() {
    local raw="$1" except="${2:-}" bad=0 bound mine="" spec p lo hi pt who
    bound="$(listening_ports)"
    # A tunnel being edited already has its own ports bound, by its own
    # service. Keeping one of them is not a clash with anything, and calling
    # it one would make the port list impossible to edit without emptying it
    # first.
    if [ -n "$except" ] && [ -f "$(cfg_file "$except")" ]; then
        mine="$(ports_of "$(cfg_file "$except")")"
    fi
    raw="$(printf '%s' "$raw" | tr -d '"' | tr ',' ' ')"
    for spec in $raw; do
        p="${spec%%=*}"; p="${p#udp:}"; p="${p#tcp:}"
        case "$p" in
            *-*) lo="${p%%-*}"; hi="${p##*-}" ;;
            *)   lo="$p"; hi="$p" ;;
        esac
        case "$lo" in '' | *[!0-9]*) continue ;; esac
        case "$hi" in '' | *[!0-9]*) continue ;; esac
        [ "$hi" -ge "$lo" ] || continue
        [ "$((hi - lo))" -gt 512 ] && hi="$((lo + 512))"
        pt="$lo"
        while [ "$pt" -le "$hi" ]; do
            who="$(port_owner "$pt" "$except")"
            if [ -n "$who" ]; then
                printf 'port %s is already forwarded by %s\n' "$pt" "$who"
                bad=1
            elif list_has "$mine" "$pt"; then
                : # its own port, bound by its own service
            elif list_has "$bound" "$pt"; then
                printf 'port %s already has something listening on it\n' "$pt"
                bad=1
            fi
            pt=$((pt + 1))
        done
    done
    [ "$bad" = "0" ]
}

# ---------------------------------------------------------------------------
# saying so
# ---------------------------------------------------------------------------

# show_taken_nets [EXCEPT] - the yellow block above the question, listing what
# is already spoken for. Silent when nothing is.
show_taken_nets() {
    local except="${1:-}" taken
    taken="$(tun_nets "$except")"
    [ -n "$taken" ] || return 0
    warn "private networks already used on this server"
    printf '%s\n' "$taken" | while read -r net name; do
        [ -n "$net" ] && dim "$(pad_to "${net}.0/24" 18)${BX_ARR} $name"
    done
    say ""
    return 0
}

# show_taken_ports [EXCEPT] - the same, for forwarded ports
show_taken_ports() {
    local except="${1:-}" listing
    listing="$(
        cfg_files | while read -r f; do
            name="$(cfg_name "$f")"
            [ -n "$except" ] && [ "$name" = "$except" ] && continue
            list="$(toml_arr "$f" ports | tr -d '"' | tr ',' ' ')"
            [ -n "$list" ] && printf '%s %s\n' "$name" "$list"
        done
    )"
    [ -n "$listing" ] || return 0
    warn "ports already forwarded on this server"
    printf '%s\n' "$listing" | while read -r name list; do
        [ -n "$name" ] && dim "$(pad_to "$name" 18)${BX_ARR} $list"
    done
    say ""
    return 0
}

# ---------------------------------------------------------------------------
# health ports
#
# One per tunnel, and it has to be: each tunnel is its own process, and two
# processes cannot bind one port. It is chosen here rather than answered for,
# but a person changing one should be able to see what the others took.
# ---------------------------------------------------------------------------

health_owner() {
    local want="$1" except="${2:-}" f addr name
    case "$want" in '' | *[!0-9]*) return 0 ;; esac
    cfg_files | while read -r f; do
        addr="$(toml_get "$f" status addr)"
        [ -n "$addr" ] || continue
        name="$(cfg_name "$f")"
        [ -n "$except" ] && [ "$name" = "$except" ] && continue
        if [ "${addr##*:}" = "$want" ]; then
            printf '%s' "$name"
            break
        fi
    done
    return 0
}

show_taken_health() {
    local except="${1:-}" listing
    listing="$(
        cfg_files | while read -r f; do
            addr="$(toml_get "$f" status addr)"
            [ -n "$addr" ] || continue
            name="$(cfg_name "$f")"
            [ -n "$except" ] && [ "$name" = "$except" ] && continue
            printf '%s %s\n' "$name" "$addr"
        done
    )"
    [ -n "$listing" ] || return 0
    warn "health ports already used on this server"
    printf '%s\n' "$listing" | while read -r name addr; do
        [ -n "$name" ] && dim "$(pad_to "$name" 22)${BX_ARR} $addr"
    done
    say ""
    return 0
}

# ---------------------------------------------------------------------------
# kernel tunnels: GRE and AmneziaWG
#
# Everything up to here is carried by our own engine: a Go process holds the
# carriers open and moves the bytes. These two are not. The kernel carries
# them, and Pingify's job is to describe the link, write the unit that brings
# it up, and then answer the same questions about it that it answers about
# every other tunnel - is it up, how far away is the other end, what is wrong.
#
# Both build a private link between the two servers, so both wear the TUN
# label, and both hand their forwarding to the iptables forwarder that already
# exists for that case: DNAT onto the other server's private address, and
# masquerade back out of the tunnel interface.
#
# The instance unit is a concrete pingify@<name>.service, which systemd
# prefers over the pingify@.service template. That is deliberate: every place
# in this manager that starts, stops, watches or deletes a tunnel keeps
# working without knowing which kind it is holding.
# ---------------------------------------------------------------------------

# The kernel carries these; there is no core process and no status endpoint.
kernel_transport() {
    case "${1:-$T_TRANSPORT}" in
        gre | awg) return 0 ;;
        *)         return 1 ;;
    esac
}

# One interface name per tunnel, derived so two tunnels never collide and a
# person can still read it. Linux stops at 15 characters, and the tunnel's own
# name already carries the transport at both ends - tun-iran-gre - so strip
# what the prefix is about to say again and the result is gre-iran.
link_iface() {
    local name="$1" pfx short
    case "$T_TRANSPORT" in
        gre)  pfx="gre" ;;
        awg)  pfx="awg" ;;
        icmp) pfx="icmp" ;;
        *)    pfx="pfy" ;;
    esac
    # tun-iran-gre     -> iran        (the transport is the tail)
    # tun-iran-gre-20   -> iran-20      (it is in the middle, once the network
    #                                    has been added to tell two apart)
    short="${name#tun-}"
    short="${short%-$pfx}"
    short="${short//-$pfx-/-}"
    if [ -n "$short" ] && [ "${#short}" -le 11 ]; then
        printf '%s-%s' "$pfx" "$short"
    else
        # Nothing readable left that fits: a hash keeps them apart, which is
        # the one thing the name has to do.
        printf '%s-%s' "$pfx" "$(printf '%s' "$name" | cksum | cut -d' ' -f1)"
    fi
}

# ---------------------------------------------------------------------------
# what the kernel needs to have
# ---------------------------------------------------------------------------

gre_ready() {
    have ip || return 1
    # ip_gre is usually a module and usually not loaded until something asks.
    modprobe ip_gre >/dev/null 2>&1
    return 0
}

awg_ready() { have awg && have awg-quick; }

# The install is a best effort: an Iran server with no route to the PPA cannot
# do this, and saying so plainly beats a unit that fails at boot.
awg_install() {
    awg_ready && return 0
    say ""
    dim "installing amneziawg-tools"
    if have add-apt-repository; then
        add-apt-repository -y ppa:amnezia/ppa >/dev/null 2>&1
    fi
    if have apt-get; then
        apt-get update >/dev/null 2>&1
        DEBIAN_FRONTEND=noninteractive apt-get install -y amneziawg amneziawg-tools >/dev/null 2>&1
    fi
    awg_ready && { ok "amneziawg-tools installed"; return 0; }

    fail "amneziawg could not be installed on this server"
    dim "it needs the Amnezia PPA, which an Iran server often cannot reach."
    dim "install it from a server that can, or use TUN-GRE, which needs nothing."
    return 1
}

# ---------------------------------------------------------------------------
# AmneziaWG keys and obfuscation
# ---------------------------------------------------------------------------

# One keypair, printed as "private public". WireGuard needs a real asymmetric
# pair on each side, and each side needs the other's public half.
awg_keypair() {
    local priv pub
    priv="$(awg genkey 2>/dev/null)" || return 1
    pub="$(printf '%s' "$priv" | awg pubkey 2>/dev/null)" || return 1
    printf '%s %s' "$priv" "$pub"
}

# The obfuscation parameters, as one comma-separated field:
#
#   Jc          how many junk packets go before the handshake
#   Jmin Jmax   how big each of them is
#   S1 S2       padding added to the two handshake messages
#   H1..H4      what the four WireGuard message types are called on the wire
#
# Jc/Jmin/Jmax/S1/S2 are the values that were measured stable on this path and
# are kept. H1..H4 are not: the script this idea came from hardcodes four
# numbers, which means every tunnel built by it answers to the same four
# values - a signature, and a better one than the plain WireGuard header it
# was meant to hide. Ours are drawn per tunnel and travel in the setup token,
# so the two servers agree and no two tunnels look alike.
awg_new_obf() {
    local h1 h2 h3 h4
    h1="$(awg_rand_header)"; h2="$(awg_rand_header)"
    h3="$(awg_rand_header)"; h4="$(awg_rand_header)"
    printf '5,50,1000,68,91,%s,%s,%s,%s' "$h1" "$h2" "$h3" "$h4"
}

# A header value has to be above 4, because 1-4 are what real WireGuard uses
# and reusing one would make the tunnel answer to its own obfuscation.
awg_rand_header() {
    local n
    n="$(od -An -N4 -tu4 /dev/urandom 2>/dev/null | tr -d ' \n')"
    case "$n" in '' | *[!0-9]*) n="$(( ($$ * 2654435761) % 2147483647 ))" ;; esac
    printf '%s' "$(( (n % 2147483600) + 5 ))"
}

# ---------------------------------------------------------------------------
# what the security token buys here
#
# The kernel has never heard of our token, so it cannot key a GRE or an
# AmneziaWG tunnel the way it keys our own transports. What it can do is
# become the one secret each of them does understand, derived the same way on
# both servers from the same answer:
#
#   AmneziaWG   a pre-shared key, mixed into every handshake on top of the
#               keypair. Real: without a matching one the tunnel does not form.
#
#   GRE         the 32-bit key GRE stamps on each packet. Not protection - it
#               travels in the clear - but two tunnels built from different
#               tokens will not talk to each other by accident.
#
# Derived rather than carried, so neither ever enters the setup token.
# ---------------------------------------------------------------------------

# kernel_keys TOKEN - "presharedkey grekey", or nothing if the core cannot
# be asked. Both servers reach the same values from the same token.
kernel_keys() {
    [ -n "$1" ] || return 1
    [ -x "$CORE_BIN" ] || return 1
    "$CORE_BIN" -derivekey "$1" 2>/dev/null
}

awg_psk_for() { kernel_keys "$1" | awk '{print $1}'; }
gre_key_for() { kernel_keys "$1" | awk '{print $2}'; }

# obf_field N FIELDS - pull one value out of that comma-separated list
obf_field() { printf '%s' "$2" | cut -d, -f"$1"; }

awg_write_conf() {
    local name="$1" iface="$2" conf="$3"
    local obf="$T_AWG_OBF"
    mkdir -p "$(dirname "$conf")"
    {
        printf '# Pingify %s - written by the manager\n' "$name"
        printf '[Interface]\n'
        printf 'PrivateKey = %s\n' "$T_AWG_PRIV"
        printf 'Address = %s\n' "$T_TUNLOCAL"
        printf 'ListenPort = %s\n' "$T_AWG_PORT"
        printf 'MTU = %s\n' "$T_TUNMTU"
        printf 'Jc = %s\n'   "$(obf_field 1 "$obf")"
        printf 'Jmin = %s\n' "$(obf_field 2 "$obf")"
        printf 'Jmax = %s\n' "$(obf_field 3 "$obf")"
        printf 'S1 = %s\n'   "$(obf_field 4 "$obf")"
        printf 'S2 = %s\n'   "$(obf_field 5 "$obf")"
        printf 'H1 = %s\n'   "$(obf_field 6 "$obf")"
        printf 'H2 = %s\n'   "$(obf_field 7 "$obf")"
        printf 'H3 = %s\n'   "$(obf_field 8 "$obf")"
        printf 'H4 = %s\n'   "$(obf_field 9 "$obf")"
        printf '\n[Peer]\n'
        printf 'PublicKey = %s\n' "$T_AWG_PUB"
        # Only the end that dials needs an endpoint. The other one learns the
        # address from the first handshake that arrives, which is what lets
        # the listening side sit behind whatever the path does to it.
        if ! this_side_accepts && [ -n "$T_PEER_IP" ]; then
            printf 'Endpoint = %s:%s\n' "$T_PEER_IP" "$T_AWG_PORT"
        fi
        printf 'AllowedIPs = %s/32\n' "${T_TUNPEER%%/*}"
        # The security token, as the one secret WireGuard understands.
        # Without a matching one the handshake never completes, so the
        # answer to that question is doing real work here.
        local psk; psk="$(awg_psk_for "$T_TOKEN")"
        [ -n "$psk" ] && printf 'PresharedKey = %s\n' "$psk"
        printf 'PersistentKeepalive = 25\n'
    } > "$conf"
    chmod 600 "$conf"
}

awg_conf_path() { printf '%s/%s.conf' "$AWG_DIR" "$1"; }

# ---------------------------------------------------------------------------
# the units
#
# A concrete instance unit, so systemd uses it in place of the template and
# the rest of the manager never has to know the difference.
# ---------------------------------------------------------------------------

write_link_unit() {
    local name="$1" iface unit
    iface="$(link_iface "$name")"
    unit="$UNIT_DIR/pingify@$name.service"

    case "$T_TRANSPORT" in
        gre) write_gre_unit "$name" "$iface" "$unit" ;;
        awg) write_awg_unit "$name" "$iface" "$unit" ;;
        *)   return 1 ;;
    esac
    systemctl daemon-reload
}

write_gre_unit() {
    local name="$1" iface="$2" unit="$3" gkey keyarg=""
    # GRE's own key: two tunnels built from different tokens then refuse to
    # talk to each other. It rides in the clear, so it is not protection -
    # but it is the only thing GRE has, and it makes the token mean something.
    gkey="$(gre_key_for "$T_TOKEN")"
    case "$gkey" in '' | *[!0-9]*) : ;; *) keyarg=" key $gkey" ;; esac
    # One shot, held open: the interface is the state, so systemd has nothing
    # to supervise once it exists. ExecStart deletes any leftover first, which
    # is what makes a restart work rather than fail on "file exists".
    cat > "$unit" <<UNIT
[Unit]
Description=Pingify tunnel $name (GRE)
Documentation=https://github.com/GreatTeejay/Pingify
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/bin/sh -c '\\
  ip link del $iface 2>/dev/null; \\
  ip tunnel add $iface mode gre local $T_PUBLIC_IP remote $T_PEER_IP ttl $T_GRE_TTL$keyarg; \\
  ip link set $iface mtu $T_TUNMTU; \\
  ip addr add $T_TUNLOCAL dev $iface; \\
  ip link set $iface up; \\
  sysctl -w net.ipv4.conf.$iface.rp_filter=0 >/dev/null 2>&1 || true'
ExecStop=/bin/sh -c 'ip link del $iface 2>/dev/null || true'
SyslogIdentifier=pingify-$name

[Install]
WantedBy=multi-user.target
UNIT
}

write_awg_unit() {
    local name="$1" iface="$2" unit="$3" conf
    conf="$(awg_conf_path "$iface")"
    cat > "$unit" <<UNIT
[Unit]
Description=Pingify tunnel $name (AmneziaWG)
Documentation=https://github.com/GreatTeejay/Pingify
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
RemainAfterExit=yes
Environment=WG_QUICK_USERSPACE_IMPLEMENTATION=amneziawg-go
ExecStart=/usr/bin/env awg-quick up $conf
ExecStop=/usr/bin/env awg-quick down $conf
SyslogIdentifier=pingify-$name

[Install]
WantedBy=multi-user.target
UNIT
}

# ---------------------------------------------------------------------------
# what the manager asks about any tunnel
# ---------------------------------------------------------------------------

# link_up NAME - the interface exists and is up
link_up() {
    local iface; iface="$(link_iface "$1")"
    ip link show "$iface" 2>/dev/null | grep -q 'state \(UP\|UNKNOWN\)'
}

# link_rtt NAME - milliseconds to the other end of the private link, or "-".
# One packet, one second: this is called from a list that redraws often.
link_rtt() {
    local peer="${T_TUNPEER%%/*}" out
    [ -n "$peer" ] || { printf '%s' '-'; return 1; }
    out="$(ping -c1 -W1 -n "$peer" 2>/dev/null | sed -n 's/.*time=\([0-9.]*\).*/\1/p')"
    [ -n "$out" ] || { printf '%s' '-'; return 1; }
    printf '%s' "$out"
}

# awg_handshake_age IFACE - seconds since the last completed handshake, or
# nothing when it cannot be asked. AmneziaWG knows for itself whether the far
# end is there, without a packet being sent - and unlike a ping, it still
# knows on a server that has been told to stop answering them.
awg_handshake_age() {
    local iface="$1" last now
    have awg || return 1
    last="$(awg show "$iface" latest-handshakes 2>/dev/null | awk '{print $2; exit}')"
    case "$last" in '' | 0 | *[!0-9]*) return 1 ;; esac
    now="$(date +%s 2>/dev/null)"
    case "$now" in '' | *[!0-9]*) return 1 ;; esac
    printf '%s' "$((now - last))"
}

# A WireGuard peer keeps talking every 25 seconds, so anything older than a
# few minutes of silence is a link that has stopped.
AWG_STALE_AFTER=180

# The same five-field line the core prints for -brief, so the tunnel list and
# the health check can read one shape for every kind of tunnel:
#   state up total rtt streams uptime
kernel_brief() {
    local name="$1" rtt age
    if ! link_up "$name"; then
        printf 'down 0 1 0.0 0 0'
        return
    fi

    # AmneziaWG is asked directly. This is both faster than a ping and more
    # honest: a peer that has been told to stop answering pings - which is
    # exactly what an ICMP tunnel on the same server turns on - is still a
    # peer that is handshaking.
    if [ "$T_TRANSPORT" = "awg" ] && age="$(awg_handshake_age "$T_TUNIF")"; then
        if [ "$age" -gt "$AWG_STALE_AFTER" ]; then
            printf 'down 0 1 0.0 0 0'
            return
        fi
        rtt="$(link_rtt "$name")"
        [ "$rtt" = "-" ] && rtt="0.0"
        printf 'up 1 1 %s 0 0' "$rtt"
        return
    fi

    rtt="$(link_rtt "$name")"
    if [ "$rtt" = "-" ]; then
        # The interface is up but nothing answers on it, which for a kernel
        # tunnel is the same news as a carrier that will not connect.
        printf 'down 0 1 0.0 0 0'
        return
    fi
    printf 'up 1 1 %s 0 0' "$rtt"
}

# status_peer NAME - the other server's address, as the running tunnel sees it.
#
# The accepting end is told nothing about the far side: it does not dial, so
# there is no connect line in its config and no address to read. But something
# arrived, and the core knows what - so this is the only place on that machine
# where the other server's address exists at all.
#
# Written with cut rather than a sed backreference on purpose: this file is
# assembled into one script by a build that has eaten a backslash before.
status_peer() {
    local name="$1" f addr doc
    f="$(cfg_file "$name")" || return 1
    addr="$(toml_get "$f" status addr)"
    [ -n "$addr" ] && [ -x "$CORE_BIN" ] || return 1
    doc="$("$CORE_BIN" -status "$addr" 2>/dev/null)" || return 1
    # one field out of the JSON, and only when it is an address - the core
    # falls back to "listen <our own>" when nothing has connected, which is
    # this machine's address and no use to anyone asking
    printf '%s' "$doc" | tr ',' '\n' | grep '"peer"' | cut -d'"' -f4 \
        | grep -E '^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$' | head -1
}

# tunnel_is_up NAME - one answer for every kind of tunnel, so the list and the
# status panel cannot disagree. The panel used to ask the core's status
# endpoint, which a kernel tunnel does not have, so GRE and AmneziaWG could
# never be counted and "3 of 4 up" read as 2.
tunnel_is_up() {
    local name="$1" f addr brief
    f="$(cfg_file "$name")"
    [ -f "$f" ] || return 1
    [ "$(svc_state "$name")" = "active" ] || return 1
    if kernel_transport "$(toml_get "$f" transport type)"; then
        brief="$(cfg_load "$name" >/dev/null 2>&1 && kernel_brief "$name")"
        case "$brief" in up\ *) return 0 ;; *) return 1 ;; esac
    fi
    addr="$(toml_get "$f" status addr)"
    [ -n "$addr" ] && [ -x "$CORE_BIN" ] || return 1
    "$CORE_BIN" -healthz "$addr" >/dev/null 2>&1
}

# ---------------------------------------------------------------------------
# health
#
# The questions are different from an engine tunnel's. There is no handshake
# to fail and no carrier to count: either the kernel built the interface or it
# did not, and either the other end answers on it or it does not.
# ---------------------------------------------------------------------------

# Can this kernel still do what the config asks for at all?
kernel_ready_check() {
    case "$T_TRANSPORT" in
        gre)
            if gre_ready; then
                hc_ok "the kernel has GRE"
            else
                hc_bad "this kernel cannot do GRE"
                hc_note "the ip_gre module is missing, which some VPS kernels ship without"
                hc_fix "modprobe ip_gre     (and ask the provider if it fails)"
            fi ;;
        awg)
            if awg_ready; then
                hc_ok "amneziawg is installed"
            else
                hc_bad "amneziawg is not installed here"
                hc_note "the tunnel cannot come up without awg and awg-quick"
                hc_fix "add-apt-repository -y ppa:amnezia/ppa && apt install -y amneziawg amneziawg-tools"
            fi ;;
    esac
}

# The link is not carrying: say which half of it is missing.
kernel_link_check() {
    local name="$1" iface="$T_TUNIF" peer="${T_TUNPEER%%/*}"

    if ! ip link show "$iface" >/dev/null 2>&1; then
        hc_bad "the interface $iface does not exist"
        hc_note "the unit ran but the kernel did not build the link"
        hc_fix "journalctl -u pingify@$name -n 20 --no-pager -o cat"
        return
    fi
    if ! link_up "$name"; then
        hc_bad "$iface exists but is down"
        hc_fix "systemctl restart pingify@$name"
        return
    fi

    # Up, addressed, and silent. For GRE that is almost always the other end
    # not built yet or the path dropping protocol 47; for AmneziaWG it is a
    # handshake that never completed, which has its own reasons.
    hc_bad "$iface is up but ${peer:-the other end} does not answer"
    # The false alarm this used to raise, and it was easy to walk into:
    # building an ICMP tunnel turns the ping block on, and a server answering
    # no pings answers none on its private links either - so a GRE tunnel
    # carrying traffic perfectly well read as down.
    #
    # The block exempts tunnel interfaces now, so this only survives where
    # there is no firewall to be selective with. The far server is the one
    # that has to answer, and it may be older than this fix.
    if [ "$T_TRANSPORT" = "gre" ] && [ "$(block_state icmp)" = "on" ] && ! have iptables; then
        hc_note "this server has no iptables, so its ping block is the blunt"
        hc_note "kind - and a GRE link is tested by pinging across it"
        hc_fix "test it by hand instead:  curl --interface $iface -sI http://$peer"
    fi
    if [ "$T_TRANSPORT" = "gre" ]; then
        hc_note "GRE is IP protocol 47, not a port - a firewall that only"
        hc_note "knows about ports will drop it without saying so"
        hc_fix "on the other server:  ip a show $iface     (it must exist there too)"
        hc_note "and check both public addresses match what each side was told"
    else
        hc_note "no handshake has completed with the other server"
        hc_fix "awg show $iface     (look for a recent handshake)"
        hc_note "the two ends must agree on the token, the port, and the"
        hc_note "obfuscation values - all of which travel in the setup token"
        hc_fix "check ${T_AWG_PORT}/udp is open here and on the other server"
    fi
}

# ---------------------------------------------------------------------------
# reaching the far end
#
# The core's probe belongs to the core, and a kernel tunnel has none. What can
# be done instead is the same thing the DNAT rule does for real traffic: open
# the forwarded port on the other server's private address and see whether
# anything is there. If that works, every part of the path works - the link,
# the routing, and the service at the end of it.
# ---------------------------------------------------------------------------

# tcp_reaches HOST PORT - true when something accepts there within a moment
tcp_reaches() {
    local host="$1" port="$2"
    timeout 5 bash -c "exec 3<>/dev/tcp/$host/$port" 2>/dev/null
}

kernel_probe() {
    local name="$1" peer="${T_TUNPEER%%/*}" spec p lport rport proto bad=0 any=0
    [ -n "$peer" ] || return 0
    [ -n "$T_FORWARDS" ] || return 0

    for spec in $(printf '%s' "$T_FORWARDS" | tr -d '"' | tr ',' ' '); do
        proto=tcp
        case "$spec" in
            udp:*) proto=udp; spec="${spec#udp:}" ;;
            tcp:*) spec="${spec#tcp:}" ;;
        esac
        lport="${spec%%=*}"
        rport="${spec#*=}"
        [ "$rport" = "$spec" ] && rport="$lport"
        # a range is described by its first port; testing all of them would
        # take longer than anybody will wait
        lport="${lport%%-*}"; rport="${rport%%-*}"
        case "$rport" in '' | *[!0-9]*) continue ;; esac
        if [ "$proto" = "udp" ]; then
            hc_note "udp :$lport cannot be tested this way"
            continue
        fi
        any=1
        if tcp_reaches "$peer" "$rport"; then
            hc_ok ":$lport reaches $peer:$rport across the link"
        else
            hc_bad ":$lport does not reach $peer:$rport"
            hc_note "the link is up, so this is the far end rather than the path"
            hc_fix "on the KHAREJ server:  ss -ltnp | grep :$rport"
            hc_note "and it must listen on 0.0.0.0, not on 127.0.0.1 alone -"
            hc_note "the traffic arrives there addressed to $peer"
            bad=1
        fi
    done
    [ "$any" = "0" ] && return 0
    return "$bad"
}

# ---------------------------------------------------------------------------
# reading an existing tunnel back
# ---------------------------------------------------------------------------

cfg_load() {
    local f
    f="$(cfg_file "$1")"
    [ -f "$f" ] || return 1
    cfg_reset
    T_NAME="$(toml_get "$f" tunnel name)"
    T_ROLE="$(toml_get "$f" tunnel role)"
    T_MODE="$(toml_get "$f" tunnel mode)";                  : "${T_MODE:=forward}"
    T_KIND="$(toml_get "$f" tunnel kind)"
    if [ -z "$T_KIND" ]; then
        # written before the kind was recorded
        [ "$(toml_get "$f" transport type)" = "icmp" ] && T_KIND="tun" || T_KIND="tcp"
    fi
    T_TRANSPORT="$(toml_get "$f" transport type)";          : "${T_TRANSPORT:=tcp}"
    T_TOKEN="$(toml_get "$f" security token)"
    T_STATUS="$(toml_get "$f" status addr)"
    T_CARRIERS="$(toml_get "$f" transport carriers)";       : "${T_CARRIERS:=4}"
    T_KEEPALIVE="$(toml_get "$f" transport keepalive_sec)"; : "${T_KEEPALIVE:=10}"
    T_OBFUSCATE="$(toml_get "$f" transport obfuscate)";     : "${T_OBFUSCATE:=false}"
    T_WINDOW="$(toml_get "$f" tuning window_kb)";           : "${T_WINDOW:=512}"
    T_SNDBUF="$(toml_get "$f" tuning sndbuf_kb)";           : "${T_SNDBUF:=$T_WINDOW}"
    T_RCVBUF="$(toml_get "$f" tuning rcvbuf_kb)";           : "${T_RCVBUF:=$T_WINDOW}"
    T_PRESET="$(toml_get "$f" tuning profile)";             : "${T_PRESET:=custom}"
    T_FORWARDS="$(toml_arr "$f" ports)"
    T_FORWARDER="$(toml_get "$f" forward forwarder)";       : "${T_FORWARDER:=pingify}"
    # pfy0 is what tunnels built before the device was named after them
    # actually have on the wire, so it stays as the fallback for those.
    T_TUNIF="$(toml_get "$f" tun name)";                    : "${T_TUNIF:=pfy0}"
    T_TUNLOCAL="$(toml_get "$f" tun local_addr)"
    T_TUNPEER="$(toml_get "$f" tun remote_addr)"
    T_TUNMTU="$(toml_get "$f" tun mtu)";                    : "${T_TUNMTU:=1380}"

    # A kernel tunnel keeps its own section, and both public addresses in it:
    # nothing about it is derived from a listen or connect line.
    if kernel_transport; then
        T_GRE_TTL="$(toml_get "$f" gre ttl)";               : "${T_GRE_TTL:=255}"
        T_AWG_PORT="$(toml_get "$f" awg listen_port)";      : "${T_AWG_PORT:=51820}"
        T_AWG_PRIV="$(toml_get "$f" awg private_key)"
        T_AWG_PUB="$(toml_get "$f" awg peer_key)"
        T_AWG_OBF="$(toml_get "$f" awg obfuscation)"
        if [ "$T_TRANSPORT" = "gre" ]; then
            T_PUBLIC_IP="$(toml_get "$f" gre local_public)"
            T_PEER_IP="$(toml_get "$f" gre peer_public)"
        else
            T_PUBLIC_IP="$(toml_get "$f" awg local_public)"
            T_PEER_IP="$(toml_get "$f" awg peer_public)"
        fi
        # Reverse, like every other Pingify tunnel: IRAN is the end that
        # waits. T_ACCEPTS names the role that waits, not this machine, so it
        # reads the same on both servers.
        T_ACCEPTS="server"
        return 0
    fi

    # The endpoint is derived, so recover what it was built from.
    local l c
    l="$(toml_get "$f" transport listen)"
    c="$(toml_get "$f" transport connect)"
    if [ -n "$l" ]; then
        T_ACCEPTS="$T_ROLE"
        case "$l" in *:*) T_PORT="${l##*:}" ;; esac
    else
        [ "$T_ROLE" = "server" ] && T_ACCEPTS="client" || T_ACCEPTS="server"
        T_PEER_IP="${c%:*}"
        case "$c" in *:*) T_PORT="${c##*:}" ;; *) T_PEER_IP="$c" ;; esac
    fi
    return 0
}

# ---------------------------------------------------------------------------
# status rendering
# ---------------------------------------------------------------------------

tunnel_status_block() {
    local name="$1" f="$(cfg_file "$1")"
    [ -f "$f" ] || { fail "no such tunnel: $name"; return 1; }
    local addr; addr="$(toml_get "$f" status addr)"
    local state; state="$(svc_state "$name")"

    local colour="$C_RED"
    [ "$state" = "active" ] && colour="$C_GRN"
    printf '  %s%s%s  service %s%s%s   token %s%s%s\n' \
        "$C_B" "$name" "$C_OFF" "$colour" "$state" "$C_OFF" \
        "$C_YEL" "$(token_print "$(toml_get "$f" security token)")" "$C_OFF"

    # A stopped tunnel has no status endpoint to ask, and printing the raw
    # "connection refused" from trying anyway reads like a fault when it is
    # only the consequence of the line above.
    if [ "$state" != "active" ]; then
        dim "not running - nothing to report"
        return 0
    fi
    [ -n "$addr" ] && [ -x "$CORE_BIN" ] || return 0
    if ! "$CORE_BIN" -status "$addr" 2>/dev/null; then
        # Either it is still coming up, or no carrier has arrived. The status
        # server answers within a second of starting, so a refusal this soon
        # after a start is the former.
        dim "starting up, or the other server has not connected yet"
    fi
    return 0
}

# One line per tunnel, for the overview table. The second argument is how wide
# the name column is; list_tunnels works it out from the names it is about to
# print, so one long name cannot push its own row out of line with the rest.
tunnel_row() {
    local name="$1" nw="${2:-13}" f="$(cfg_file "$1")"
    local role proto fwder addr state brief up total rtt links kern=0
    role="$(side_label "$(toml_get "$f" tunnel role)")"
    proto="$(transport_label "$(toml_get "$f" transport type)")"
    fwder="$(forwarder_label "$(toml_get "$f" forward forwarder)")"
    addr="$(toml_get "$f" status addr)"
    state="$(svc_state "$name")"

    up="-"; total="$(toml_get "$f" transport carriers)"; rtt="-"
    if [ "$state" = "active" ]; then
        if kernel_transport "$(toml_get "$f" transport type)"; then
            kern=1
            # No core and no status endpoint: the kernel holds the link, and
            # the answer comes from the interface plus one ping across it.
            # In a subshell, because cfg_load writes every T_ variable and
            # this runs once per tunnel inside somebody else's loop.
            total=1
            brief="$(cfg_load "$name" >/dev/null 2>&1 && kernel_brief "$name")"
        elif [ -n "$addr" ] && [ -x "$CORE_BIN" ]; then
            brief="$("$CORE_BIN" -status "$addr" -brief 2>/dev/null)"
        fi
    fi
    if [ -n "$brief" ]; then
        # state up total rtt streams uptime - one shape for every kind
        set -- $brief
        up="$2"
        # An unreachable endpoint reports zeroes; keep the configured carrier
        # count so the column still says what was asked for.
        [ "$3" != "0" ] && total="$3"
        if [ "$1" = "up" ]; then rtt="${4}ms"; else rtt="-"; fi
    fi

    # GRE and AmneziaWG have exactly one link, because they are not built out
    # of connections the way our own transports are - there is no second one
    # to open. Printing "1/1" beside a "24/24" invited the reading that they
    # were running at a twenty-fourth of it, so they say up or down and leave
    # counting to the transports that have something to count.
    if [ "$kern" = "1" ]; then
        case "$up" in
            0) links="down" ;;
            -) links="-" ;;
            *) links="up" ;;
        esac
    else
        links="$up/$total"
    fi

    # Green only when the tunnel is running *and* a carrier is actually up:
    # a running process with no peer is the failure people most need to see.
    local dot="$C_GRY$BX_OFF$C_OFF"
    case "$state" in
        active)
            if [ "$up" != "0" ] && [ "$up" != "-" ]; then dot="$C_GRN$BX_ON$C_OFF"
            else dot="$C_YEL$BX_ON$C_OFF"; fi ;;
        stopped)  dot="$C_YEL$BX_OFF$C_OFF" ;;
        disabled) dot="$C_GRY$BX_OFF$C_OFF" ;;
    esac

    printf '  %s %s %s %s %s %s %s%s%s\n' \
        "$dot" \
        "$(pad_to "${C_B}${name}${C_OFF}" "$nw")" \
        "$(pad_to "$role" 8)" \
        "$(pad_to "$proto" 10)" \
        "$(pad_to "$fwder" 9)" \
        "$(pad_to "$links" 6)" \
        "$(rtt_colour "$rtt")" "$rtt" "$C_OFF"
}

list_tunnels() {
    local names; names="$(tunnel_names)"
    if [ -z "$names" ]; then
        dim "no tunnels configured yet - pick New tunnel to make one"
        return 1
    fi
    # As wide as the widest name, never narrower than the header. It was a
    # fixed 13, and the moment a name grew past that - which it did as soon
    # as the private network went into it - that row alone slid right and
    # every column after it stopped lining up.
    local w=13 n
    for n in $names; do
        [ "${#n}" -gt "$w" ] && w="${#n}"
    done

    printf '    %s%s %s %s %s %s %s%s\n' \
        "$C_DIM" \
        "$(pad_to "NAME" "$w")" \
        "$(pad_to "SIDE" 8)" \
        "$(pad_to "PROTO" 10)" \
        "$(pad_to "FORWARDER" 9)" \
        "$(pad_to "LINKS" 6)" \
        "RTT" "$C_OFF"
    for n in $names; do tunnel_row "$n" "$w"; done
    return 0
}

# ---------------------------------------------------------------------------
# manage tunnels
# ---------------------------------------------------------------------------

pick_tunnel() {
    local names; names="$(tunnel_names)"
    [ -n "$names" ] || { dim "no tunnels configured yet"; return 1; }
    local i=0 n
    say ""
    for n in $names; do
        i=$((i + 1))
        item "$i" "$n" "$(svc_state "$n")"
    done
    item 0 "Back"
    say ""
    local sel=""
    # No default. It used to offer 1, so the key people press to leave a menu
    # picked the first tunnel in it instead.
    ask sel "select"
    [ "$sel" = "0" ] && return 1
    case "$sel" in ''|*[!0-9]*) return 1 ;; esac
    PICKED="$(printf '%s\n' $names | sed -n "${sel}p")"
    [ -n "$PICKED" ]
}

manage_tunnels() {
    while :; do
        banner
        head2 "Manage Tunnels"
        list_tunnels || { pause; return; }
        if ! pick_tunnel; then return; fi
        tunnel_menu "$PICKED"
    done
}

tunnel_menu() {
    local name="$1"
    while :; do
        banner
        head2 "Tunnel: $name"
        tunnel_status_block "$name"
        rule
        group "Service"
        item 1 "Restart"
        item 2 "Stop"
        item 3 "Start"
        item 4 "Delete this tunnel"
        group "Check"
        item 5 "Health check" "what is wrong, and what to do about it"
        item 6 "Live log"
        group "Settings"
        item 7 "Ports" "$(printf '%s' "$(toml_arr "$(cfg_file "$name")" ports)" | tr -d '"' | tr ',' ' ')"
        item 8 "Tuning" "carriers, window, keepalive, shaping"
        item 9 "Scheduled restart"
        say ""
        item 0 "Back"
        say ""
        local c=""
        ask c "select"
        case "$c" in
            1) systemctl restart "pingify@$name"; ok "restarted"; sleep 1 ;;
            2) systemctl stop "pingify@$name"; ok "stopped"; sleep 1 ;;
            3) systemctl start "pingify@$name"; ok "started"; sleep 1 ;;
            4) delete_tunnel "$name" && return ;;
            5) health_check "$name" ;;
            6) live_log "$name" ;;
            7) edit_forwards "$name" ;;
            8) tuning_menu "$name" ;;
            9) recycle_menu "$name" ;;
            0|"") return ;;
        esac
    done
}

# journald puts its own timestamp, the hostname and unit[pid] in front of
# every line. Our line already carries a timestamp, so all that prefix bought
# was half the terminal width - on a 24-carrier tunnel it pushed the actual
# message off the right edge. -o cat prints only what the core wrote.
live_log() {
    local name="$1"
    banner
    head2 "Live log: $name"
    say ""
    dim "ctrl-c to stop following"
    say ""
    # ctrl-c goes to every process in the foreground group, and a script with
    # no handler for it dies. So the key that stops following also closed the
    # manager and dropped you back to a shell - the same "I had to start it
    # again" as the dashboard that would not take enter. Catch it here, let
    # journalctl take the signal and go, and come back to the menu.
    trap ':' INT
    journalctl -u "pingify@$name" -n 60 -f --no-pager -o cat || true
    trap - INT
}

edit_logging() {
    local name="$1" f
    f="$(cfg_file "$name")"
    banner
    head2 "Logging: $name"
    say ""
    choice 1 "error" "only what is broken"
    choice 2 "warn" "and what is wrong but survivable"
    choice 3 "info" "and what a healthy tunnel does"
    choice 4 "debug" "and why each carrier and stream did what it did"
    choice 5 "trace" "and every packet - slows a busy tunnel down"
    say ""
    dim "This is local. The two servers may log at different levels."
    say ""
    local c="" lvl
    ask c "select" "3"
    case "$c" in
        1) lvl="error" ;; 2) lvl="warn" ;;
        4) lvl="debug" ;; 5) lvl="trace" ;;
        3|"") lvl="info" ;;
        *) fail "pick 1 to 5"; pause; return ;;
    esac
    cp -f "$f" "$f.bak"
    if grep -q '^level' "$f"; then
        sed -i "s#^level.*#level            = \"$lvl\"#" "$f"
    else
        printf '
[logging]
level            = "%s"
' "$lvl" >> "$f"
    fi
    if "$CORE_BIN" -c "$f" -check >/dev/null 2>&1; then
        rm -f "$f.bak"
        systemctl restart "pingify@$name"
        ok "logging at $lvl"
    else
        mv -f "$f.bak" "$f"
        fail "the core rejected that; nothing was changed"
    fi
    pause
}

# The health port is where -status and the watchdog ask how a tunnel is doing.
# It is picked automatically and bound to loopback, so it is not reachable from
# anywhere and cannot collide with another tunnel - but a fixed one is easier
# to point a monitor at, so it can be set.
edit_health() {
    local name="$1" f
    f="$(cfg_file "$name")"
    cfg_load "$name" || return 1
    banner
    head2 "Health port: $name"
    say ""
    dim "Bound to 127.0.0.1, so nothing outside this server can reach it."
    dim "Used by -status and by the watchdog. Local to this server: the two"
    dim "ends do not have to match."
    say ""
    dim "One per tunnel, always: each tunnel is its own process, and two"
    dim "processes cannot bind one port."
    say ""
    show_taken_health "$name"
    local p="" owner=""
    while :; do
        ask p "port" "${T_STATUS##*:}"
        case "$p" in '' | *[!0-9]*) fail "numbers only"; continue ;; esac
        [ "$p" -ge 1 ] && [ "$p" -le 65535 ] || { fail "1 to 65535"; continue; }
        owner="$(health_owner "$p" "$name")"
        if [ -n "$owner" ]; then
            fail "port $p is already $owner's health port"
            continue
        fi
        break
    done

    cp -f "$f" "$f.bak"
    sed -i "s#^addr .*#addr             = \"127.0.0.1:$p\"#" "$f"
    if "$CORE_BIN" -c "$f" -check >/dev/null 2>&1; then
        rm -f "$f.bak"
        systemctl restart "pingify@$name"
        ok "health port is now $p"
    else
        mv -f "$f.bak" "$f"
        fail "the core rejected that; nothing was changed"
    fi
    pause
}

shaping_label() {
    case "$(toml_get "$(cfg_file "$1")" transport obfuscate)" in
        true) printf 'on' ;;
        *)    printf 'off' ;;
    esac
}

# Not a performance knob: it decides what the tunnel looks like from outside,
# and the two servers have to agree or nothing passes.
edit_shaping() {
    local name="$1" f="$(cfg_file "$1")" now
    now="$(shaping_label "$name")"
    banner
    head2 "Traffic shaping - currently ${C_YEL}${now}${C_OFF}"
    say ""
    dim "ON   the frame length is masked and the opening frames carry random"
    dim "     filler, so nothing on the wire sits at a fixed offset. The cost is"
    dim "     that the stream then looks like nothing at all, and a filter that"
    dim "     drops what it cannot identify will drop exactly that."
    say ""
    dim "OFF  each frame carries a plain length in front, so the tunnel looks"
    dim "     like an ordinary length-prefixed protocol."
    say ""
    ok "the payload is AES-256-GCM either way - this changes the shape, not the secrecy"
    say ""
    warn "set it the SAME on both servers. If they differ, no traffic passes at all."
    say ""
    local want=""
    ask want "shaping on? (yes/no)" "$([ "$now" = "on" ] && echo yes || echo no)"
    case "$want" in
        y|yes|true|on|1)  want="true" ;;
        n|no|false|off|0) want="false" ;;
        *) fail "answer yes or no"; pause; return ;;
    esac

    cp -f "$f" "$f.bak"
    # Append rather than substitute: a replacement carrying a newline has to
    # be escaped, and that escape does not survive every layer it passes
    # through on the way into this file.
    sed -i -e '/^obfuscate/d' \
           -e "/^keepalive_sec/a obfuscate        = $want" "$f"
    if "$CORE_BIN" -c "$f" -check >/dev/null 2>&1; then
        rm -f "$f.bak"
        systemctl restart "pingify@$name"
        ok "shaping is $([ "$want" = "true" ] && echo on || echo off) - now do the same on the other server"
    else
        mv -f "$f.bak" "$f"
        fail "the core rejected that; nothing was changed"
    fi
    pause
}

edit_forwards() {
    local name="$1" f="$(cfg_file "$1")"
    cfg_load "$name" || return 1
    if [ "$T_ROLE" != "server" ]; then
        warn "the port list lives on the IRAN server; this is the KHAREJ end"
        pause; return
    fi
    say ""
    dim "current: $(printf '%s' "$T_FORWARDS" | tr -d '"')"
    say ""
    # Everything except this tunnel's own list, which it is allowed to keep.
    show_taken_ports "$name"
    local raw="" fwd="" clash=""
    while :; do
        ask raw "new port list (comma separated)"
        [ -n "$raw" ] || return
        fwd="$(parse_forwards "$raw")"
        [ -n "$fwd" ] || { fail "nothing to set"; return; }
        clash="$(forwards_clash "$raw" "$name")" && break
        printf '%s
' "$clash" | while read -r line; do
            [ -n "$line" ] && fail "$line"
        done
        dim "pick another port, or free that one first"
        say ""
    done

    cp -f "$f" "$f.bak"
    if grep -q '^ports' "$f"; then
        sed -i "s#^ports.*#ports            = [$fwd]#" "$f"
    else
        sed -i "s#^\(forwarder.*\)#\1\nports            = [$fwd]#" "$f"
    fi
    if "$CORE_BIN" -c "$f" -check >/dev/null 2>&1; then
        rm -f "$f.bak"
        systemctl restart "pingify@$name"
        apply_nat quiet
        ok "ports updated and the tunnel restarted"
    else
        mv -f "$f.bak" "$f"
        fail "that port list was rejected, nothing changed"
    fi
    pause
}

# Every number that shapes a tunnel, on one screen, split by the only
# distinction that matters when two servers disagree: the settings that have to
# match, and the ones that are nobody's business but this machine's.
# ---------------------------------------------------------------------------
# what the numbers actually buy
#
# A window in kilobytes and a carrier count mean nothing on their own. What a
# person wants to know is how fast one connection can go, and that has one
# answer: a stream may have at most one window of data in flight, so it cannot
# beat window / round-trip no matter what the path underneath can do.
#
#   1024 KB at 90 ms  ->  93 Mbit/s for a single connection
#   4096 KB at 90 ms  -> 372 Mbit/s
#
# Which is the whole reason the bigger presets exist, and the reason raising
# carriers does nothing for a single download.
# ---------------------------------------------------------------------------

# stream_ceiling WINDOW_KB RTT_MS -> megabits per second, or "-"
stream_ceiling() {
    local win="$1" rtt="${2%%.*}"
    # Checked apart, not joined: an empty window beside a good round trip
    # reads as a perfectly good number when the two are concatenated.
    case "$win" in '' | *[!0-9]*) printf '%s' '-'; return 1 ;; esac
    case "$rtt" in '' | *[!0-9]*) printf '%s' '-'; return 1 ;; esac
    [ "$rtt" -gt 0 ] || { printf '%s' '-'; return 1; }
    # KB * 8 bits / ms  ==  kbit/ms  ==  Mbit/s, near enough for a menu
    printf '%s' "$(( win * 8 / rtt ))"
}

# The round trip this tunnel is actually seeing, so the ceiling above is about
# this path rather than a number out of a book. Falls back to a typical
# Iran-to-Europe figure when the tunnel is not up to be asked.
tuning_rtt() {
    local name="$1" brief=""
    if [ -n "$T_STATUS" ] && [ -x "$CORE_BIN" ] && [ "$(svc_state "$name")" = "active" ]; then
        brief="$("$CORE_BIN" -status "$T_STATUS" -brief 2>/dev/null)"
    fi
    if [ -n "$brief" ]; then
        set -- $brief
        if [ "$1" = "up" ] && [ "${4%%.*}" -gt 0 ] 2>/dev/null; then
            printf '%s' "${4%%.*}"
            return 0
        fi
    fi
    printf '90'
    return 1
}

tuning_menu() {
    local name="$1" f v
    f="$(cfg_file "$name")"
    while :; do
        cfg_load "$name" || return 1
        banner
        head2 "Tuning: $name"

        local rtt measured ceiling
        rtt="$(tuning_rtt "$name")" && measured="measured" || measured="assumed"
        ceiling="$(stream_ceiling "$T_WINDOW" "$rtt")"

        panel "both servers must agree"
        field "Token" "$(token_print "$T_TOKEN")" "Shaping" "$(shaping_label "$name")"
        field "Type" "$(transport_label "$T_TRANSPORT")" "Forwarder" "$(forwarder_label "$T_FORWARDER")"
        panel_end
        say ""
        panel "local to this server"
        field "Profile" "$T_PRESET"
        field "Carriers" "$T_CARRIERS" "Window" "${T_WINDOW} KB"
        field "Buffers" "${T_SNDBUF} / ${T_RCVBUF} KB" "Keepalive" "${T_KEEPALIVE} s"
        field "Health port" "$T_STATUS"
        panel_end
        say ""

        # The one number worth reading off this screen.
        panel "what that buys"
        field "One link" "up to ${ceiling} Mbit/s" "Round trip" "${rtt} ms, ${measured}"
        # More carriers spread more connections; they do nothing for one.
        field "Spread over" "$T_CARRIERS carriers at once"
        panel_end

        # A socket that cannot hold a window's worth of data makes the window
        # a number on paper: the kernel stops the writer before the credit
        # runs out, and the extra window buys nothing.
        if [ "$T_SNDBUF" -lt "$T_WINDOW" ] || [ "$T_RCVBUF" -lt "$T_WINDOW" ]; then
            say ""
            warn "the buffers are smaller than the window"
            dim "a socket that cannot hold one window makes the rest of it"
            dim "unreachable - raise the buffers to ${T_WINDOW} KB or lower the window"
        fi

        say ""
        dim "Read the top box on the other server and make it read the same."
        dim "The rest is local; it will not break the link."

        rule
        item 1 "Profile" "pick a preset and set them all at once"
        item 2 "Carriers" "$T_CARRIERS - parallel connections"
        item 3 "Window" "$T_WINDOW KB - the ceiling on one connection"
        item 4 "Buffers" "$T_SNDBUF / $T_RCVBUF KB - what the sockets hold"
        item 5 "Keepalive" "$T_KEEPALIVE seconds"
        item 6 "Traffic shaping" "$(shaping_label "$name") - must match"
        item 7 "Logging" "$T_LOG"
        item 8 "Health port" "$T_STATUS"
        item 0 "Back"
        say ""
        local c=""
        ask c "select"
        case "$c" in
            1) say ""; preset_menu
               tuning_write "$name" "$T_CARRIERS" "$T_WINDOW" "$T_KEEPALIVE" "$T_SNDBUF" "$T_RCVBUF" ;;
            2) say ""; ask v "parallel connections" "$T_CARRIERS"
               tuning_write "$name" "$v" "$T_WINDOW" "$T_KEEPALIVE" "$T_SNDBUF" "$T_RCVBUF" ;;
            3) say ""
               dim "one connection tops out at window / round trip"
               dim "at ${rtt} ms:  1024 KB = $(stream_ceiling 1024 "$rtt") Mbit/s   4096 KB = $(stream_ceiling 4096 "$rtt") Mbit/s"
               say ""
               ask v "window per connection, KB" "$T_WINDOW"
               tuning_write "$name" "$T_CARRIERS" "$v" "$T_KEEPALIVE" "$T_SNDBUF" "$T_RCVBUF" ;;
            4) edit_buffers "$name" ;;
            5) say ""; ask v "keepalive seconds" "$T_KEEPALIVE"
               tuning_write "$name" "$T_CARRIERS" "$T_WINDOW" "$v" "$T_SNDBUF" "$T_RCVBUF" ;;
            6) edit_shaping "$name" ;;
            7) edit_logging "$name" ;;
            8) edit_health "$name" ;;
            0|"") return ;;
        esac
    done
}

# The socket buffers, on their own screen because there are two of them and
# because getting them wrong is quiet: too small and the window above is a
# fiction, too large and a busy server spends real memory on carriers that
# are idle.
edit_buffers() {
    local name="$1" snd rcv
    cfg_load "$name" || return 1
    banner
    head2 "Buffers: $name"
    say ""
    dim "Each carrier gets a send and a receive buffer of this size, so a"
    dim "$T_CARRIERS-carrier tunnel holds ${T_CARRIERS} of each."
    say ""
    field "Now" "${T_SNDBUF} / ${T_RCVBUF} KB" \
          "In total" "$(( (T_SNDBUF + T_RCVBUF) * T_CARRIERS / 1024 )) MB"
    say ""
    dim "They should be at least the window (${T_WINDOW} KB), or the window"
    dim "cannot fill. Past that they buy nothing."
    say ""
    ask snd "send buffer, KB" "$T_SNDBUF"
    ask rcv "receive buffer, KB" "$T_RCVBUF"
    tuning_write "$name" "$T_CARRIERS" "$T_WINDOW" "$T_KEEPALIVE" "$snd" "$rcv"
}

# tuning_write <name> <carriers> <window> <keepalive> [sndbuf] [rcvbuf]
tuning_write() {
    local name="$1" car="$2" win="$3" ka="$4" snd="${5:-}" rcv="${6:-}" f
    f="$(cfg_file "$name")"
    [ -n "$snd" ] || snd="$win"
    [ -n "$rcv" ] || rcv="$win"
    case "$car$win$ka$snd$rcv" in *[!0-9]* | "") fail "numbers only"; pause; return ;; esac
    [ "$car" -ge 1 ] && [ "$car" -le 64 ] || { fail "carriers must be 1 to 64"; pause; return; }
    [ "$win" -ge 16 ] || { fail "a window under 16 KB stalls every connection"; pause; return; }
    # 64 MB a socket is already past anything a real path can use, and 64 of
    # them is 4 GB of a server that has other work to do.
    [ "$snd" -le 65536 ] && [ "$rcv" -le 65536 ] || { fail "a buffer over 64 MB is not a tuning, it is a leak"; pause; return; }

    cp -f "$f" "$f.bak"
    sed -i "s#^carriers.*#carriers         = $car#" "$f"
    sed -i "s#^window_kb.*#window_kb        = $win#" "$f"
    sed -i "s#^keepalive_sec.*#keepalive_sec    = $ka#" "$f"
    sed -i "s#^sndbuf_kb.*#sndbuf_kb        = $snd#" "$f"
    sed -i "s#^rcvbuf_kb.*#rcvbuf_kb        = $rcv#" "$f"
    # A hand-set profile is no longer whichever preset it started as.
    sed -i "s#^profile.*#profile          = \"$(preset_name "$car" "$win")\"#" "$f"
    if "$CORE_BIN" -c "$f" -check >/dev/null 2>&1; then
        rm -f "$f.bak"
        systemctl restart "pingify@$name"
        ok "saved and restarted"
    else
        mv -f "$f.bak" "$f"
        fail "the core rejected that; nothing was changed"
    fi
    sleep 1
}



recycle_menu() {
    local name="$1"
    say ""
    if systemctl is-enabled --quiet "pingify-recycle@$name.timer" 2>/dev/null; then
        dim "a scheduled recycle is currently active"
        if confirm "turn it off?"; then
            systemctl disable --now "pingify-recycle@$name.timer" >/dev/null 2>&1
            rm -f "$UNIT_DIR/pingify-recycle@$name.timer"
            systemctl daemon-reload
            ok "scheduled recycle removed"
        fi
        pause; return
    fi
    dim "Some Iranian ISPs quietly degrade long-lived connections. A periodic"
    dim "restart costs a second of downtime and clears that up."
    say ""
    local hours=""
    ask hours "restart every N hours (0 to cancel)" "6"
    case "$hours" in ''|*[!0-9]*|0) return ;; esac
    cat > "$UNIT_DIR/pingify-recycle@$name.timer" <<TIMER
[Unit]
Description=Pingify scheduled recycle of tunnel $name

[Timer]
OnBootSec=${hours}h
OnUnitActiveSec=${hours}h
RandomizedDelaySec=120
Unit=pingify-recycle@$name.service

[Install]
WantedBy=timers.target
TIMER
    systemctl daemon-reload
    systemctl enable --now "pingify-recycle@$name.timer" >/dev/null 2>&1
    ok "the tunnel will recycle every ${hours}h"
    pause
}

delete_tunnel() {
    local name="$1"
    say ""
    confirm "really delete tunnel $name?" || return 1

    # Read it before the file goes, so the kernel leftovers can be named.
    local was_kernel=0 iface=""
    if cfg_load "$name" >/dev/null 2>&1 && kernel_transport; then
        was_kernel=1; iface="$T_TUNIF"
    fi

    systemctl disable --now "pingify@$name" >/dev/null 2>&1
    systemctl disable --now "pingify-recycle@$name.timer" >/dev/null 2>&1
    rm -f "$UNIT_DIR/pingify-recycle@$name.timer"
    if [ "$was_kernel" = "1" ]; then
        # The instance unit is a real file for these, not the shared template,
        # and the interface outlives the unit if the stop did not run.
        rm -f "$UNIT_DIR/pingify@$name.service"
        [ -n "$iface" ] && {
            ip link del "$iface" 2>/dev/null
            rm -f "$(awg_conf_path "$iface")"
        }
    fi
    rm -f "$(cfg_file "$name")" "$(cfg_file "$name").bak" "$STATE_DIR/$name.fail"
    systemctl daemon-reload
    # Its forwarding rules outlive the config unless something removes them,
    # and a DNAT rule pointing at an address that no longer exists swallows
    # every packet for that port - which looks exactly like a broken tunnel.
    apply_nat quiet
    ok "tunnel $name removed"
    sleep 1
    return 0
}

# ---------------------------------------------------------------------------
# health
#
# The core already reconnects a carrier on its own. This watchdog is the
# outer layer: it catches a wedged process, a tunnel that lost every carrier,
# and a service that failed to come back after a reboot.
# ---------------------------------------------------------------------------

HEALTH_STRIKES=3

run_health_check() {
    mkdir -p "$STATE_DIR"
    local n f addr fails
    for n in $(tunnel_names); do
        systemctl is-enabled --quiet "pingify@$n" 2>/dev/null || continue
        f="$(cfg_file "$n")"

        if ! systemctl is-active --quiet "pingify@$n"; then
            echo "pingify: $n is not running, starting it"
            systemctl restart "pingify@$n"
            echo 0 > "$STATE_DIR/$n.fail"
            continue
        fi

        addr="$(toml_get "$f" status addr)"
        if [ -z "$addr" ] || [ ! -x "$CORE_BIN" ]; then
            continue
        fi
        if "$CORE_BIN" -healthz "$addr" >/dev/null 2>&1; then
            echo 0 > "$STATE_DIR/$n.fail"
            continue
        fi

        fails="$(cat "$STATE_DIR/$n.fail" 2>/dev/null || echo 0)"
        case "$fails" in ''|*[!0-9]*) fails=0 ;; esac
        fails=$((fails + 1))
        echo "$fails" > "$STATE_DIR/$n.fail"
        echo "pingify: $n has no live carrier (strike $fails of $HEALTH_STRIKES)"
        if [ "$fails" -ge "$HEALTH_STRIKES" ]; then
            echo "pingify: restarting $n"
            systemctl restart "pingify@$n"
            echo 0 > "$STATE_DIR/$n.fail"
        fi
    done
}


# ---------------------------------------------------------------------------
# health check
#
# Every check that fails prints what to do about it. A report that says a
# thing is wrong and stops there leaves you exactly where you started, and the
# faults this tool actually hits are the same handful over and over - a stale
# core, a port nothing is listening on, a leftover NAT rule, a tunnel built one
# way on one server and the other way on the other.
#
# It only reports on what it can see from this machine, and says so where the
# answer is on the other one.
# ---------------------------------------------------------------------------

HC_BAD=0
HC_WARN=0

hc_ok()   { printf '  %s%s%s %s\n' "$C_GRN" "$MK_OK" "$C_OFF" "$1"; }
hc_bad()  { printf '  %s%s%s %s\n' "$C_RED" "$MK_NO" "$C_OFF" "$1"; HC_BAD=$((HC_BAD + 1)); }
hc_warn() { printf '  %s%s%s %s\n' "$C_YEL" "$MK_WARN" "$C_OFF" "$1"; HC_WARN=$((HC_WARN + 1)); }
hc_fix()  { printf '      %s%s fix:%s %s\n' "$C_CYN" "$BX_ARR" "$C_OFF" "$1"; }
hc_note() { printf '      %s%s%s\n' "$C_DIM" "$1" "$C_OFF"; }

health_check() {
    local name="$1" f
    f="$(cfg_file "$name")"
    [ -f "$f" ] || { fail "no such tunnel: $name"; return 1; }
    cfg_load "$name" || return 1
    cfg_endpoints

    HC_BAD=0; HC_WARN=0
    banner
    head2 "Health check: $name"
    say ""

    # --- the core and the script have to agree -----------------------------
    if [ ! -x "$CORE_BIN" ]; then
        hc_bad "the core is not installed"
        hc_fix "main menu ${BX_ARR} Core ${BX_ARR} install"
    elif ! core_matches_script; then
        hc_bad "core $(core_version) against script $PINGIFY_VERSION"
        hc_note "they read the same config file, so a mismatch rejects tunnels"
        hc_fix "main menu ${BX_ARR} Update Pingify"
    else
        hc_ok "core and script are both $PINGIFY_VERSION"
    fi

    # --- the service -------------------------------------------------------
    local state; state="$(svc_state "$name")"
    case "$state" in
        active) hc_ok "the service is running" ;;
        stopped)
            hc_bad "the service is stopped"
            hc_fix "systemctl start pingify@$name" ;;
        *)
            hc_bad "the service is $state"
            hc_fix "journalctl -u pingify@$name -n 40 --no-pager -o cat" ;;
    esac

    # --- the config itself -------------------------------------------------
    # A kernel tunnel has no core in the path, so the core has no opinion on
    # it. What can be checked instead is whether the kernel can still do what
    # the config asks for.
    if kernel_transport; then
        kernel_ready_check
    elif [ -x "$CORE_BIN" ]; then
        if "$CORE_BIN" -c "$f" -check >/dev/null 2>&1; then
            hc_ok "the config is valid"
        else
            hc_bad "the core rejects this config"
            "$CORE_BIN" -c "$f" -check 2>&1 | sed 's/^/      /'
            hc_fix "Manage ${BX_ARR} $name ${BX_ARR} Tuning, or edit $f"
        fi
    fi

    # --- carriers, or the one link a kernel tunnel has ---------------------
    local up=0 total="$T_CARRIERS" rtt="-" brief=""
    if [ "$state" = "active" ]; then
        if kernel_transport; then
            total=1
            brief="$(kernel_brief "$name")"
        elif [ -n "$T_STATUS" ] && [ -x "$CORE_BIN" ]; then
            brief="$("$CORE_BIN" -status "$T_STATUS" -brief 2>/dev/null)"
        fi
    fi
    if [ -n "$brief" ]; then
        set -- $brief
        up="$2"; [ "$3" != "0" ] && total="$3"; rtt="$4"
    fi

    if [ "$state" != "active" ]; then
        :
    elif kernel_transport && [ "$up" = "0" ]; then
        kernel_link_check "$name"
    elif [ -z "$brief" ]; then
        hc_bad "the status endpoint is not answering on $T_STATUS"
        hc_note "the core is running but has not opened it, or has just started"
        hc_fix "journalctl -u pingify@$name -n 20 --no-pager -o cat"
    elif [ "$up" = "0" ]; then
        hc_bad "no carrier is up (0 of $total)"
        if this_side_accepts; then
            hc_note "this end waits for the other one to connect"
            if [ "$T_TRANSPORT" = "tcp" ]; then
                hc_fix "check the other server is running, then open ${T_PORT}/tcp here:"
                hc_note "ufw allow ${T_PORT}/tcp    (or the provider's firewall)"
                hc_note "if it still will not hold, rebuild with Direct instead"
            else
                hc_fix "check the other server is running and can ping this one"
            fi
        else
            hc_note "this end dials ${CFG_CONNECT}"
            if [ "$T_TRANSPORT" = "tcp" ]; then
                hc_fix "check that port is open on the other server"
                hc_note "from here:  timeout 5 bash -c '</dev/tcp/${CFG_CONNECT%:*}/${CFG_CONNECT##*:}' && echo open"
            else
                hc_fix "check the other server answers a ping:  ping -c3 ${CFG_CONNECT}"
            fi
        fi
        hc_note "and that both ends have the same security token"
    elif [ "$up" != "$total" ]; then
        hc_warn "$up of $total carriers are up"
        hc_note "some are being dropped - the path is lossy or something is trimming them"
        hc_fix "Manage ${BX_ARR} $name ${BX_ARR} Live log, and look for 'carrier .* down'"
    else
        hc_ok "$up of $total carriers up, $(rtt_tint "${rtt}ms") to the other server"
        # A long round trip is usually geography rather than a fault, so it
        # explains itself and is not counted as a problem.
        if rtt_slow "$rtt"; then
            hc_note "that is a long way round - anything interactive will feel it"
            hc_note "the other server being closer is the only thing that fixes it"
        fi
    fi

    # --- the forwarded ports, on the end that has them ---------------------
    #
    # What "bound" means depends on who forwards. Our core binds the port and
    # accepts on it. The kernel does not bind anything at all - a DNAT rule
    # rewrites the destination in PREROUTING, before any socket is consulted -
    # so asking whether something is listening reports a fault on every
    # working iptables tunnel, and offers a restart that cannot help.
    if [ "$T_ROLE" = "server" ] && [ -n "$T_FORWARDS" ]; then
        local p spec bad=0 rules=""
        [ "$T_FORWARDER" = "iptables" ] && have iptables \
            && rules="$(iptables -t nat -S PINGIFY_NAT 2>/dev/null)"
        for spec in $(printf '%s' "$T_FORWARDS" | tr -d '"' | tr ',' ' '); do
            p="${spec%%=*}"; p="${p#udp:}"; p="${p#tcp:}"; p="${p%%-*}"
            case "$p" in '' | *[!0-9]*) continue ;; esac
            if [ "$T_FORWARDER" = "iptables" ]; then
                if ! printf '%s' "$rules" | grep -q -- "--dport $p "; then
                    hc_bad "no forwarding rule for :$p"
                    hc_note "the kernel forwards this tunnel, so the port is not"
                    hc_note "bound here - it is rewritten on the way past"
                    hc_fix "pingify --apply-firewall"
                    bad=1
                fi
            elif port_free "$p"; then
                hc_bad "nothing is listening on :$p"
                hc_fix "systemctl restart pingify@$name"
                bad=1
            fi
        done
        if [ "$bad" = "0" ]; then
            if [ "$T_FORWARDER" = "iptables" ]; then
                hc_ok "every forwarded port has a rule here"
            else
                hc_ok "every forwarded port is bound here"
            fi
        fi
    fi

    # --- a leftover NAT rule eats a port silently --------------------------
    if have iptables && iptables -t nat -S PINGIFY_NAT >/dev/null 2>&1; then
        local rules; rules="$(iptables -t nat -S PINGIFY_NAT 2>/dev/null | grep -c ' -j DNAT')"
        if [ "${rules:-0}" != "0" ] && [ "$T_FORWARDER" != "iptables" ]; then
            hc_warn "$rules forwarding rules are installed but this tunnel does not use them"
            hc_note "a rule pointing at an address that has gone swallows every packet"
            hc_note "for that port, which looks exactly like a broken tunnel"
            hc_fix "pingify --apply-firewall     (rebuilds them from the configs)"
        fi
    fi

    # --- ICMP echo, on a tunnel that rides in it ---------------------------
    # The kernel answering an ordinary ping costs nothing, but it answers
    # every scanner on the internet, and this server is meant to look quiet.
    # It never touches our own traffic: the transport is a raw socket, which
    # the kernel copies to us regardless, and both ends send echo *replies*,
    # which the kernel never answers by itself. So the block is wanted here.
    if [ "$T_TRANSPORT" = "icmp" ]; then
        if [ "$(block_state icmp)" = "on" ]; then
            hc_ok "this server is not answering pings, which is what we want"
        else
            hc_warn "this server still answers ordinary pings"
            hc_note "the tunnel keeps working either way, but the server is"
            hc_note "louder than it needs to be and answers every scanner"
            hc_fix "main menu ${BX_ARR} Blocking ${BX_ARR} turn the ICMP block on"
        fi
    fi

    # --- the far side ------------------------------------------------------
    # The probe is the only check here that reaches past this machine, and
    # its verdict has to reach the summary: a report that lists a port the
    # other server could not reach and then says nothing is wrong is worse
    # than no report at all.
    # Not for a kernel tunnel: the probe is part of the core, and the core
    # cannot even read a config for a transport it does not run. Asking it
    # anyway produced a rejection and then blamed the far server for it.
    if [ "$T_ROLE" = "server" ] && [ "$up" != "0" ] && [ -n "$T_FORWARDS" ]        && ! kernel_transport; then
        say ""
        head2 "Through the tunnel"
        local out rc
        out="$("$CORE_BIN" -c "$f" -probe 2>&1)"; rc=$?
        # the carrier line is already above, in this report's own words
        printf '%s\n' "$out" | sed '/carriers up,/d' | sed 's/^/  /'
        if [ "$rc" != "0" ]; then
            say ""
            hc_bad "a forwarded port did not reach the service on the other server"
            hc_note "this end is fine - the tunnel carried the test across"
            hc_note "and the far end is where it stopped"
            hc_fix "on the KHAREJ server:  ss -ltnp | grep <the port after the arrow>"
            hc_note "whatever should answer there is not listening on that address"
        fi
    fi

    # A kernel tunnel gets the same question asked a different way: not
    # through the core, which is not in this path, but across the private link
    # the kernel built - which is the route real traffic takes.
    if [ "$T_ROLE" = "server" ] && [ "$up" != "0" ] && kernel_transport; then
        say ""
        head2 "Through the tunnel"
        kernel_probe "$name" || {
            say ""
            hc_note "everything on this server is doing its part"
        }
    fi

    # --- what it comes to --------------------------------------------------
    say ""
    rule
    if [ "$HC_BAD" = "0" ] && [ "$HC_WARN" = "0" ]; then
        ok "nothing wrong on this server"
        dim "if the tunnel still misbehaves, run this on the other one too"
    elif [ "$HC_BAD" = "0" ]; then
        warn "$HC_WARN thing$([ "$HC_WARN" = "1" ] || echo s) worth looking at"
    else
        fail "$HC_BAD problem$([ "$HC_BAD" = "1" ] || echo s), $HC_WARN warning$([ "$HC_WARN" = "1" ] || echo s)"
        dim "each one has a fix under it"
    fi
    pause
}

enable_watchdog() {
    write_units
    systemctl enable --now pingify-health.timer >/dev/null 2>&1
    [ "${1:-}" = "quiet" ] || ok "watchdog enabled (checks every 30s)"
}

disable_watchdog() {
    systemctl disable --now pingify-health.timer >/dev/null 2>&1
    ok "watchdog disabled"
}

watchdog_state() {
    if systemctl is-enabled --quiet pingify-health.timer 2>/dev/null; then
        printf 'on'
    else
        printf 'off'
    fi
}

live_dashboard() {
    local key=""
    while :; do
        banner
        head2 "Live status"
        list_tunnels
        rule
        say "  ${C_DIM}watchdog: $(watchdog_state)   $(uptime | sed 's/^ *//')${C_OFF}"
        say ""
        dim "  refreshing every 2s - enter or q to go back"
        # read returns 0 only when a key actually arrived, and non-zero when
        # the two seconds ran out. Without that test an empty key means both
        # "the user pressed enter" and "nothing happened", so enter did
        # nothing and the only way out of here was to kill the script.
        if read -rsn1 -t 2 key; then
            case "$key" in q|Q|0|"") return ;; esac
        fi
    done
}

health_menu() {
    while :; do
        banner
        head2 "Health"
        list_tunnels
        rule
        item 1 "Health check" "what is wrong, and what to do about it"
        item 2 "Live status dashboard"
        item 3 "Enable the watchdog"
        item 4 "Disable the watchdog"
        item 5 "Recent health log"
        item 6 "Restart every tunnel"
        item 0 "Back"
        say ""
        local c=""
        ask c "select"
        case "$c" in
            1) if pick_tunnel; then health_check "$PICKED"; fi ;;
            2) live_dashboard ;;
            3) enable_watchdog; pause ;;
            4) disable_watchdog; pause ;;
            5) say ""; journalctl -u pingify-health.service -n 40 --no-pager -o cat | sed 's/^/  /'; pause ;;
            6) local n
               for n in $(tunnel_names); do systemctl restart "pingify@$n"; ok "restarted $n"; done
               pause ;;
            0|"") return ;;
        esac
    done
}

# ---------------------------------------------------------------------------
# server and network tuning
#
# The defaults on a stock Ubuntu image are sized for a datacentre LAN. An
# Iran <-> Europe path has ~40-120 ms of RTT and real packet loss, so the
# kernel needs far more room in flight and a congestion control that does not
# read loss as congestion.
# ---------------------------------------------------------------------------

apply_tuning() {
    local want_forward="${1:-no}"
    say ""
    if [ -f "$SYSCTL_FILE" ]; then
        dim "replacing the previous Pingify tuning"
    else
        # Keep one copy of whatever the box looked like before we touched it.
        [ -f "$STATE_DIR/sysctl.pre" ] || sysctl -a 2>/dev/null > "$STATE_DIR/sysctl.pre"
    fi

    cat > "$SYSCTL_FILE" <<SYSCTL
# Written by Pingify $PINGIFY_VERSION. Delete this file and run
# "sysctl --system" to go back to the distribution defaults.

# --- room in flight: 64 MB covers a 200 ms / 2.5 Gbit path ---
net.core.rmem_max = 67108864
net.core.wmem_max = 67108864
net.core.rmem_default = 1048576
net.core.wmem_default = 1048576
net.ipv4.tcp_rmem = 4096 1048576 67108864
net.ipv4.tcp_wmem = 4096 1048576 67108864
net.ipv4.udp_rmem_min = 16384
net.ipv4.udp_wmem_min = 16384

# --- behave sensibly on a long, slightly lossy path ---
net.ipv4.tcp_mtu_probing = 1
net.ipv4.tcp_slow_start_after_idle = 0
net.ipv4.tcp_no_metrics_save = 1
net.ipv4.tcp_notsent_lowat = 131072
net.ipv4.tcp_fastopen = 3
net.ipv4.tcp_window_scaling = 1
net.ipv4.tcp_sack = 1

# --- connection churn ---
net.core.somaxconn = 65535
net.core.netdev_max_backlog = 250000
net.ipv4.tcp_max_syn_backlog = 8192
net.ipv4.tcp_syncookies = 1
net.ipv4.tcp_fin_timeout = 15
net.ipv4.tcp_tw_reuse = 1
net.ipv4.tcp_keepalive_time = 300
net.ipv4.tcp_keepalive_intvl = 30
net.ipv4.tcp_keepalive_probes = 5
net.ipv4.ip_local_port_range = 10240 65535

# --- file descriptors ---
fs.file-max = 2097152
fs.nr_open = 2097152
SYSCTL

    if [ "$want_forward" = "yes" ]; then
        cat >> "$SYSCTL_FILE" <<'SYSCTL'

# --- routing, for full-IP tunnels ---
net.ipv4.ip_forward = 1
net.ipv6.conf.all.forwarding = 1
SYSCTL
    fi

    sysctl --system >/dev/null 2>&1
    ok "network tuning applied"
    dim "congestion control is a separate switch - see Enable BBR"

    if ! grep -q 'pingify' /etc/security/limits.d/99-pingify.conf 2>/dev/null; then
        cat > /etc/security/limits.d/99-pingify.conf <<'LIMITS'
# Pingify
*   soft  nofile  1048576
*   hard  nofile  1048576
root soft nofile  1048576
root hard nofile  1048576
LIMITS
        ok "file descriptor limits raised (log out and back in for shells)"
    fi
}

# BBR is its own switch: it is the one change with a visible effect on a slow
# path, and people want to turn it on or off without touching everything else.
enable_bbr() {
    say ""
    if ! lsmod 2>/dev/null | grep -q '^tcp_bbr'; then
        modprobe tcp_bbr 2>/dev/null || true
    fi
    if ! sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null | grep -qw bbr; then
        fail "this kernel does not offer BBR"
        dim "kernel $(uname -r); a 4.9 or newer kernel with tcp_bbr is needed"
        return 1
    fi
    echo tcp_bbr > /etc/modules-load.d/pingify.conf
    cat > /etc/sysctl.d/98-pingify-bbr.conf <<'SYSCTL'
# Written by Pingify. Delete this file and run "sysctl --system" to undo it.
net.core.default_qdisc = fq
net.ipv4.tcp_congestion_control = bbr
SYSCTL
    sysctl --system >/dev/null 2>&1
    ok "BBR enabled with the fq queue discipline"
    dim "now: $(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null) / $(sysctl -n net.core.default_qdisc 2>/dev/null)"
}

disable_bbr() {
    say ""
    rm -f /etc/sysctl.d/98-pingify-bbr.conf /etc/modules-load.d/pingify.conf
    sysctl -w net.ipv4.tcp_congestion_control=cubic >/dev/null 2>&1
    sysctl --system >/dev/null 2>&1
    ok "back to $(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null)"
}

revert_tuning() {
    rm -f "$SYSCTL_FILE" /etc/security/limits.d/99-pingify.conf           /etc/modules-load.d/pingify.conf /etc/sysctl.d/98-pingify-bbr.conf
    sysctl --system >/dev/null 2>&1
    ok "Pingify tuning removed; the distribution defaults are back"
    dim "a reboot makes absolutely sure nothing is left over"
}

show_net_settings() {
    say ""
    printf '  %-34s %s\n' "congestion control" "$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null)"
    printf '  %-34s %s\n' "available" "$(sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null)"
    printf '  %-34s %s\n' "default qdisc" "$(sysctl -n net.core.default_qdisc 2>/dev/null)"
    printf '  %-34s %s\n' "rmem_max" "$(sysctl -n net.core.rmem_max 2>/dev/null)"
    printf '  %-34s %s\n' "wmem_max" "$(sysctl -n net.core.wmem_max 2>/dev/null)"
    printf '  %-34s %s\n' "tcp_rmem" "$(sysctl -n net.ipv4.tcp_rmem 2>/dev/null)"
    printf '  %-34s %s\n' "tcp_wmem" "$(sysctl -n net.ipv4.tcp_wmem 2>/dev/null)"
    printf '  %-34s %s\n' "mtu probing" "$(sysctl -n net.ipv4.tcp_mtu_probing 2>/dev/null)"
    printf '  %-34s %s\n' "ip_forward" "$(sysctl -n net.ipv4.ip_forward 2>/dev/null)"
    printf '  %-34s %s\n' "open file limit" "$(ulimit -n)"
    printf '  %-34s %s\n' "Pingify tuning file" "$([ -f "$SYSCTL_FILE" ] && echo present || echo absent)"
    say ""
}

manage_swap() {
    say ""
    local cur; cur="$(free -m | awk '/^Swap:/{print $2}')"
    dim "current swap: ${cur:-0} MB"
    if [ "${cur:-0}" -gt 0 ] 2>/dev/null; then
        if confirm "remove the existing Pingify swap file?"; then
            swapoff /swapfile 2>/dev/null || true
            sed -i '\#^/swapfile #d' /etc/fstab
            rm -f /swapfile
            ok "swap file removed"
            pause; return
        fi
    fi
    local mb=""
    ask mb "swap size in MB (0 to cancel)" "1024"
    case "$mb" in ''|*[!0-9]*|0) return ;; esac
    swapoff /swapfile 2>/dev/null || true
    rm -f /swapfile
    info "creating a ${mb}MB swap file"
    if ! fallocate -l "${mb}M" /swapfile 2>/dev/null; then
        dd if=/dev/zero of=/swapfile bs=1M count="$mb" status=none || { fail "could not create it"; pause; return; }
    fi
    chmod 600 /swapfile
    mkswap /swapfile >/dev/null 2>&1
    swapon /swapfile || { fail "swapon failed"; pause; return; }
    grep -q '^/swapfile ' /etc/fstab || echo '/swapfile none swap sw 0 0' >> /etc/fstab
    sysctl -w vm.swappiness=10 >/dev/null 2>&1
    ok "swap ready"
    pause
}

optimize_menu() {
    while :; do
        banner
        head2 "Optimize"
        panel "CURRENT"
        field "Congestion" "$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null)"               "Qdisc" "$(sysctl -n net.core.default_qdisc 2>/dev/null)"
        field "Tuning" "$([ -f "$SYSCTL_FILE" ] && echo applied || echo default)"               "Open files" "$(ulimit -n)"
        panel_end
        say ""
        item 1 "Apply network optimization" "buffers, backlogs, file limits"
        item 2 "Enable BBR" "congestion control and fq"
        item 3 "Disable BBR" "back to the kernel default"
        say ""
        item 4 "Enable IP forwarding" "needed for Full IP tunnels"
        item 5 "Swap file"
        item 6 "Sync the clock" "the handshake rejects a skewed clock"
        say ""
        item 7 "Show all settings"
        item 8 "Revert everything Pingify changed"
        item 0 "Back"
        say ""
        local c=""
        ask c "select"
        case "$c" in
            1) apply_tuning no; pause ;;
            2) enable_bbr; pause ;;
            3) disable_bbr; pause ;;
            4) apply_tuning yes; pause ;;
            5) manage_swap ;;
            6) sync_clock; pause ;;
            7) show_net_settings; pause ;;
            8) say ""; confirm "revert the sysctl and limits changes?" && revert_tuning; pause ;;
            0 | "") return ;;
        esac
    done
}

sync_clock() {
    say ""
    info "current time: $(date -u '+%Y-%m-%d %H:%M:%S UTC')"
    if have timedatectl; then
        timedatectl set-ntp true 2>/dev/null && ok "NTP synchronisation enabled"
        timedatectl status 2>/dev/null | sed 's/^/  /'
    else
        warn "timedatectl is missing; install systemd-timesyncd or chrony"
    fi
    dim "Pingify rejects a handshake more than 3 minutes out, so both servers"
    dim "must agree on the time."
}

# ---------------------------------------------------------------------------
# blocking
#
# Three switches people running a tunnel keep reaching for:
#
#   ICMP       stop the server answering pings
#   speedtest  keep clients from burning the link on benchmark sites
#   UDP 443    reject QUIC, so browsers fall back to TCP where the tunnel
#
# Everything goes in Pingify's own iptables chains, so nothing here touches
# rules you or your panel put in place. State lives in $STATE_DIR and a boot
# unit re-applies it, because iptables rules do not survive a reboot.
# ---------------------------------------------------------------------------

SPEEDTEST_HOSTS="speedtest.net ooklaserver.net speedtestcustom.com fast.com \
nperf.com speedof.me openspeedtest.com speedcheck.org librespeed.org \
测速 speedtest.cn"

# The hosts file gets a marked block so it can be removed cleanly.
HOSTS_MARK="# --- pingify speedtest block ---"

block_state() { [ -f "$STATE_DIR/block-$1" ] && printf 'on' || printf 'off'; }

block_summary() {
    local out=""
    [ "$(block_state icmp)" = "on" ]      && out="${out}icmp "
    [ "$(block_state speedtest)" = "on" ] && out="${out}speedtest "
    [ "$(block_state quic)" = "on" ]      && out="${out}quic "
    [ -n "$out" ] && printf '%s' "${out% }" || printf 'none'
}

block_toggle() {
    local what="$1"
    if [ -f "$STATE_DIR/block-$what" ]; then
        rm -f "$STATE_DIR/block-$what"
    else
        mkdir -p "$STATE_DIR"
        : > "$STATE_DIR/block-$what"
    fi
    apply_blocking
}

# ---------------------------------------------------------------------------
# applying
# ---------------------------------------------------------------------------

ipt() { iptables "$@" 2>/dev/null; }

# Our chains, hooked once into the built-in ones and rebuilt from scratch each
# time so the state file is always the single source of truth.
block_reset_chains() {
    local c
    for c in PINGIFY_IN PINGIFY_OUT PINGIFY_FWD; do
        ipt -N "$c" || ipt -F "$c"
    done
    ipt -C INPUT   -j PINGIFY_IN  || ipt -I INPUT 1   -j PINGIFY_IN
    ipt -C OUTPUT  -j PINGIFY_OUT || ipt -I OUTPUT 1  -j PINGIFY_OUT
    ipt -C FORWARD -j PINGIFY_FWD || ipt -I FORWARD 1 -j PINGIFY_FWD
}

block_drop_chains() {
    ipt -D INPUT   -j PINGIFY_IN
    ipt -D OUTPUT  -j PINGIFY_OUT
    ipt -D FORWARD -j PINGIFY_FWD
    local c
    for c in PINGIFY_IN PINGIFY_OUT PINGIFY_FWD; do
        ipt -F "$c"
        ipt -X "$c"
    done
}

hosts_block_off() {
    if grep -qF "$HOSTS_MARK" /etc/hosts 2>/dev/null; then
        sed -i "/$(printf '%s' "$HOSTS_MARK" | sed 's/[]\/$*.^[]/\\&/g')/,/# --- end pingify ---/d" /etc/hosts
    fi
}

hosts_block_on() {
    hosts_block_off
    {
        printf '%s\n' "$HOSTS_MARK"
        local h
        for h in $SPEEDTEST_HOSTS; do
            case "$h" in *[!a-zA-Z0-9.-]*) continue ;; esac
            printf '127.0.0.1 %s\n127.0.0.1 www.%s\n' "$h" "$h"
        done
        printf '%s\n' "# --- end pingify ---"
    } >> /etc/hosts
}

apply_blocking() {
    local quiet="${1:-}"
    have iptables || { [ "$quiet" = quiet ] || warn "iptables is not installed; nothing applied"; return 1; }
    mkdir -p "$STATE_DIR"
    block_reset_chains

    # --- ICMP -------------------------------------------------------------
    #
    # Dropped in the firewall rather than switched off in the kernel, because
    # icmp_echo_ignore_all is global and a private link is not public.
    #
    # A server told to ignore every echo also ignores the one its own tunnel's
    # health check sends across the private link - so building an ICMP tunnel,
    # which turns this on, made every GRE tunnel on the same pair of servers
    # read as down while it was carrying traffic perfectly well.
    #
    # A rule can tell the two apart. Echo requests arriving on a tunnel
    # interface are answered; everything else is dropped, which is the whole
    # point of the switch. Our own ICMP transport is untouched either way:
    # it rides in echo *replies*, which nothing here matches.
    if [ "$(block_state icmp)" = "on" ]; then
        if have iptables; then
            rm -f /etc/sysctl.d/99-pingify-block.conf
            sysctl -w net.ipv4.icmp_echo_ignore_all=0 >/dev/null 2>&1
            local ifc
            for ifc in $(tun_ifaces | awk '{print $1}'); do
                [ -n "$ifc" ] || continue
                ipt -A PINGIFY_IN -i "$ifc" -p icmp --icmp-type echo-request -j ACCEPT
            done
            ipt -A PINGIFY_IN -p icmp --icmp-type echo-request -j DROP
        else
            # No firewall to be selective with: the blunt switch, and the
            # health check knows to expect it.
            printf 'net.ipv4.icmp_echo_ignore_all = 1\n' > /etc/sysctl.d/99-pingify-block.conf
        fi
    else
        rm -f /etc/sysctl.d/99-pingify-block.conf
        sysctl -w net.ipv4.icmp_echo_ignore_all=0 >/dev/null 2>&1
    fi
    sysctl --system >/dev/null 2>&1
    # --- speedtest --------------------------------------------------------
    if [ "$(block_state speedtest)" = "on" ]; then
        hosts_block_on
        local h ok_any=0
        for h in $SPEEDTEST_HOSTS; do
            case "$h" in *[!a-zA-Z0-9.-]*) continue ;; esac
            # Matches the hostname in a plaintext TLS ClientHello, so it also
            # catches traffic that only passes through this server.
            if ipt -A PINGIFY_OUT -m string --string "$h" --algo bm -j REJECT; then ok_any=1; fi
            ipt -A PINGIFY_FWD -m string --string "$h" --algo bm -j REJECT
        done
        if [ "$ok_any" = "0" ] && [ "$quiet" != quiet ]; then
            warn "the kernel string match is unavailable; only the hosts file block is active"
        fi
    else
        hosts_block_off
    fi

    # --- QUIC -------------------------------------------------------------
    if [ "$(block_state quic)" = "on" ]; then
        ipt -A PINGIFY_OUT -p udp --dport 443 -j REJECT --reject-with icmp-port-unreachable
        ipt -A PINGIFY_FWD -p udp --dport 443 -j REJECT --reject-with icmp-port-unreachable
        ipt -A PINGIFY_IN  -p udp --dport 443 -j DROP
    fi

    write_firewall_unit
    [ "$quiet" = quiet ] || ok "blocking rules applied"
    return 0
}

# iptables forgets everything on reboot, so re-apply from the state files.
write_firewall_unit() {
    cat > "$UNIT_DIR/pingify-firewall.service" <<UNIT
[Unit]
Description=Pingify blocking rules
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=$SELF_BIN --apply-firewall

[Install]
WantedBy=multi-user.target
UNIT
    systemctl daemon-reload
    systemctl enable pingify-firewall.service >/dev/null 2>&1
}

remove_blocking() {
    rm -f "$STATE_DIR"/block-icmp "$STATE_DIR"/block-speedtest "$STATE_DIR"/block-quic
    rm -f /etc/sysctl.d/99-pingify-block.conf
    sysctl -w net.ipv4.icmp_echo_ignore_all=0 >/dev/null 2>&1
    hosts_block_off
    have iptables && block_drop_chains
    systemctl disable --now pingify-firewall.service >/dev/null 2>&1
    rm -f "$UNIT_DIR/pingify-firewall.service"
    systemctl daemon-reload
}

# ---------------------------------------------------------------------------
# menu
# ---------------------------------------------------------------------------

blocking_menu() {
    while :; do
        banner
        head2 "Blocking"
        panel "RULES"
        row "$(pad_to "${C_DIM}Ping / ICMP${C_OFF}" 22)$(state_badge "$(block_state icmp)")"
        row "$(pad_to "${C_DIM}Speedtest sites${C_OFF}" 22)$(state_badge "$(block_state speedtest)")"
        row "$(pad_to "${C_DIM}UDP 443${C_OFF}" 22)$(state_badge "$(block_state quic)")"
        panel_end
        say ""
        item 1 "Ping / ICMP" "stop this server answering pings - wanted on an ICMP tunnel"
        item 2 "Speedtest sites" "block benchmark sites and their CDNs"
        item 3 "Block UDP 443" "rejects QUIC, so browsers fall back to TCP"
        say ""
        item 4 "Show the live rules"
        item 5 "Clear everything"
        item 0 "Back"
        say ""
        local c=""
        ask c "select"
        case "$c" in
            1) say ""
               # The question people arrive with is whether this breaks an
               # ICMP tunnel. It does not, and the reason is worth stating
               # once here rather than being rediscovered on a live server.
               if [ "$(block_state icmp)" != "on" ]; then
                   dim "Safe with an ICMP tunnel running. The tunnel reads from a raw"
                   dim "socket, which the kernel copies to us whatever this is set to,"
                   dim "and both ends send echo replies, which the kernel never answers"
                   dim "by itself. This only stops it answering other people's pings."
                   say ""
               fi
               block_toggle icmp
               if [ "$(block_state icmp)" = "on" ]; then
                   ok "this server no longer answers pings"
               else
                   ok "this server answers pings again"
               fi
               pause ;;
            2) say ""
               dim "This works on traffic leaving in the clear, so it belongs on"
               dim "the KHAREJ server - that is where the proxy talks to the site."
               say ""
               block_toggle speedtest; pause ;;
            3) say ""; block_toggle quic; pause ;;
            4) say ""
               if have iptables; then
                   iptables -S PINGIFY_IN PINGIFY_OUT PINGIFY_FWD 2>/dev/null | sed 's/^/    /' | head -n 40
                   printf '    %sicmp_echo_ignore_all = %s%s\n' \
                       "$C_DIM" "$(sysctl -n net.ipv4.icmp_echo_ignore_all 2>/dev/null)" "$C_OFF"
               else
                   warn "iptables is not installed"
               fi
               pause ;;
            5) say ""
               confirm "remove every blocking rule?" && { remove_blocking; ok "cleared"; }
               pause ;;
            0 | "") return ;;
        esac
    done
}

# ---------------------------------------------------------------------------
# measuring
#
# Two different questions, and confusing them wastes an afternoon:
#
#   what can the PATH between these two servers carry?
#       iperf3 straight between the public addresses. This is the ceiling -
#       no tunnel is going to beat it.
#
#   what does the TUNNEL deliver of that?
#       the same test, but over the tunnel's own addresses. This is the
#       number your users actually get.
#
# Measuring only one tells you nothing. 90 Mbit/s through the tunnel is
# excellent on a path that carries 100 and dreadful on a path that carries
# 500, and the only way to know which you have is to measure both. So this
# does, and prints them together.
#
# iperf3 with twenty parallel streams, ten seconds each way. Twenty because a
# single TCP stream on a 90 ms path is limited by its own window long before
# the path is full - one stream measures TCP, twenty measure the path.
# ---------------------------------------------------------------------------

IPERF_PORT=5201
IPERF_STREAMS=20
IPERF_SECONDS=10

iperf_ready() { have iperf3; }

iperf_install() {
    iperf_ready && return 0
    say ""
    dim "installing iperf3"
    if have apt-get; then
        apt-get update >/dev/null 2>&1
        DEBIAN_FRONTEND=noninteractive apt-get install -y iperf3 >/dev/null 2>&1
    elif have dnf; then
        dnf install -y iperf3 >/dev/null 2>&1
    elif have yum; then
        yum install -y iperf3 >/dev/null 2>&1
    elif have apk; then
        apk add --no-cache iperf3 >/dev/null 2>&1
    fi
    iperf_ready && { ok "iperf3 installed"; return 0; }
    fail "iperf3 could not be installed here"
    dim "install it by hand and come back:  apt install -y iperf3"
    return 1
}

# iperf_bitrate OUTPUT WHICH - the [SUM] line's bitrate, which is the only
# number in a twenty-stream run that means anything. WHICH is sender or
# receiver.
iperf_bitrate() {
    printf '%s' "$1" | grep '\[SUM\]' | grep "$2" | tail -1 \
        | awk '{ for (i = 1; i < NF; i++) if ($(i+1) ~ /bits\/sec/) print $i, $(i+1) }'
}

# speed_over_link - true when this tunnel has private addresses to measure
# between, which is the clean way to do it.
speed_over_link() { [ -n "${T_TUNPEER%%/*}" ] && [ -n "${T_TUNLOCAL%%/*}" ]; }

# speed_first_port - the first forwarded TCP port, as "local remote"
speed_first_port() {
    local spec lport rport
    for spec in $(printf '%s' "$T_FORWARDS" | tr -d '"' | tr ',' ' '); do
        case "$spec" in udp:*) continue ;; tcp:*) spec="${spec#tcp:}" ;; esac
        lport="${spec%%=*}"; rport="${spec#*=}"
        [ "$rport" = "$spec" ] && rport="$lport"
        lport="${lport%%-*}"; rport="${rport%%-*}"
        case "$lport$rport" in '' | *[!0-9]*) continue ;; esac
        printf '%s %s' "$lport" "$rport"
        return 0
    done
    return 1
}

# The other server's public address, however this end happens to know it.
speed_peer_public() {
    local p="$T_PEER_IP"
    [ -n "$p" ] || p="$(status_peer "$PICKED" 2>/dev/null)"
    printf '%s' "$p"
    [ -n "$p" ]
}

# Two steps, in order, one on each server. Anything more than that on this
# screen is a way to do it in the wrong order.
speed_menu() {
    local side here_a="" here_b=""
    side="$(this_side)"
    case "$side" in
        IRAN)   here_b="${C_GRN}  ${BX_ARR} this server${C_OFF}" ;;
        KHAREJ) here_a="${C_GRN}  ${BX_ARR} this server${C_OFF}" ;;
    esac

    while :; do
        banner
        head2 "iperf3"
        say ""
        dim "Real bandwidth between your two servers. ${IPERF_STREAMS} parallel streams,"
        dim "${IPERF_SECONDS} seconds each way - one stream on a 90 ms path runs out of its"
        dim "own window long before the path runs out of room."
        say ""
        say "  ${C_B}1${C_OFF} ${BX_ARR} Hold the listener   ${C_DIM}on KHAREJ, first${C_OFF}${here_a}"
        say "  ${C_B}2${C_OFF} ${BX_ARR} Run the test        ${C_DIM}on IRAN, after that${C_OFF}${here_b}"
        say ""
        item 0 "Back"
        say ""
        local c=""
        ask c "select"
        case "$c" in
            1) speed_listen ;;
            2) speed_run both ;;
            0 | "") return ;;
        esac
    done
}

speed_listen() {
    iperf_install || { pause; return 0; }
    banner
    head2 "Listener"
    say ""
    dim "iperf3 -s, answering on every address this server has - so it serves"
    dim "both a test over the tunnel and one over the public path."
    say ""
    ok "waiting on port $(addr_tint "$IPERF_PORT")"
    say ""
    dim "Now run the test from the other server."
    dim "ctrl-c when it is finished."
    say ""
    trap ':' INT
    iperf3 -s -p "$IPERF_PORT" 2>&1 | sed 's/^/  /'
    trap - INT
    say ""
    ok "listener stopped"
    pause
}

# speed_one TARGET LABEL - ten seconds each way against TARGET, printing what
# it finds. Sets SPEED_DOWN and SPEED_UP.
speed_one() {
    local target="$1" port="$2" out
    SPEED_DOWN=""; SPEED_UP=""

    dim "sending - this is your users' download"
    out="$(iperf3 -c "$target" -p "$port" -i 1 -t "$IPERF_SECONDS" -P "$IPERF_STREAMS" 2>&1)" || {
        say ""
        fail "the test did not run"
        printf '%s\n' "$out" | tail -n 4 | sed 's/^/      /'
        return 1
    }
    SPEED_DOWN="$(iperf_bitrate "$out" sender)"
    dim "  ${SPEED_DOWN:-no reading}"

    say ""
    dim "receiving - this is your users' upload"
    out="$(iperf3 -c "$target" -p "$port" -i 1 -t "$IPERF_SECONDS" -P "$IPERF_STREAMS" -R 2>&1)" || {
        say ""
        warn "the reverse test did not run"
        return 0
    }
    SPEED_UP="$(iperf_bitrate "$out" receiver)"
    dim "  ${SPEED_UP:-no reading}"
    return 0
}

# mbits VALUE - "412 Mbits/sec" as a bare number, for comparing two of them
mbits() {
    local n u
    n="$(printf '%s' "$1" | awk '{print $1}')"
    u="$(printf '%s' "$1" | awk '{print $2}')"
    case "$n" in '' | *[!0-9.]*) printf '0'; return 1 ;; esac
    case "$u" in
        Gbits/sec) printf '%s' "$(awk -v x="$n" 'BEGIN{printf "%d", x*1000}')" ;;
        Kbits/sec) printf '%s' "$(awk -v x="$n" 'BEGIN{printf "%d", x/1000}')" ;;
        *)         printf '%s' "$(awk -v x="$n" 'BEGIN{printf "%d", x}')" ;;
    esac
}

speed_run() {
    local what="$1"
    pick_tunnel || return 0
    cfg_load "$PICKED" || return 0
    iperf_install || { pause; return 0; }

    local tun_target="" tun_port="$IPERF_PORT" how="" pub=""
    if [ "$what" != "path" ]; then
        if speed_over_link; then
            tun_target="${T_TUNPEER%%/*}"
            how="across the private link"
        else
            local ports
            ports="$(speed_first_port)" || {
                fail "this tunnel has no private link and forwards no TCP port"
                dim "there is no way in to measure through it"
                pause; return 0
            }
            tun_target="127.0.0.1"
            tun_port="${ports%% *}"
            how="through forwarded port ${tun_port}"
        fi
    fi
    if [ "$what" != "tunnel" ]; then
        pub="$(speed_peer_public)" || {
            if [ "$what" = "path" ]; then
                fail "this end does not know the other server's public address"
                dim "it accepts rather than dials, and the tunnel is not up to be asked"
                pause; return 0
            fi
            pub=""
        }
    fi

    banner
    head2 "Speed test: $PICKED"
    say ""
    field "Transport" "$(transport_label "$T_TRANSPORT")"
    [ -n "$tun_target" ] && field "Tunnel" "$(addr_tint "${tun_target}:${tun_port}") $how"
    [ -n "$pub" ]        && field "Raw path" "$(addr_tint "${pub}:${IPERF_PORT}")"
    say ""
    warn "the other server must be holding a listener right now"
    dim "Diagnostics ${BX_ARR} Speed test ${BX_ARR} Hold a listener"
    say ""
    confirm_yes "start?" || return 0

    local td="" tu="" pd="" pu=""
    if [ -n "$tun_target" ]; then
        say ""
        head2 "Through the tunnel"
        say ""
        speed_one "$tun_target" "$tun_port" && { td="$SPEED_DOWN"; tu="$SPEED_UP"; }
    fi
    if [ -n "$pub" ]; then
        say ""
        head2 "The raw path"
        say ""
        speed_one "$pub" "$IPERF_PORT" && { pd="$SPEED_DOWN"; pu="$SPEED_UP"; }
    fi

    speed_report "$td" "$tu" "$pd" "$pu"
}

# The result, and what it means - which is the part a column of iperf output
# does not tell you.
speed_report() {
    local td="$1" tu="$2" pd="$3" pu="$4"
    banner
    head2 "Result: $PICKED"
    say ""

    if [ -n "$td$tu" ]; then
        panel "through the tunnel"
        field "Download" "${td:-not measured}"
        field "Upload" "${tu:-not measured}"
        panel_end
    fi
    if [ -n "$pd$pu" ]; then
        say ""
        panel "the raw path, for comparison"
        field "Download" "${pd:-not measured}"
        field "Upload" "${pu:-not measured}"
        panel_end
    fi

    # The comparison is the whole point. A number on its own is not a verdict.
    if [ -n "$td" ] && [ -n "$pd" ]; then
        local t p pct
        t="$(mbits "$td")"; p="$(mbits "$pd")"
        if [ "$p" -gt 0 ]; then
            pct=$((t * 100 / p))
            say ""
            if [ "$pct" -ge 80 ]; then
                ok "the tunnel is carrying ${pct}% of what the path can - that is as good as this gets"
            elif [ "$pct" -ge 50 ]; then
                warn "the tunnel is carrying ${pct}% of what the path can"
                dim "some loss is the cost of a tunnel; this much is worth a look"
                dim "try a larger window: Manage ${BX_ARR} $PICKED ${BX_ARR} Tuning ${BX_ARR} Profile"
            else
                fail "the tunnel is carrying only ${pct}% of what the path can"
                dim "the path is fine, so this is the tunnel - check the MTU first,"
                dim "then the window, then try another transport"
                dim "Diagnostics ${BX_ARR} Find the MTU"
            fi
        fi
    elif [ -n "$td" ]; then
        say ""
        dim "Run it against the raw path too - the same number means something"
        dim "quite different on a route that carries 100 Mbit than on one that"
        dim "carries 500, and only the pair tells you which you have."
    fi

    say ""
    dim "Numbers move with the hour on this route. Take each of them more than"
    dim "once before deciding anything."
    pause
}

# ---------------------------------------------------------------------------
# benchmarking the server itself
#
# A different question again: not the link, but the machine. Slow disk or a
# throttled CPU shows up as a tunnel that cannot keep up, and no amount of
# tuning fixes a server that is the bottleneck.
#
# This runs a third-party script from the internet, which is worth being
# plain about: the address is on the screen before anything runs, and nothing
# runs until you agree to it.
# ---------------------------------------------------------------------------

BENCH_URL="https://raw.githubusercontent.com/teddysun/across/master/bench.sh"

bench_menu() {
    banner
    head2 "Benchmark & Speedtest"
    say ""
    dim "CPU, disk, and a real speedtest against public servers. Says whether"
    dim "the machine itself is the bottleneck - which no tunnel setting fixes."
    say ""
    dim "This is the machine on its own. For the link between your two servers,"
    dim "use iperf3 instead - that is the number your users get."
    say ""
    warn "this downloads and runs a script written by someone else"
    say ""
    dim "$BENCH_URL"
    say ""
    dim "It is the widely used bench.sh. Read it first if you would rather;"
    dim "nothing here runs until you say so."
    say ""
    confirm "download and run it?" || return 0

    have curl || have wget || { fail "neither curl nor wget is installed"; pause; return 0; }

    local tmp="/tmp/pingify-bench.$$"
    say ""
    if ! fetch "$BENCH_URL" "$tmp" 60; then
        fail "could not download it"
        dim "this server may not be able to reach that address"
        rm -f "$tmp"
        pause; return 0
    fi
    ok "downloaded $(wc -c < "$tmp" | tr -d ' ') bytes"
    say ""
    rule
    bash "$tmp" 2>&1 | sed 's/^/  /'
    rule
    rm -f "$tmp"
    say ""
    pause
}

# ---------------------------------------------------------------------------
# finding the MTU instead of guessing it
#
# Every tunnel wraps the packet it carries, so the packet it can carry is
# smaller than the one the path allows. Guess too high and every full-size
# packet is fragmented or silently dropped - which reads as "connects fine,
# then stalls on anything large", the hardest fault here to diagnose. Guess too
# low and every packet wastes room, forever.
#
# The right number is not a constant. It is:
#
#     path MTU  -  what this transport wraps it in
#
# and the path MTU is a property of the route between these two servers today.
# Some paths carry 1500, plenty of Iranian routes carry less because they are
# themselves inside somebody else's tunnel. So it is measured, not assumed.
#
# The measurement is a ping with "do not fragment" set: if the packet is too
# big for any hop it is dropped rather than split, so the largest size that
# still gets an answer is the path MTU. Binary search finds it in ~10 pings.
# ---------------------------------------------------------------------------

# What each transport adds to every packet it carries, in bytes.
#
#   GRE   outer IP 20 + GRE 4 + our derived key 4                 = 28
#   AWG   outer IP 20 + UDP 8 + WireGuard 16 + Poly1305 tag 16    = 60
#         plus the junk AmneziaWG pads a handshake with, so more headroom
#   ICMP  outer IP 20 + ICMP 8 + our tag 4 + ARQ nonce 4 + hdr 16 = 52
#         plus the braid record header and the GCM tag it rides in
transport_overhead() {
    case "${1:-$T_TRANSPORT}" in
        gre)  printf '28' ;;
        awg)  printf '80' ;;   # 60 measured + 20 spare for the padding
        icmp) printf '80' ;;   # 52 measured + the braid frame around it
        *)    printf '40' ;;
    esac
}

# path_mtu HOST - the largest packet that reaches HOST without being fragmented,
# or nothing when the path will not answer at all.
#
# ping -M do sets DF; -s is the ICMP payload, so the packet on the wire is that
# plus 8 bytes of ICMP and 20 of IP.
path_mtu() {
    local host="$1" lo=576 hi=1500 mid payload best=0
    have ping || return 1

    # If the smallest size does not come back, nothing here is measurable -
    # the far end is not answering pings at all, which is its own answer.
    if ! ping -M do -s $((lo - 28)) -c1 -W2 -n "$host" >/dev/null 2>&1; then
        return 1
    fi
    best="$lo"

    while [ "$lo" -le "$hi" ]; do
        mid=$(((lo + hi) / 2))
        payload=$((mid - 28))
        if ping -M do -s "$payload" -c1 -W2 -n "$host" >/dev/null 2>&1; then
            best="$mid"
            lo=$((mid + 1))
        else
            hi=$((mid - 1))
        fi
    done
    printf '%s' "$best"
}

# mtu_menu - measure the path this tunnel rides on and say what its MTU should
# be. Offers to write it, because a number nobody applies is a number nobody
# uses.
mtu_menu() {
    pick_tunnel || return 0
    cfg_load "$PICKED" || return 0

    banner
    head2 "MTU: $PICKED"
    say ""
    if ! cfg_needs_link; then
        dim "This tunnel carries ports, not packets - it has no MTU of its own."
        dim "The connections inside it use whatever the two servers negotiate."
        say ""
        dim "Only TUN-ICMP, TUN-GRE and TUN-AWG have a device to set this on."
        pause
        return 0
    fi

    # The end that accepts is told nothing about the other server - there is
    # no connect line in its config, because it does not dial. But the running
    # tunnel knows who arrived, so ask it.
    local peer="$T_PEER_IP"
    if [ -z "$peer" ]; then
        peer="$(status_peer "$PICKED")"
    fi
    if [ -z "$peer" ]; then
        fail "this end does not know the other server's address"
        dim "it accepts rather than dials, so nothing in its config names the"
        dim "far side - and the tunnel is not up to be asked either"
        say ""
        dim "start it, or measure from the other server, which does know"
        pause
        return 0
    fi

    field "Transport" "$(transport_label "$T_TRANSPORT")"
    field "Measuring to" "$(addr_tint "$peer")"
    field "Set now" "$T_TUNMTU"
    say ""
    dim "Sends pings that may not be fragmented, largest first, until one comes"
    dim "back. Takes a few seconds."
    say ""

    local pmtu
    pmtu="$(path_mtu "$peer")" || {
        fail "the path would not answer a single ping"
        dim "either $peer is not reachable, or it is set to ignore ICMP -"
        dim "which the Blocking switch does, and the other server may have it on"
        say ""
        dim "turn it off there for a moment, measure, and turn it back on"
        pause
        return 0
    }

    local over want
    over="$(transport_overhead "$T_TRANSPORT")"
    want=$((pmtu - over))

    say ""
    panel "measured"
    field "Path" "$pmtu bytes"
    field "Wrapping" "$over bytes, $(transport_label "$T_TRANSPORT")"
    field "Tunnel MTU" "$want bytes"
    panel_end
    say ""

    if [ "$pmtu" -lt 1500 ]; then
        warn "the path carries less than a full 1500-byte packet"
        dim "normal on a route that is itself inside another tunnel, and exactly"
        dim "why this is worth measuring rather than assuming"
        say ""
    fi

    if [ "$want" = "$T_TUNMTU" ]; then
        ok "the MTU is already right"
        pause
        return 0
    fi

    if [ "$want" -gt "$T_TUNMTU" ]; then
        dim "Raising it means fewer packets for the same bytes."
    else
        warn "the current $T_TUNMTU is larger than this path can carry"
        dim "every full-size packet is being fragmented or dropped, which is"
        dim "what makes a tunnel connect and then stall on anything large"
    fi
    say ""
    confirm_yes "set the MTU to $want?" || return 0

    local f; f="$(cfg_file "$PICKED")"
    cp -f "$f" "$f.bak"
    sed -i "s#^mtu .*#mtu              = $want#" "$f"
    rm -f "$f.bak"
    say ""
    ok "set to $want"
    dim "set the same on the other server - the smaller of the two is what the"
    dim "link actually gets, so leaving one high wastes the measurement"
    say ""
    if confirm_yes "restart $PICKED now?"; then
        systemctl restart "pingify@$PICKED" >/dev/null 2>&1
        ok "restarted"
    fi
    pause
}

# ---------------------------------------------------------------------------
# update / remove
# ---------------------------------------------------------------------------

RAW_BASE="https://raw.githubusercontent.com/GreatTeejay/Pingify/main"

restart_all() {
    local n any=0
    for n in $(tunnel_names); do any=1; systemctl restart "pingify@$n"; done
    [ "$any" = "1" ] && ok "$1; every tunnel was restarted" || ok "$1"
}

# The script and the core share a config format, so they have to move
# together. Updating one alone is how a machine ends up with two versions of
# Pingify on it that refuse to work with each other.
update_pingify() {
    banner
    head2 "Update Pingify"
    if ! self_update; then pause; return 1; fi
    say ""
    info "restarting with the new version to bring the core along"
    sleep 1
    exec "$SELF_BIN"
}

self_update() {
    say ""
    info "fetching the latest Pingify from GitHub"
    local tmp="/tmp/pingify.new"

    # From the release, not from the branch. The two are not the same thing at
    # the same moment: a push to main changes the raw file instantly, while the
    # release that carries the matching core is built afterwards and appears a
    # few minutes later. Anyone updating inside that window took a new script
    # and an old core, and then read "core does not match the script" on their
    # own screen - which is a fault this tool invented for itself.
    #
    # The release carries both, so taking both from it means they cannot
    # disagree. The branch stays as a fallback for a release that has not
    # published yet.
    if ! fetch "$(release_base)/Pingify.sh" "$tmp" 60; then
        warn "the latest release did not answer; trying the branch"
        if ! fetch "$RAW_BASE/Pingify.sh" "$tmp" 60; then
            fail "could not reach GitHub"
            dim "on an Iranian server this often fails; update from the Kharej box"
            dim "and copy the file across instead."
            return 1
        fi
    fi
    if ! bash -n "$tmp" 2>/dev/null; then
        fail "the downloaded file is not valid, refusing to install it"
        rm -f "$tmp"; return 1
    fi
    local newver; newver="$(grep -m1 '^PINGIFY_VERSION=' "$tmp" | cut -d'"' -f2)"
    install -m 0755 "$tmp" "$SELF_BIN"
    rm -f "$tmp"
    ok "Pingify updated to ${newver:-unknown}"
}

remove_menu() {
    banner
    head2 "Remove"
    item 1 "Remove the core only" "tunnels and configs stay"
    item 2 "Remove every tunnel" "configs and services, core stays"
    item 3 "Full uninstall" "every tunnel, unit, rule and file it wrote"
    item 0 "Back"
    say ""
    local c=""
    ask c "select"
    case "$c" in
        1)  say ""
            confirm "remove $CORE_BIN?" || return
            local n
            for n in $(tunnel_names); do systemctl stop "pingify@$n" >/dev/null 2>&1; done
            rm -f "$CORE_BIN"
            rm -rf "$SRC_DIR"
            ok "core removed; the next run downloads it again"
            pause ;;
        2)  say ""
            confirm "delete every tunnel on this server?" || return
            local n
            for n in $(tunnel_names); do
                # A kernel tunnel leaves an interface and a unit file of its
                # own behind; read it before the config goes.
                if cfg_load "$n" >/dev/null 2>&1 && kernel_transport; then
                    ip link del "$T_TUNIF" 2>/dev/null
                    rm -f "$UNIT_DIR/pingify@$n.service" "$(awg_conf_path "$T_TUNIF")"
                fi
                systemctl disable --now "pingify@$n" >/dev/null 2>&1
                systemctl disable --now "pingify-recycle@$n.timer" >/dev/null 2>&1
                rm -f "$UNIT_DIR/pingify-recycle@$n.timer" "$(cfg_file "$n")"
            done
            systemctl daemon-reload
            ok "all tunnels removed"
            pause ;;
        3)  full_uninstall ;;
        0|"") return ;;
    esac
}

# Everything this tool ever wrote, in one pass. The firewall rules matter
# most: a DNAT rule pointing at an address that no longer exists swallows
# every packet for that port silently, and an uninstall that leaves one
# behind hands the next person a server that is broken in a way nothing on
# it explains.
full_uninstall() {
    say ""
    warn "this removes, on this server:"
    say ""
    dim "    every tunnel and its config in $CFG_DIR"
    dim "    the systemd units, timers and the boot-time firewall unit"
    dim "    the forwarding rules (iptables chains PINGIFY_NAT, PINGIFY_POST)"
    dim "    the blocking rules (chains PINGIFY_IN, PINGIFY_OUT, PINGIFY_FWD)"
    dim "    the ICMP block in /etc/sysctl.d and the speedtest lines in /etc/hosts"
    dim "    every GRE and AmneziaWG interface it created"
    dim "    the core binary, the state directory and this script"
    say ""
    confirm "go ahead?" || return

    local n
    for n in $(tunnel_names); do
        # The kernel tunnels hold an interface that outlives their unit if
        # the stop never ran, and a unit file that is not the shared template.
        if cfg_load "$n" >/dev/null 2>&1 && kernel_transport; then
            ip link del "$T_TUNIF" 2>/dev/null
            rm -f "$UNIT_DIR/pingify@$n.service"
        fi
        systemctl disable --now "pingify@$n" >/dev/null 2>&1
        systemctl disable --now "pingify-recycle@$n.timer" >/dev/null 2>&1
    done
    systemctl disable --now pingify-health.timer >/dev/null 2>&1

    # both sets of chains, unhooked from the built-in ones and deleted
    remove_blocking
    have iptables && nat_drop_chains

    rm -f "$UNIT_DIR"/pingify@.service "$UNIT_DIR"/pingify-health.service \
          "$UNIT_DIR"/pingify-health.timer "$UNIT_DIR"/pingify-recycle@*.service \
          "$UNIT_DIR"/pingify-recycle@*.timer "$UNIT_DIR"/pingify-firewall.service
    systemctl daemon-reload

    if confirm "also revert the sysctl and file-limit tuning?"; then revert_tuning; fi
    rm -rf "$CFG_DIR" "$STATE_DIR" "$SRC_DIR"
    rm -f "$CORE_BIN"

    say ""
    ok "every rule and unit is gone; nothing of Pingify is left running"
    dim "check for yourself:  iptables -t nat -S | grep PINGIFY   (should print nothing)"
    say ""
    ok "removing the manager itself now"
    rm -f "$SELF_BIN"
    say ""
    exit 0
}

# ---------------------------------------------------------------------------
# diagnostics
#
# One command that answers "is this thing working, and if not, which part is
# broken" - in the order the failures actually happen, so the first red line
# is the one to fix.
# ---------------------------------------------------------------------------

DIAG_BAD=0

check_pass() { printf '  %s%s%s %s\n' "$C_GRN" "$MK_OK" "$C_OFF" "$1"; }
check_fail() { printf '  %s%s%s %s\n' "$C_RED" "$MK_NO" "$C_OFF" "$1"; DIAG_BAD=$((DIAG_BAD + 1)); }
check_warn() { printf '  %s%s%s %s\n' "$C_YEL" "$MK_WARN" "$C_OFF" "$1"; }
check_note() { printf '      %s%s%s\n' "$C_DIM" "$1" "$C_OFF"; }

tcp_probe() {
    timeout 5 bash -c ": < /dev/tcp/$1/$2" 2>/dev/null
}

diag_tunnel() {
    local name="$1" f
    f="$(cfg_file "$name")"
    cfg_load "$name" || { check_fail "$name: no config"; return; }

    printf '\n  %s%s%s\n' "$C_B" "$name" "$C_OFF"

    # 1. the config the core will actually read
    if "$CORE_BIN" -c "$f" -check >/dev/null 2>&1; then
        check_pass "config is valid"
    else
        check_fail "the core rejects this config"
        "$CORE_BIN" -c "$f" -check 2>&1 | sed 's/^/      /'
        return
    fi

    # 2. the service
    case "$(svc_state "$name")" in
        active)   check_pass "service is running" ;;
        stopped)  check_fail "service is stopped"; check_note "start it from Manage tunnels"; return ;;
        *)        check_fail "service is not enabled"; return ;;
    esac

    # 3. the link itself, straight from the core
    local brief state up total rtt
    brief="$("$CORE_BIN" -status "$T_STATUS" -brief 2>/dev/null)"
    set -- $brief
    state="${1:-down}"; up="${2:-0}"; total="${3:-0}"; rtt="${4:-0}"
    if [ "$state" = "up" ]; then
        check_pass "link is up - $up of $total connections, $(rtt_tint "${rtt}ms")"
        [ "$up" != "$total" ] && check_warn "some connections are still down"
    else
        check_fail "no connection to the other server"
    fi

    # 4. the path, so a down link points at a cause
    cfg_endpoints
    if [ -n "$CFG_CONNECT" ]; then
        local host="${CFG_CONNECT%:*}" port="${CFG_CONNECT##*:}"
        if [ "$T_TRANSPORT" = "icmp" ]; then
            host="$CFG_CONNECT"
            if have ping && ping -c 2 -W 2 "$host" >/dev/null 2>&1; then
                check_pass "$host answers a ping - the ICMP path is open"
            else
                check_fail "$host does not answer a ping"
                check_note "an ICMP tunnel cannot work if ping does not get through"
            fi
            return
        fi
        if tcp_probe "$host" "$port"; then
            check_pass "port $port on $host accepts connections"
        else
            check_fail "cannot reach $host:$port"
            check_note "is the other server running, and is the port open there?"
        fi
    else
        local port="${CFG_LISTEN##*:}"
        if [ "$T_TRANSPORT" = "icmp" ]; then
            check_pass "ICMP needs no port to be open here"
            return
        fi
        if ss -Hltn "sport = :$port" 2>/dev/null | grep -q .; then
            check_pass "listening on port $port"
            [ "$state" = "up" ] || check_note "open $port in your firewall and check the other server"
        else
            check_fail "nothing is listening on port $port"
        fi
    fi

    # 5. the ports clients are told to use
    if [ "$T_MODE" = "forward" ] && [ -n "$T_FORWARDS" ]; then
        local spec p missing=""
        for spec in $(printf '%s' "$T_FORWARDS" | tr -d '"' | tr ',' ' '); do
            p="${spec%%=*}"; p="${p##*:}"; p="${p%%-*}"
            case "$p" in "" | *[!0-9]*) continue ;; esac
            ss -Hltn "sport = :$p" 2>/dev/null | grep -q . || missing="$missing $p"
        done
        if [ -n "$missing" ]; then
            check_fail "not listening on:$missing"
        else
            check_pass "all forwarded ports are open"
        fi
    fi
}

diag_full() {
    banner
    head2 "Full check"
    DIAG_BAD=0

    # --- the machine ------------------------------------------------------
    printf '  %s%s%s\n' "$C_B" "This server" "$C_OFF"
    [ -x "$CORE_BIN" ] && check_pass "core $(core_version)" || check_fail "the core is not installed"

    if have timedatectl && timedatectl show -p NTPSynchronized --value 2>/dev/null | grep -q yes; then
        check_pass "clock is synchronised"
    else
        check_warn "clock may be off"
        check_note "the handshake rejects a difference over 3 minutes - see Optimize"
    fi

    if [ "$(watchdog_state)" = "on" ]; then
        check_pass "watchdog is on"
    else
        check_warn "watchdog is off - a dead tunnel will not be restarted"
    fi

    # --- each tunnel ------------------------------------------------------
    local names; names="$(tunnel_names)"
    if [ -z "$names" ]; then
        printf '\n'
        check_warn "no tunnels configured"
    else
        local n
        for n in $names; do diag_tunnel "$n"; done
    fi

    printf '\n'
    if [ "$DIAG_BAD" = "0" ]; then
        ok "everything checks out"
    else
        fail "$DIAG_BAD problem(s) above"
    fi
    pause
}

diagnostics_menu() {
    while :; do
        banner
        head2 "Diagnostics"
        group "Check"
        item 1 "Full check" "config, service, link, path, ports"
        item 2 "Live log" "follow a tunnel as it runs"
        group "Measure"
        item 3 "iperf3" "real bandwidth between your two servers"
        item 4 "Benchmark & Speedtest" "this machine: cpu, disk, and a real speedtest"
        item 5 "Find the MTU" "measure the path instead of guessing at it"
        item 6 "Ping the other end" "raw latency, outside the tunnel"
        group "Show"
        item 7 "Forwarding rules" "the iptables rules Pingify installed, if any"
        item 8 "System summary"
        say ""
        item 0 "Back"
        say ""
        local c=""
        ask c "select"
        case "$c" in
            1) diag_full ;;
            2) if pick_tunnel; then live_log "$PICKED"; fi ;;
            3) speed_menu ;;
            4) bench_menu ;;
            5) mtu_menu ;;
            6) diag_ping ;;
            7) show_nat; pause ;;
            8) diag_system ;;
            0 | "") return ;;
        esac
    done
}

diag_ping() {
    pick_tunnel || return
    cfg_load "$PICKED" || return
    local host=""
    cfg_endpoints
    [ -n "$CFG_CONNECT" ] && host="${CFG_CONNECT%:*}"
    # The end that accepts has no configured peer, but the running tunnel
    # knows who connected to it - so ask that before asking a person.
    [ -n "$host" ] || host="$(status_peer "$PICKED")"
    say ""
    if [ -z "$host" ]; then
        dim "this server waits for the other one, and nothing has connected yet -"
        dim "so neither its config nor the tunnel knows the far address"
        say ""
        ask host "address to ping"
    fi
    [ -n "$host" ] || return
    say ""
    if have ping; then
        ping -c 5 -W 2 "$host" 2>&1 | sed 's/^/    /'
    else
        warn "ping is not installed"
    fi
    pause
}

diag_system() {
    banner
    head2 "System"
    panel "MACHINE"
    field "OS" "$OS_PRETTY"
    field "Kernel" "$(uname -r)"
    field "Arch" "$ARCH"
    field "CPU" "$(nproc) cores"
    field "Memory" "$(free -h 2>/dev/null | awk '/^Mem:/{print $3" of "$2}')"
    panel_end
    panel "NETWORK"
    field "Public IP" "$SRV_IP"
    field "Congestion" "$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null)"
    field "Qdisc" "$(sysctl -n net.core.default_qdisc 2>/dev/null)"
    field "Blocking" "$(block_summary)"
    field "Open files" "$(ulimit -n)"
    panel_end
    panel "PINGIFY"
    field "Script" "$PINGIFY_VERSION"
    field "Core" "$(core_version)"
    field "Directory" "$BASE_DIR"
    field "Time" "$(date -u '+%Y-%m-%d %H:%M UTC')"
    panel_end
    pause
}

# ---------------------------------------------------------------------------
# embedded core sources
#
# build.sh drops the contents of core/*.go in here. Shipping the source rather
# than a binary means one file works on amd64 and arm64 alike, and there is
# never a release download to be blocked.
# ---------------------------------------------------------------------------

write_core_sources() {
    local d="$1"
    mkdir -p "$d" || return 1
    cat > "$d/arq.go" <<'PINGIFY_SRC_EOF'
package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"encoding/binary"
	"errors"
	"io"
	"net"
	"sync"
	"time"
)

// ---------------------------------------------------------------------------
// ARQ - a reliable ordered stream over an unreliable datagram carrier
//
// The braid layer above needs what TCP gives it: bytes arriving once, in
// order. ICMP echo gives none of that, so this sits in between and supplies
// it - sequence numbers, cumulative acknowledgements, retransmission on a
// measured timeout, fast retransmit on duplicate acks, and a send window.
//
// It deliberately knows nothing about ICMP. It takes a function that puts one
// datagram on the wire and a stream of datagrams coming back, which is what
// makes it testable against a link that loses, reorders and duplicates on
// purpose rather than only against a real network on a good day.
//
// Wire layout of one datagram:
//
//	[4]  nonce      random, in the clear, keys the mask below
//	[16] header     masked with AES(k, nonce)
//	     [4] session
//	     [1] carrier
//	     [1] flags
//	     [4] seq
//	     [4] ack
//	     [2] length
//	[n]  payload    already encrypted by the layer above
//
// Masking the header costs one AES block per datagram and leaves nothing
// constant for a filter to match on.
// ---------------------------------------------------------------------------

const (
	arqNonce = 4
	arqHdr   = 16
	arqOver  = arqNonce + arqHdr
	// The floor and the ceiling on segments in flight. The window itself is
	// per connection now, sized from the tunnel's own window_kb - it used to
	// be this constant, 64, and nothing could reach it.
	//
	// 64 segments of 1200 bytes is 76.8 KB in flight, and a stream is pinned
	// to one carrier for its life. At 75 ms that is 8 Mbit/s for a single
	// download, whatever the carrier count says - which is why an ICMP tunnel
	// measured a fraction of what the same servers did over TCP, and why one
	// video stalled while the tunnel looked idle.
	arqWinMin = 32
	arqWinMax = 4096
	// Where every version before this one sat, and so the only width an
	// un-updated peer is known to accept.
	arqWinStart = 64

	flagData = 1 << 0
	flagFin  = 1 << 1
	flagRst  = 1 << 2
)

var (
	errARQClosed = errors.New("arq: connection closed")
	errARQReset  = errors.New("arq: reset by peer")
)

type arqHeader struct {
	session uint32
	carrier uint8
	flags   uint8
	seq     uint32
	ack     uint32
	length  uint16
}

func (h *arqHeader) put(dst []byte) {
	binary.BigEndian.PutUint32(dst[0:4], h.session)
	dst[4] = h.carrier
	dst[5] = h.flags
	binary.BigEndian.PutUint32(dst[6:10], h.seq)
	binary.BigEndian.PutUint32(dst[10:14], h.ack)
	binary.BigEndian.PutUint16(dst[14:16], h.length)
}

func (h *arqHeader) get(src []byte) {
	h.session = binary.BigEndian.Uint32(src[0:4])
	h.carrier = src[4]
	h.flags = src[5]
	h.seq = binary.BigEndian.Uint32(src[6:10])
	h.ack = binary.BigEndian.Uint32(src[10:14])
	h.length = binary.BigEndian.Uint16(src[14:16])
}

// maskHeader XORs the 16 header bytes with an AES block keyed by the nonce.
func maskHeader(blk cipher.Block, nonce, hdr []byte) {
	var in, ks [16]byte
	copy(in[:], nonce)
	blk.Encrypt(ks[:], in[:])
	for i := 0; i < arqHdr; i++ {
		hdr[i] ^= ks[i]
	}
}

// segment is one unacknowledged piece of the outgoing stream.
type segment struct {
	seq     uint32
	data    []byte
	sentAt  time.Time
	retries int
}

// arqConn presents a net.Conn over datagrams.
type arqConn struct {
	session uint32
	carrier uint8
	mask    cipher.Block
	maxPay  int
	// Segments allowed in flight. A stream is pinned to one carrier, so this
	// alone decides how fast a single download can go: window * maxPay / RTT.
	//
	// It starts at arqWinStart and grows towards maxWindow while the peer
	// keeps acknowledging, and halves when a segment has to be sent twice.
	// Two reasons, and both matter:
	//
	//   A peer that has not been updated yet only accepts what the old fixed
	//   window allowed. Starting there means the tunnel comes up against any
	//   version, and widens only once this peer has shown it keeps up.
	//
	//   A window past what the path can carry does not go faster, it queues -
	//   and a queue is the stalling video and the swinging ping it was meant
	//   to cure. Backing off on loss is what holds it near the path's own
	//   capacity instead of above it.
	window    int
	maxWindow int
	send      func([]byte) error
	remote    net.Addr

	mu   sync.Mutex
	cond *sync.Cond

	// outbound
	sndNext uint32
	sndUna  uint32
	sndBuf  map[uint32]*segment
	pending []byte // bytes not yet cut into a segment

	// inbound
	rcvNext uint32
	rcvBuf  map[uint32][]byte
	inbox   []byte

	// round-trip estimate, Jacobson/Karels
	srtt, rttvar, rto time.Duration

	lastAck  uint32
	dupAcks  int
	needAck  bool
	peerFin  bool
	sentFin  bool
	closed   bool
	err      error
	done     chan struct{}
	deadline time.Time

	// How many times one segment is resent before the carrier is declared
	// dead. With the doubling backoff below, twelve works out at roughly
	// half a minute - long enough to ride out a blip, short enough that the
	// pool starts a fresh carrier while anyone is still watching.
	maxRetries int
}

// arqWindowFor turns the tunnel's window_kb into segments in flight, which is
// the unit the ARQ actually counts in. Sized the same way the TCP transport
// sizes its credit window, so the two answer to the same setting.
func arqWindowFor(windowKB, maxPayload int) int {
	if windowKB <= 0 || maxPayload <= 0 {
		return arqWinMin
	}
	n := windowKB * 1024 / maxPayload
	if n < arqWinMin {
		return arqWinMin
	}
	if n > arqWinMax {
		return arqWinMax
	}
	return n
}

func newARQ(session uint32, carrier uint8, psk []byte, maxPayload, window int, send func([]byte) error) *arqConn {
	k := hkdfExpand(hkdfExtract([]byte("pingify/v3 icmp"), psk), []byte("arq header"), 32)
	blk, err := aes.NewCipher(k)
	if err != nil {
		panic(err)
	}
	c := &arqConn{
		session:    session,
		carrier:    carrier,
		mask:       blk,
		maxPay:     maxPayload,
		window:     arqWinStart,
		maxWindow:  window,
		send:       send,
		sndBuf:     make(map[uint32]*segment),
		rcvBuf:     make(map[uint32][]byte),
		rto:        500 * time.Millisecond,
		done:       make(chan struct{}),
		maxRetries: 12,
	}
	c.cond = sync.NewCond(&c.mu)
	go c.timerLoop()
	return c
}

// ---------------------------------------------------------------------------
// net.Conn
// ---------------------------------------------------------------------------

func (c *arqConn) Read(p []byte) (int, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	for len(c.inbox) == 0 {
		if c.err != nil {
			return 0, c.err
		}
		if c.peerFin {
			return 0, io.EOF
		}
		if c.closed {
			return 0, errARQClosed
		}
		c.cond.Wait()
	}
	n := copy(p, c.inbox)
	c.inbox = c.inbox[n:]
	return n, nil
}

func (c *arqConn) Write(p []byte) (int, error) {
	total := 0
	for len(p) > 0 {
		c.mu.Lock()
		for len(c.sndBuf) >= c.window {
			if c.closed || c.err != nil {
				e := c.err
				if e == nil {
					e = errARQClosed
				}
				c.mu.Unlock()
				return total, e
			}
			c.cond.Wait()
		}
		if c.closed || c.err != nil {
			e := c.err
			if e == nil {
				e = errARQClosed
			}
			c.mu.Unlock()
			return total, e
		}
		n := len(p)
		if n > c.maxPay {
			n = c.maxPay
		}
		seg := &segment{seq: c.sndNext, data: append([]byte(nil), p[:n]...)}
		c.sndBuf[seg.seq] = seg
		c.sndNext++
		c.emit(seg, flagData)
		c.mu.Unlock()
		p = p[n:]
		total += n
	}
	return total, nil
}

func (c *arqConn) Close() error {
	c.mu.Lock()
	if c.closed {
		c.mu.Unlock()
		return nil
	}
	c.closed = true
	if !c.sentFin {
		c.sentFin = true
		c.emit(nil, flagFin)
	}
	close(c.done)
	c.cond.Broadcast()
	c.mu.Unlock()
	return nil
}

func (c *arqConn) LocalAddr() net.Addr  { return c.remote }
func (c *arqConn) RemoteAddr() net.Addr { return c.remote }

// The braid layer sets deadlines to detect a wedged carrier. The keepalive and
// retransmit machinery already covers that, so these are accepted and ignored
// rather than pretended not to exist.
func (c *arqConn) SetDeadline(t time.Time) error      { return nil }
func (c *arqConn) SetReadDeadline(t time.Time) error  { return nil }
func (c *arqConn) SetWriteDeadline(t time.Time) error { return nil }

// ---------------------------------------------------------------------------
// sending
// ---------------------------------------------------------------------------

// emit builds and sends one datagram. Caller holds the lock, and the send
// callback runs under it - fine for a datagram socket, which does not block,
// but it means the callback must not reach back into this connection.
func (c *arqConn) emit(seg *segment, flags uint8) {
	var payload []byte
	h := arqHeader{session: c.session, carrier: c.carrier, flags: flags, ack: c.rcvNext}
	if seg != nil {
		h.seq = seg.seq
		h.length = uint16(len(seg.data))
		payload = seg.data
		seg.sentAt = time.Now()
	}
	buf := make([]byte, arqOver+len(payload))
	if _, err := rand.Read(buf[:arqNonce]); err != nil {
		return
	}
	h.put(buf[arqNonce:arqOver])
	maskHeader(c.mask, buf[:arqNonce], buf[arqNonce:arqOver])
	copy(buf[arqOver:], payload)
	c.needAck = false
	c.send(buf)
}

// ackOnly sends a bare acknowledgement. Caller holds the lock.
func (c *arqConn) ackOnly() { c.emit(nil, 0) }

// ---------------------------------------------------------------------------
// receiving
// ---------------------------------------------------------------------------

// onDatagram feeds one received datagram in. It never blocks, so the socket
// reader is never held up by a slow consumer.
func (c *arqConn) onDatagram(buf []byte) {
	if len(buf) < arqOver {
		return
	}
	hdr := make([]byte, arqHdr)
	copy(hdr, buf[arqNonce:arqOver])
	maskHeader(c.mask, buf[:arqNonce], hdr)
	var h arqHeader
	h.get(hdr)
	if h.session != c.session || h.carrier != c.carrier {
		return
	}
	if int(h.length) > len(buf)-arqOver {
		return
	}
	payload := buf[arqOver : arqOver+int(h.length)]

	c.mu.Lock()
	defer c.mu.Unlock()

	if h.flags&flagRst != 0 {
		c.fail(errARQReset)
		return
	}

	c.processAck(h.ack)

	if h.flags&flagData != 0 && h.length > 0 {
		c.deliver(h.seq, payload)
		c.needAck = true
	}
	if h.flags&flagFin != 0 {
		c.peerFin = true
		c.cond.Broadcast()
	}
}

// grow widens the window by one segment for each round of clean acks, up to
// what the tunnel was configured for. Additive on the way up, halved on the
// way down - the shape that settles near a path's capacity rather than
// oscillating around it.
func (c *arqConn) grow() {
	if c.window < c.maxWindow {
		c.window++
	}
}

// shrink halves the window when a segment had to be sent twice, which is the
// path saying it is carrying more than it can.
func (c *arqConn) shrink() {
	c.window /= 2
	if c.window < arqWinMin {
		c.window = arqWinMin
	}
	c.cond.Broadcast()
}

// processAck retires everything the peer has confirmed. Caller holds the lock.
func (c *arqConn) processAck(ack uint32) {
	if ack == c.lastAck {
		c.dupAcks++
		// Three duplicates mean the segment after the ack is almost certainly
		// gone; resend it now rather than waiting out the timer.
		if c.dupAcks == 3 {
			if seg, ok := c.sndBuf[ack]; ok {
				c.emit(seg, flagData)
				seg.retries++
				c.shrink()
			}
		}
		return
	}
	c.dupAcks = 0
	c.lastAck = ack

	for s := c.sndUna; s < ack; s++ {
		if seg, ok := c.sndBuf[s]; ok {
			// Karn's rule: a retransmitted segment says nothing about the RTT.
			if seg.retries == 0 {
				c.sampleRTT(time.Since(seg.sentAt))
			}
			delete(c.sndBuf, s)
		}
	}
	if ack > c.sndUna {
		c.sndUna = ack
		// Fresh ground acknowledged with nothing resent: the peer is keeping
		// up and is willing to take at least this much, so widen a little.
		c.grow()
	}
	c.cond.Broadcast()
}

// deliver puts a segment in order, buffering anything that arrives early.
// Caller holds the lock.
func (c *arqConn) deliver(seq uint32, payload []byte) {
	if seq < c.rcvNext {
		return // already had it; the ack was lost, not the data
	}
	// Bounded by what any peer is allowed to send, never by what this end
	// happens to be sending. Tying it to our own window made the receive
	// guard a wire parameter: an end with a wide window sent past what an end
	// with a narrow one would accept, every one of those segments was
	// dropped, the sender resent them until it gave up, and the carrier died.
	// Which is exactly what updating one server before the other did.
	if seq >= c.rcvNext+arqWinMax*2 {
		return // absurdly far ahead, drop rather than grow without bound
	}
	if _, dup := c.rcvBuf[seq]; dup {
		return
	}
	c.rcvBuf[seq] = append([]byte(nil), payload...)
	for {
		seg, ok := c.rcvBuf[c.rcvNext]
		if !ok {
			break
		}
		c.inbox = append(c.inbox, seg...)
		delete(c.rcvBuf, c.rcvNext)
		c.rcvNext++
	}
	c.cond.Broadcast()
}

func (c *arqConn) fail(err error) {
	if c.err == nil {
		c.err = err
	}
	c.cond.Broadcast()
}

// ---------------------------------------------------------------------------
// timers
// ---------------------------------------------------------------------------

// sampleRTT folds one measurement into the retransmit timeout, the way TCP
// does: smoothed average plus four mean deviations. Caller holds the lock.
func (c *arqConn) sampleRTT(m time.Duration) {
	if c.srtt == 0 {
		c.srtt = m
		c.rttvar = m / 2
	} else {
		d := c.srtt - m
		if d < 0 {
			d = -d
		}
		c.rttvar = (3*c.rttvar + d) / 4
		c.srtt = (7*c.srtt + m) / 8
	}
	c.rto = c.srtt + 4*c.rttvar
	if c.rto < 200*time.Millisecond {
		c.rto = 200 * time.Millisecond
	}
	if c.rto > 5*time.Second {
		c.rto = 5 * time.Second
	}
}

func (c *arqConn) timerLoop() {
	t := time.NewTicker(20 * time.Millisecond)
	defer t.Stop()
	idle := time.Now()
	for {
		select {
		case <-c.done:
			return
		case now := <-t.C:
			c.mu.Lock()
			if c.err != nil {
				c.mu.Unlock()
				return
			}
			// Anything past its timeout goes again, with the timeout doubled
			// so a dead path is not hammered.
			for _, seg := range c.sndBuf {
				if now.Sub(seg.sentAt) >= c.rto {
					seg.retries++
					c.shrink()
					if seg.retries > c.maxRetries {
						c.fail(errARQClosed)
						c.mu.Unlock()
						return
					}
					c.emit(seg, flagData)
					if c.rto < 5*time.Second {
						c.rto *= 2
					}
				}
			}
			if c.needAck {
				c.ackOnly()
			}
			// A quiet link still needs a heartbeat, both to keep any stateful
			// middlebox interested and to notice the peer going away.
			if len(c.sndBuf) == 0 && now.Sub(idle) > time.Second {
				c.ackOnly()
				idle = now
			}
			if len(c.sndBuf) > 0 {
				idle = now
			}
			c.mu.Unlock()
		}
	}
}
PINGIFY_SRC_EOF
    cat > "$d/config.go" <<'PINGIFY_SRC_EOF'
package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"strconv"
	"strings"
)

// ---------------------------------------------------------------------------
// configuration files
//
// TOML is what people expect for this kind of tool, so that is what Pingify
// writes. What it reads back is a deliberately small subset: bare `key = value`
// at the top level, one `[tun]` table, string arrays, integers and strings.
// Pingify generates these files, so a full TOML implementation would be a
// dependency bought for nothing - and a dependency is exactly what the offline
// build path cannot afford.
//
// JSON is still accepted so that configs written by 3.2 and earlier keep
// working without anyone having to convert them.
// ---------------------------------------------------------------------------

func loadConfig(path string) (*Config, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read config: %v", err)
	}
	var cfg Config
	if strings.HasPrefix(strings.TrimSpace(string(raw)), "{") {
		if err := json.Unmarshal(raw, &cfg); err != nil {
			return nil, fmt.Errorf("parse config: %v", err)
		}
		return &cfg, nil
	}
	if err := parseTOML(string(raw), &cfg); err != nil {
		return nil, fmt.Errorf("parse config: %v", err)
	}
	return &cfg, nil
}

func parseTOML(text string, c *Config) error {
	sc := bufio.NewScanner(strings.NewReader(text))
	sc.Buffer(make([]byte, 0, 64*1024), 1<<20)
	section := ""
	line := 0

	for sc.Scan() {
		line++
		s := stripComment(sc.Text())
		if s == "" {
			continue
		}
		if strings.HasPrefix(s, "[") {
			if !strings.HasSuffix(s, "]") {
				return fmt.Errorf("line %d: unterminated table header", line)
			}
			section = strings.Trim(s[1:len(s)-1], " \t\"")
			continue
		}
		eq := strings.Index(s, "=")
		if eq < 0 {
			return fmt.Errorf("line %d: expected key = value", line)
		}
		key := strings.TrimSpace(s[:eq])
		val := strings.TrimSpace(s[eq+1:])
		if err := assign(c, section, key, val); err != nil {
			return fmt.Errorf("line %d: %v", line, err)
		}
	}
	return sc.Err()
}

// stripComment removes a trailing # comment, leaving anything inside quotes
// alone so a value may contain a hash.
func stripComment(s string) string {
	inQ := false
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '"':
			inQ = !inQ
		case '#':
			if !inQ {
				return strings.TrimSpace(s[:i])
			}
		}
	}
	return strings.TrimSpace(s)
}

func unquote(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		if out, err := strconv.Unquote(s); err == nil {
			return out
		}
		return s[1 : len(s)-1]
	}
	return s
}

// parseArray reads ["a", "b"] into its elements.
func parseArray(s string) ([]string, error) {
	s = strings.TrimSpace(s)
	if !strings.HasPrefix(s, "[") || !strings.HasSuffix(s, "]") {
		return nil, fmt.Errorf("expected a [...] array")
	}
	body := strings.TrimSpace(s[1 : len(s)-1])
	if body == "" {
		return nil, nil
	}
	var out []string
	for _, part := range splitTop(body) {
		part = unquote(part)
		if part != "" {
			out = append(out, part)
		}
	}
	return out, nil
}

// splitTop splits on commas that are not inside quotes.
func splitTop(s string) []string {
	var out []string
	inQ, start := false, 0
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '"':
			inQ = !inQ
		case ',':
			if !inQ {
				out = append(out, s[start:i])
				start = i + 1
			}
		}
	}
	return append(out, s[start:])
}

func atoi(key, s string) (int, error) {
	// TOML allows 10_000 as a readability separator.
	n, err := strconv.Atoi(strings.ReplaceAll(strings.TrimSpace(s), "_", ""))
	if err != nil {
		return 0, fmt.Errorf("%s: %q is not a number", key, s)
	}
	return n, nil
}

// assign maps one key onto the Config. Sections group what belongs together;
// a key with no section is the flat layout Pingify wrote before 3.4 and is
// still accepted so an existing file keeps working.
func assign(c *Config, section, key, val string) error {
	var err error
	num := func(dst *int) error {
		n, e := atoi(key, val)
		if e == nil {
			*dst = n
		}
		return e
	}
	boolean := func(dst **bool) error {
		switch strings.ToLower(strings.TrimSpace(unquote(val))) {
		case "true", "yes", "on", "1":
			t := true
			*dst = &t
		case "false", "no", "off", "0":
			f := false
			*dst = &f
		default:
			return fmt.Errorf("%s must be true or false, got %q", key, val)
		}
		return nil
	}

	switch section {
	case "", "tunnel":
		switch key {
		case "name":
			c.Name = unquote(val)
		case "role":
			c.Role = unquote(val)
		case "mode":
			c.Mode = unquote(val)
		}
	}

	switch section {
	case "", "transport":
		switch key {
		case "type", "transport":
			c.Transport = unquote(val)
		case "listen":
			c.Listen = unquote(val)
		case "connect":
			c.Connect = unquote(val)
		case "carriers":
			err = num(&c.Carriers)
		case "keepalive_sec":
			err = num(&c.KeepaliveSec)
		case "dial_timeout_sec":
			err = num(&c.DialTimeout)
		case "obfuscate":
			err = boolean(&c.Obfuscate)
		}
	}

	switch section {
	case "", "security":
		switch key {
		case "token":
			c.Token = unquote(val)
		case "psk":
			c.PSK = unquote(val)
		}
	}

	switch section {
	case "", "forward":
		switch key {
		case "ports", "forwards":
			c.Forwards, err = parseArray(val)
		case "bind_addr":
			c.BindAddr = unquote(val)
		case "allow":
			c.Allow, err = parseArray(val)
		}
	}

	switch section {
	case "", "tuning":
		switch key {
		case "window_kb":
			err = num(&c.WindowKB)
		case "sndbuf_kb":
			err = num(&c.SndBufKB)
		case "rcvbuf_kb":
			err = num(&c.RcvBufKB)
		}
	}

	switch section {
	case "", "status":
		if key == "addr" || key == "status_addr" {
			c.StatusAddr = unquote(val)
		}
	}

	switch section {
	case "", "logging":
		if key == "level" || key == "log_level" {
			c.LogLevel = unquote(val)
		}
	}

	if section == "tun" {
		switch key {
		case "name":
			c.TUN.Name = unquote(val)
		case "local", "local_addr":
			c.TUN.Local = unquote(val)
		case "peer", "remote_addr":
			c.TUN.Peer = unquote(val)
		case "mtu":
			err = num(&c.TUN.MTU)
		}
	}

	// Anything unrecognised is ignored on purpose: a config written by a newer
	// Pingify should not stop an older core from starting.
	return err
}
PINGIFY_SRC_EOF
    cat > "$d/handshake_v2.go" <<'PINGIFY_SRC_EOF'
package main

import (
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"encoding/binary"
	"io"
	"net"
	"time"
)

// The plain handshake, byte for byte as v2.1.1 shipped it.
//
// v3 removed every constant from the wire so nothing could be fingerprinted:
// no magic, no version, a header XORed with a key-derived block, a variable
// amount of trailing padding, and masked frame lengths. On a real Iran<->Europe
// path that stream stopped carrying anything a few seconds after each carrier
// came up, in both directions, every time - while this one, with a four-byte
// magic in the clear, worked on the same two servers.
//
// Both are kept. Which one a tunnel speaks is [transport] obfuscate, and it has
// to match on the two ends. Off - this one - is the default, because a tunnel
// that carries no traffic protects nothing.
const (
	hs2Magic     = "PFY2"
	hs2Version   = 2
	hs2ClientLen = 4 + 1 + 1 + 2 + 8 + 16 + 32
	hs2ServerLen = 16 + 32
)

func deriveSessionV2(psk, nonceC, nonceS []byte, carrier uint16, dialer bool) *sessionKeys {
	salt := make([]byte, 0, len(nonceC)+len(nonceS)+2)
	salt = append(salt, nonceC...)
	salt = append(salt, nonceS...)
	salt = append(salt, byte(carrier>>8), byte(carrier))
	prk := hkdfExtract(salt, psk)
	c2s := hkdfExpand(prk, []byte("pingify/v2 c2s"), 32)
	s2c := hkdfExpand(prk, []byte("pingify/v2 s2c"), 32)

	// The length masks are never used in this mode; they are filled in so the
	// struct is always whole and nothing has to check before reading it.
	if dialer {
		return &sessionKeys{aeadFrom(c2s), aeadFrom(s2c), blockFrom(c2s), blockFrom(s2c)}
	}
	return &sessionKeys{aeadFrom(s2c), aeadFrom(c2s), blockFrom(s2c), blockFrom(c2s)}
}

func clientHandshakeV2(conn net.Conn, cfg *Config, carrier int) (*sessionKeys, error) {
	psk := cfg.key()
	buf := make([]byte, hs2ClientLen)
	copy(buf[0:4], hs2Magic)
	buf[4] = hs2Version
	buf[5] = roleByte(cfg.Role)
	binary.BigEndian.PutUint16(buf[6:8], uint16(carrier))
	binary.BigEndian.PutUint64(buf[8:16], uint64(time.Now().Unix()))
	if _, err := rand.Read(buf[16:32]); err != nil {
		return nil, err
	}
	m := hmac.New(sha256.New, psk)
	m.Write(buf[:32])
	copy(buf[32:], m.Sum(nil))

	conn.SetDeadline(time.Now().Add(15 * time.Second))
	if _, err := conn.Write(buf); err != nil {
		return nil, err
	}
	resp := make([]byte, hs2ServerLen)
	if _, err := io.ReadFull(conn, resp); err != nil {
		return nil, err
	}
	m2 := hmac.New(sha256.New, psk)
	m2.Write([]byte("pingify/v2 srv"))
	m2.Write(buf[16:32])
	m2.Write(resp[:16])
	if !hmac.Equal(m2.Sum(nil), resp[16:]) {
		return nil, errHandshake
	}
	conn.SetDeadline(time.Time{})

	return deriveSessionV2(psk, buf[16:32], resp[:16], uint16(carrier), true), nil
}

func serverHandshakeV2(conn net.Conn, cfg *Config, g *replayGuard) (*sessionKeys, int, error) {
	psk := cfg.key()
	buf := make([]byte, hs2ClientLen)
	conn.SetDeadline(time.Now().Add(15 * time.Second))
	if _, err := io.ReadFull(conn, buf); err != nil {
		return nil, 0, err
	}
	if string(buf[0:4]) != hs2Magic || buf[4] != hs2Version {
		return nil, 0, errHandshake
	}
	if buf[5] == roleByte(cfg.Role) {
		return nil, 0, errHandshake // both ends configured with the same role
	}
	ts := int64(binary.BigEndian.Uint64(buf[8:16]))
	if d := time.Since(time.Unix(ts, 0)); d > hsSkew || d < -hsSkew {
		return nil, 0, errHandshake
	}
	m := hmac.New(sha256.New, psk)
	m.Write(buf[:32])
	if !hmac.Equal(m.Sum(nil), buf[32:]) {
		return nil, 0, errHandshake
	}
	var nc [16]byte
	copy(nc[:], buf[16:32])
	if !g.accept(nc) {
		return nil, 0, errHandshake
	}

	resp := make([]byte, hs2ServerLen)
	if _, err := rand.Read(resp[:16]); err != nil {
		return nil, 0, err
	}
	m2 := hmac.New(sha256.New, psk)
	m2.Write([]byte("pingify/v2 srv"))
	m2.Write(buf[16:32])
	m2.Write(resp[:16])
	copy(resp[16:], m2.Sum(nil))
	if _, err := conn.Write(resp); err != nil {
		return nil, 0, err
	}
	conn.SetDeadline(time.Time{})

	carrier := int(binary.BigEndian.Uint16(buf[6:8]))
	return deriveSessionV2(psk, buf[16:32], resp[:16], uint16(carrier), false), carrier, nil
}
